/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240315-3","meetingId":"r06-c-budget","date":"2024年3月15日","dateIso":"2024-03-15","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を180件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年度品川区一般会計予算","agenda":"令和６年度品川区一般会計予算","exchanges":[{"speaker":"せりざわ委員","kind":"質問","question":"おはようあります。よろしくお願いします。３７５ページ、生徒指導対策費から、子どもたちの犯罪の防止という観点で、様々お伺いをしたいと思います。初めに、子どもたちの犯罪の被害防止のところからお伺いをしたいと思います。警察庁の調査では、昨年の１年間で、子どもたちの小学校等でＳＮＳを通じた犯罪被害というのが急増しているというのが、先日ニュースになっておりました。","respondent":"丸谷教育総合支援センター長","answer":"登下校中の犯罪につきましても、今、小学生であれば、まもるっちを身につけておりますが、そういったところで声かけ事案でありますとか、そういった何か危険を感じたらひもを引くというような指導は徹底しています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"今、お話いただきましたが東京都でも、自治体に向けても教職員に向けても、もしくは児童・生徒に向けても公開はされていますが、ＧＩＧＡワークブックとうきょうという教材を使っていて、なかなかこれも、ＳＮＳを通じて友達同士の犯罪、例えば写真を勝手に撮られているよ、などというところはたくさん書いてあるのですが、見知らぬ方にどういうふうにされて、ここからは犯罪ですよ。","respondent":"丸谷教育総合支援センター長","answer":"ただいまご紹介のありました、何か犯罪に巻き込まれた、もしくは巻き込まれたかもしれない、そんなとき、困ったときの窓口ということでありますけれども、例えば本区であれば、ＨＥＡＲＴＳに連絡を入れるということも考えられます。","voiceIndex":6,"id":"exchange-002"},{"speaker":"せりざわ委員","kind":"質問","question":"ＨＥＡＲＴＳ等、窓口のお話もいろいろいただきました。何かご見解あれば。もう１点、加害防止のところでもお話をお伺いしたいと思います。残念ながらまだまだ、犯罪を犯す子どもたちもいらっしゃって、そういった子どもたちに対して、学校側が再犯防止というところでどういった取組ができるのかお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"そういった地道な積み重ねを今後とも取り組んでまいりたいと考えております。","voiceIndex":8,"id":"exchange-003"},{"speaker":"せりざわ委員","kind":"質問","question":"初犯の防止というところでいうと、松本委員も弁護士でいらっしゃいますが、今、弁護士が国の補助金を使って、たしか自治体の負担ゼロで、様々、ＳＮＳを通じた、初めて手を染めてしまうケースというのをいろいろ講習されているというふうに伺っていて、品川区でもたしか何校か今やっていらっしゃるのかなと思うのですが。","respondent":"丸谷教育総合支援センター長","answer":"外部講師、例えば弁護士を呼んでの授業ということも大変有効かと考えておりますので、学校の要望に応じて、こちらとしても教育委員会としても支援をしてまいりたいと考えております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問","question":"おはようあります。本日もよろしくお願いします。私からは、３７７ページの市民科・各教科充実経費に関連して、防災教育についてお伺いしてまいります。そこで、まず、小・中・高校生に対する区の防災教育についての現状、取組についてお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"防災教育についてのお尋ねです。区立学校、小学校、中学校、義務教育学校におきましては、各学校で年１１回、８月を除く月１回、避難訓練を実施しております。地震や火災、またＪアラートや不審者対応など、学校が年間通して計画を立てて実施しています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"年間１１回の避難訓練、各校で毎月行われているということで、Ｊアラートも含めて行われているということ、各学校で訓練を行っていることを確認させていただきました。そこで、防災サイコロも含め、こういった公益社団法人や専門的講師等の授業をまだ実施されていない学校へ周知、紹介するなど、後押しを進めていただきたいと思いますが、区のお考えをお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"こうした様々な防災教育ができる、実施する事業者等ありますので、ご紹介いただきながら、有益なものは学校教育にも取り入れていけるように後押ししていきたいと考えております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひ前向きに進めていただければと思います。令和４年には、東京都教育委員会で作成の紙媒体の防災ノートが、デジタル教材として刷新されました。紙媒体のときよりも、解説動画がつけ加えられ、より活用されやすくなり、児童・生徒が１人１台端末の中で防災教育の教材として使用されていると思われますが、この防災ノートの各学校での活用状況等についてお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"１人１台タブレット端末の中に安全・安心のフォルダを用意しまして、こちらの防災ノートのデジタル版に直接アクセスできるような仕組みを整えております。各学校が実施しております避難訓練等の、そういった時期に合わせまして、活用を進めているところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"様々な授業の中で工夫をしながら、防災の横軸を入れながら進めていくことは非常に大変な労力だと思われますが、防災ノートの中での各教科に取り上げられなかった項目については、計画性を持って、ぜひ、毎月行っている避難訓練の後を活用して網羅できるように進めていただきたいと思いますが、この辺について、区の見解をお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"各教科におきましても防災教育を進めておりまして、例えば理科では、地震の単元でそういう災害についても学ぶといったようなことで、それぞれの教科で関連項目、年間計画を立てながら、各学校では実施しています。","voiceIndex":19,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"渋谷区の中学校や世田谷区の小学校では、Ｂ－ＶＲを使った防災教育が各自のタブレット端末で動画を視聴して実施され、首都直下地震の際のイメージと危険予知について実際に学ばれ、報道されています。ぜひ、こちらについても、防災教育の一環として、より一層の周知を進めていただきたく、活用していただければと思いますが、この辺のことについて、区の見解があればお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"次年度、中学生向けの教材を区でも作成するということで、関係課とも連携をしながら、中学生への防災教育の充実というのは努めていきたいと考えております。様々そういった有効な教材、教具出ておりますので、そういったものも注視しながら検討を進めていきたいと考えております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひ前向きにさらに進めていただければと思います。防災教育については、各学校での工夫により進められているという観点から、少なからず、各学校での格差が出てくると思われますが、この点をどのように把握して、どう解消していくのか、最後にこの１点だけお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"そこには、必ず指導する基本的事項というものを定めておりまして、それを基に年間計画を立てておりますので、各学校とも最低基準というものは確実にクリアしているというふうに捉えております。その中で、各校の工夫で、子どもたちへの指導の充実を図っているところです。","voiceIndex":23,"id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"最低基準の全体計画を基に把握されているということ、確認させていただきました。格差のある点については、周知での後押し等により改善して、さらなる全体的な防災教育の向上を図っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"山本委員","kind":"質問","question":"本日もどうぞよろしくお願いいたします。私からは、３７５ページの学校支援費、いじめ防止対策費について伺います。学校支援費に関連して、学級崩壊に対する対応について伺います。ある小学生の保護者の方から、学級崩壊についてのご相談を受けていました。区内の公立小・中学校で、現在把握している学級崩壊は何件あるのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"学級崩壊に具体的な基準がないため、件数としてお示しすることはできませんが、複数の学校で学級崩壊の状態にあるという報告は受けております。その中で教育委員会が介入しているケースもあります。","voiceIndex":27,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"学級崩壊が起こると、学校と教育委員会ではどう対応することとなっているのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"学校としては、可能な限り複数の教員で授業のサポートに入り、正常な学級運営ができるように努めているところです。場合によっては臨時保護者会を開き、保護者の協力も求めています。","voiceIndex":29,"id":"exchange-013"},{"speaker":"山本委員","kind":"提案","question":"お話をお聞きしますと、７月に校長先生が教育委員会に相談をし、教育委員会の教育アドバイザーや担当の方が学校を訪問し、学校に状況を確認したり、実際に児童、学級の様子を観察したりして、効果的な対応策について検討、提案をしてきたとのことでした。ＨＥＡＲＴＳや警察ＯＢの方々、地域ボランティアの方々に、発生後速やかに、連日サポートに入ってもらう仕組みはできないのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"地域の方にもご協力いただけるのであれば、大変ありがたいことだと考えております。そうした仕組みづくりにつきましては、学校のほうに提案することは可能だというふうに捉えております。","voiceIndex":33,"id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひそのようにしていただきたいと思います。それから、真面目に授業を受けたいと思っている生徒保護者の方々から、対象生徒を別室指導とすることの要望がありました。区のお考えを伺います。","respondent":"丸谷教育総合支援センター長","answer":"集団の中で授業妨害という形で表れておりますが、その子なりの何らかのＳＯＳだと捉えております。当該の児童・生徒から気持ちをしっかりと聞き取ることで、その後の支援につなげていくことが適切だと考えております。","voiceIndex":35,"id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"区のお考えも理解できます。常に別室は適切ではないと考えますが、改善が見られるまでは別室でしっかり個別指導をすることが、改善を促す生徒自身の成長のためにも、そして、クラス全体にとっても必要なのではないかと考えます。対象生徒の保護者が見に来るときにはおとなしくしていて、いないときに騒ぐという話を聞きました。区のお考えを伺います。","respondent":"丸谷教育総合支援センター長","answer":"大人がいるから、または、カメラがついているから、おとなしく真面目にしているということでは、本当の意味での子どもの成長にはつながらないと考えております。","voiceIndex":37,"id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"このように事実関係の確認を要する事態に限ってのモニタリングカメラの設置ルールの制定を要望いたします。先ほどご説明したとおり、６月に発生して、結局、状況が改善しないまま１２月まで続き、現在も完全には解決していないと聞いています。迅速に解決できるようにするため、ガイドラインづくりをするのがよいのではないでしょうか。区のご見解を伺います。","respondent":"丸谷教育総合支援センター長","answer":"前もって対応方針を決めておくことは必要だと考えておりまして、先日の校長連絡会でも、例えば、いじめが起こったとき、学校が虐待を把握したとき、また学級が落ち着かなくなってきたときに、どのように学校は対応するのか、４月当初の保護者会等の機会を捉えて。","voiceIndex":39,"id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"前もって対応方針を決めていくということが必要とお考えを理解いたしました。迅速に解決できるようにするため、学校現場の負担を軽減するため、有効な仕組みづくりを要望し、次の質問に進みます。続いて、いじめ問題について伺います。区長部局が入っても同じことです。個々のいじめ案件に対して、必要に応じて第三者が相談に乗れる仕組みが必要ではないかと感じましたが、区のお考えを伺います。","respondent":"丸谷教育総合支援センター長","answer":"例えば第三者ということであれば、本来は、教育委員会がその役割を担っており、学校と保護者本人との仲介を担うものだというふうに考えているところです。そういった第三者の立場であるということから、今後も保護者の理解を得るように努めていきたいと考えております。","voiceIndex":41,"id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"学校が解決できるときは学校に任せればよいと考えます。この問題でも、一番に考えないといけないことは、その子どもたちにとってその学校での時間が１度きりで戻ってないことです。問題が長期化しないよう、速やかにいじめ問題が解決できるよう、第三者の相談に乗れる仕組みの検討を要望し、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"３８１ページ、校内別室指導支援事業、３７１ページ、教育振興基本計画策定経費、３７２ページ、教育指導費、校則について伺います。質問ですけれど、校内別室登校支援の拡大なのですが、１月の文教委員会で審査された陳情でも要望もされていたものでもありますし、不登校児童・生徒の学びの選択肢を用意するという点で評価するものです。","respondent":"丸谷教育総合支援センター長","answer":"校内別室指導支援員の配置についてです。配置の想定としては、各学校に週５日配置の予定です。ですので、現在募集３０人程度と区ではしておりますけれども、各学校が独自に支援員を見つけてくるということもありますので、区としては３０人と、今は示しています。","voiceIndex":45,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"募集要項にあります、この、学校等において児童等に対し学習指導等の経験がある者とは何でしょうか、伺いたいと。指導支援員というのは、資格は問わないということになるのでしょうか、伺います。だとしたら、支援員にとっての必要な資質やスキルというのは何だとお考えなのでしょうか。どのような研修を行う必要があると考えているのかというものも併せて伺います。","respondent":"丸谷教育総合支援センター長","answer":"研修についてですけれども、全体の集めての研修ということは考えてはいるところではないのですが、各学校には不登校担当の教員配置も進めるよう今、学校には働きかけをしておりまして。","voiceIndex":49,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、別室を用意しましたで終わりというのは、もちろん、それではないと、言うまでもないと思いますので、その中身というのが本当に子どもにとっていい環境かどうかになるかというのは本当に大事だと思っているのです。そういうものを求めたいと思います。質問ですけれど、指導員の専門性の構築、その担保についてもう一つ、もう少し伺いたいなと思うのですが、よろしくお願いいたします。","respondent":"丸谷教育総合支援センター長","answer":"そういった意味では、学校管理職経験の方等は非常に有効かというふうに考えておりまして、学生に向けては、そうした学校、現在の管理職からの指導ですとかそういったもので担保はしていきたいというふうに考えております。","voiceIndex":51,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"教育振興基本計画なのですけれど、プレス発表などにはいろいろ目的なども書いていますが、行政計画と書いてあるのですけれど、この教育委員会、教育の独立性と照らしてこの基本計画の関係というのはどういうふうになっているのか、行政計画という、この意味というのを教えてもらいたいのですけれど、それが一つと、あと代表質問でも指摘し求めてきたのですが。","respondent":"宮尾庶務課長","answer":"教育振興基本計画に関するお尋ねです。計画の意味ですけれども、こちらの計画は、教育基本法、こちらに、各自治体に策定を努力義務として課しているものです。これを受けて、この教育基本法に定める行政計画としてこのたび、策定を予定しています。","voiceIndex":53,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり、この掲載している場所も学校によってばらばらで、見つけられた学校も含めて、このページ内の検索欄で校則と検索しても出てこないという状況でした。私が検索してみたらそんな状況だったのですが、区立学校全体で公開しているというご答弁でしたけれども、区教育委員会としては実際に、どんなふうに公開しているのだろうかということを確認する作業というのはしたのでしょうか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"ただ、今お話あったように、なかなかその掲載場所が学校によってまちまちということも確認しておりますので、そういった意味では、保護者や地域の方がご覧いただけるような工夫、改善を学校に求めるということで、引き続き次年度に向けて周知してまいりたいと考えております。","voiceIndex":55,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"代表質問では、実際に校則を見直している学校数も伺ったのですが、答弁は、児童・生徒だけでなく、保護者、地域の方の意見も踏まえて行うよう学校に働きかけており、中学校や義務教育学校後期課程を中心に実施しているところという答弁にとどまったのですが、数を把握しないということなのですか。実施数も含めて、校則見直しの、主に中学でもいいですけれど現状について改めて伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"子どもの意見を聞いて校則を見直した学校の件数ということですけれども、中学校、義務教育学校それぞれ９校、６校ありますが、全ての学校において、子どもたちの意見を聞いて校則の見直しを図っているということで確認ができております。","voiceIndex":57,"id":"exchange-025"},{"speaker":"安藤委員","kind":"提案","question":"提案したいのですが、各学校において毎年必ず、こうした教育効果あるわけですから、子どもたち、教師、保護者が、この意見表明権を４つの基本原則に備えている、子どもの権利条約を学習する機会を持つことと、そしてそれとセットで、校則の見直しを３者の協議によって決めることを、毎年定式化、義務化と言うと少し言葉強いのですけれど、してはいかがかと思うのですが、いかがでしょうか、伺います。","respondent":"丸谷教育総合支援センター長","answer":"各校が学校の決まりについて紹介し合っていましたが、その中で子どもの権利条約という考え方につきましても、区教育委員会のほうから紹介させていただいて、これからも生徒会活動を充実させていくようにと紹介したところです。","voiceIndex":59,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"毎年見直しというのを定式化したらどうかという質問に対してはいかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"失礼いたしました。毎年必ずということですけれども、そういった機会を捉えて進めていくように働きかけてまいります。","voiceIndex":61,"id":"exchange-027"},{"speaker":"筒井委員","kind":"提案","question":"よろしくお願いします。地域の歴史・文化、和楽器による音楽教育なのですけれど、私は提案として、民謡の取り入れということをぜひやっていただけたらいいかなと考えております。民謡は、今現在シルバーセンターとか、品川区では高齢者向けの事業に取り入れられていると考えておりますけれども、ぜひ教育にも民謡の活用ということをぜひ、提案していきたいのですが、区のお考えはいかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"その民謡の歴史的な背景でありますとか、地域の状況も含めまして、合わせて行っているところです。","voiceIndex":64,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願い申し上げます。それがどういう原因でお声が広がっているかというと、やはり教員１人に対する負担が大きくなっていると。それでまずお伺いをしたいのは、スクール・サポート・スタッフ、現在これ品川区でも配置をされているかと思いますけれども、スクール・サポート・スタッフの効果、どのように今、区としては評価をされているのでしょうか、お聞かせください。","respondent":"中谷指導課長","answer":"非常に教員の負担が減ったということは全校から寄せられておりまして、こちらについては継続してやっていきたいと考えています。","voiceIndex":66,"id":"exchange-029"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。続いて、エデュケーション・アシスタントなのですけれど、今後、品川区ではまだ配置をされていないかと思いますが、今後のエデュケーション・アシスタントの品川区での配置予定と、これはエデュケーション・アシスタント、小学校１年から３年という範囲が限定されているのですけれども、小学校１年から３年となっていることに対する評価についてお聞かせください。","respondent":"中谷指導課長","answer":"エデュケーション・アシスタントにつきましては、来年度、まず小学校の２校を指定させていただきまして、試行実施という形で取り組んでまいりたいと考えています。","voiceIndex":68,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。よろしくお願い申し上げます。それでやはり、一方で負担軽減と同時に、正規の教員を増やしていくというのは当然正攻法として必要かなと考えておりますけれども、私はこれから社会人採用が鍵だと考えておりまして、やはりもう一度教員になりたいという方、世の中にいらっしゃるのかなと考えておりますが、区のお考えというのはいかがでしょうか。","respondent":"中谷指導課長","answer":"引き続き、このような形で社会人の方も多く取り込めるようにやってまいりたいと考えています。","voiceIndex":70,"id":"exchange-031"},{"speaker":"せらく委員","kind":"提案","question":"不登校支援ガイドブックについて伺います。先日、事前に伺ったところの確認になりますが、不登校支援ガイドブックは、不登校になってしまった児童・生徒へ学校を通じてお渡しするもので、全員に配付するものではないというふうに想定しているとお聞きしたのですけれど、確認させてください。その後、ご検討のほうをされたことがあれば教えていただけますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"名称についてですけれども、登校支援だけではなくて例えば、仮想空間を利用したものですとか、そういった校外のこともフリースクールも含めてのガイドブックになりますので、何かいい名称というのは今後考えていきたいと考えております。","voiceIndex":73,"id":"exchange-032"},{"speaker":"せらく委員","kind":"質問・要望","question":"恐らくどこに相談しても受け付けていただけるのだと、つなげていただけるのだと考えていますが、そういった点も考慮して、登校支援のガイドブックには作成していただきたいというふうに思っております。不登校児童・生徒の次の質問になります。当区ではそういった保護者の集まりなどは開催していますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"これはマイスクール利用者だけではなくて、不登校児童・生徒の保護者を対象にしております。今年度は１１月に３日間行いまして、進路説明会や、その後の懇談の場ということで設けているところです。","voiceIndex":75,"id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"１１月に３日間開催しているということなのですけれども、マイスクール利用者以外も不登校でお悩みの方が参加できるということで、学年だとかそういうところの制限はありますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"特に学年の制限は設けてはございません。","voiceIndex":77,"id":"exchange-034"},{"speaker":"せらく委員","kind":"質問・要望","question":"分かりました。今回、不登校のポータルサイトなども開設するということなので、オンライン交流会ですとか、頻度もオンラインで、その１１月だけではなく、不登校が増える夏休み明けだとか、学年が変わる３月なども視野に入れていただけたら助かるのではないかと思います。こちらは要望です。これは３年生のお母さんから聞きました。こちらについてはどのように認識していらっしゃいますか。","respondent":"丸谷教育総合支援センター長","answer":"残りは、７校が３年生から、６校が４年生からということで、学校にもばらつきがあるということで、先日校長連絡会でも周知をして、今の生命の安全教育と関連性を持った形での着替えというものを実施するよう周知したところです。","voiceIndex":79,"id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。周知していただけたということで、着替えという場面も学校の生活の中で大事な時間であるというふうに思いますので、引き続き１年生から全校でできるようにお願いしたいと思います。今回は教育長と委員の方のコラムが、すてきな笑顔の写真とともに掲載されておりまして、こちら「教育のひろば」の内容については誰がどのように決めているか伺いたいと思います。","respondent":"宮尾庶務課長","answer":"「教育のひろば」、広報紙に関するお尋ねです。こちらの記事の内容についてですが、基本的には教育委員会事務局内の各課から、保護者の方にお配りするという前提で記事を募りまして、最終的に、教育長ともご相談をして事務局内で決めさせていただいているです。","voiceIndex":81,"id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"事務局と教育長と決めていらっしゃるということです。今回、その教育長のお顔と委員の方の思いが拝見できまして、すごく保護者として安心感があったので、ぜひ、年２回の発行なので、毎号どなたか委員の方の思いが聞けたらいいなというふうに思いまして、今回質問させていただきました。引き続きよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"私から、３７７ページ、しながわ教育推進事業、ファイナンス・パーク、３８７ページ、教材教具等経費についてお伺いいたします。１点目に、ファイナンス・パークについてお伺いいたします。２点目に、教材教具等経費についてお伺いいたします。そこで将来的なお話なのですけれども、今後民間試験の補助については英語検定のみというお考えでしょうか。は学力定着度調査の状況を確認させてください。","respondent":"丸谷教育総合支援センター長、柏木学務課長、中谷指導課長","answer":"今後ですけれども、現在そのオンライン、デジタルで行っていますので、適宜、改定が可能であるということで事業者とも確認ができていますので。本区で行っております、英検チャレンジ事業ですけれども、こちらは品川区が平成１８年度から、１年生からの英語科を実施するという。学年が上がる中で、理科や社会で目標を下回る結果などがありまして、分析を行いながら授業改善を進めてまいります。","voiceIndex":85,"id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"英語検定については、現在、今までその英語に品川区は力を入れてきたということなのですけれども、将来的にはぜひ検討していただきたいというふうに思いますので、将来的な部分はぜひ要望させていただきたいというふうに思います。学習指導要領の方向性について、今年から本格的な検討が始まるかと思いますが、ＰＩＳＡの結果がどのような影響を及ぼす可能性があると分析していますでしょうか。","respondent":"中谷指導課長","answer":"未来を切り拓く力を持つ児童・生徒の育成を目指しております。学校が育てたい子どもの姿を明確にして、共有をしながら、９年間の一貫教育を通じて、社会にある様々な課題解決にも、他者と協働しながら参画できる子どもたちを育ててまいりたいと考えています。","voiceIndex":89,"id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"与える教育と引き出す教育のところに、あと、子どもの遊びと学びの関係とフロー体験のところもちょっとお聞きしたいところがあったのですけれども、今回は時間がありませんので、ぜひ、私もまだ研究途中なのですが、フロー体験というのが子どもにとってすごく幼児教育等の文脈でも可能性を少し感じているところがありますので、ぜひ研究していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-040"},{"speaker":"澤田委員","kind":"質問","question":"本日もよろしくお願いいたします。３８７ページ、ＩＣＴ支援員経費について、時間があれば３７５ページ、いじめ等防止プログラム経費について質問いたします。品川区では、令和３年度からＩＣＴ教育が本格的に始まりましたが、教員の先生によっては、ＩＣＴ機器の操作やＩＣＴを活用しての授業が得意な方、苦手な方といらっしゃいます。ＩＣＴ支援員の方の支援の内容を具体的に教えてください。","respondent":"柏木学務課長","answer":"ＩＣＴ支援員の支援の内容ですけれども、主な内容になりますが、授業で使用するＩＣＴ機器やソフトウエアの準備ですとか片づけ、動作環境の確認、児童・生徒に対する操作の支援、ＩＣＴ機器を活用した授業を行うために学習活動の狙いに沿った提案。","voiceIndex":95,"id":"exchange-041"},{"speaker":"澤田委員","kind":"質問","question":"操作方法だけでなく授業支援等、様々な支援をされていることが分かりました。今ご説明いただいたような支援員の方たちのサポートにより、先生方の負担も軽減されていることと思います。先生方から、それらのサポートについて定期的にヒアリング等はされているのでしょうか。区として把握されていることがあればお聞かせいただければと思います。","respondent":"柏木学務課長","answer":"直接、教員のほうからの意見聴取というのは特に何か行っているものではございませんけれども、支援員の定例会がございまして、そちらのほうで各学校の状況等はその中で報告をされているものになります。","voiceIndex":97,"id":"exchange-042"},{"speaker":"澤田委員","kind":"質問","question":"その定例会などから上がってきた意見の中で、実際に変わったことなどは何かあったりするのでしょうか。","respondent":"柏木学務課長","answer":"その支援の方法について、支援員の中でうまくいったこと、あとうまくいかなかったもの、そういうものの共有がされますので、そういう部分で、支援員全体で意識の共有と改善点が見えてきている、それに基づいてまた改善していくという状況です。","voiceIndex":99,"id":"exchange-043"},{"speaker":"澤田委員","kind":"質問","question":"支援員の声を先生方の授業に活かしているということは分かりました。その、週１回、今、巡回支援が行われている中で、ほとんどの学校ではそれで十分対応できているということを伺っておりますけれども、その中でもやはりどうしてもＩＣＴ機器の操作等が苦手で、週１回以上の支援を必要とされている先生がいらっしゃるというお話もお聞きしています。","respondent":"柏木学務課長","answer":"ただ、今後進めていく上で、やはり学校によったり、また、先生によったりというのは出てくるのかなというのは想像できますので、今後、その必要な学校、不必要な学校はないと思いますけれども、少なくてもいいよという学校がもしありましたら。","voiceIndex":101,"id":"exchange-044"},{"speaker":"澤田委員","kind":"質問","question":"先生の負担を緩和することができれば、後々子どもたちに返ってくると思いますので、どうぞよろしくお願いいたします。同様の理由で引っ越しを決断されたという話もよく伺います。ＩＣＴに関連することで、先生しか行えない、支援員の方は行えないというようなサポートもあるのでしょうか。もしあるような場合は、どのような業務内容なのかということも教えていただけますでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"例えば教員でしかできない業務として、成績の処理ですとか、授業そのものについては教員でしか行えないというふうに考えております。","voiceIndex":103,"id":"exchange-045"},{"speaker":"澤田委員","kind":"質問","question":"以前、ＩＣＴ支援員の方たちから、先生の負担を減らすためにできることがあれば力になりたいというようなことを伺ったことがあります。今、教えていただいたことの中でも、ちょっと個人情報の保護の観点からどうしても先生自身が行わなければならない業務もあるかとは思います。ＩＣＴ教育を進めていく上でそれも大事なのではないかと思いますが、区としての見解をお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"そうした中で、この業務は任せよう、お願いしようということが進んでいくと思いますので、区教育委員会としてもそうした周知に努めていきたいと考えております。","voiceIndex":105,"id":"exchange-046"},{"speaker":"澤田委員","kind":"質問","question":"ぜひ、教員の先生方にも、どこが任せられるかどうかというのも、例えばヒアリングなどして進めていっていただければと思います。そのような場合、その修理代金は、区が負担する場合と保護者が負担する場合があるのでしょうか、教えていただけますでしょうか。","respondent":"柏木学務課長","answer":"タブレットの故障時の対応ですけれども、こちらのタブレットはリース契約をしていまして、その中では保守契約というのも結んでおりますので、基本、故障等につきましては保守の中で行われるということで保護者の負担は基本は求めないこととなります。","voiceIndex":107,"id":"exchange-047"},{"speaker":"澤田委員","kind":"質問・要望","question":"保守契約があって保護者には求めないということなのですけれども、それは区の財源も使っていないというか、最初に申し込むときに契約に入っているという形なのですか、お願いします。","respondent":"柏木学務課長","answer":"それと、すみません、先ほどの件で、フィルムの件がございましたが、フィルムはリースの中には入っていない、消耗品という扱いでありますので、そこら辺についてはもしかすると保護者に代替を買ってもらうという場合があるかもしれません。","voiceIndex":109,"id":"exchange-048"},{"speaker":"澤田委員","kind":"質問","question":"リースのときの保守契約で、特に保護者にはかからないということですけれども、やはりｉＰａｄを大事に使うような精神というか、ＳＤＧｓということでもあるかもしれませんが、その心を育てる意味でも、例えばＩＣＴ支援員の方に、多分一番最初のときにいろいろご説明をされるとは思うのですが、度々壊してしまうような児童などについては。","respondent":"柏木学務課長","answer":"子どもたちは本当に大事に使ってありますが、あまりそういう故障等の問合せ、壊してしまったというのは少ないかなというふうに思ってありますが、当然授業で活用するツールの一つになりますので、年度当初等にその部分は。","voiceIndex":111,"id":"exchange-049"},{"speaker":"澤田委員","kind":"質問","question":"続きまして、３７５ページ、いじめ等防止プログラム経費について質問いたします。４月には教員向けの段階別研修の実施、各調査ツールの試行開始、５月にはいじめ予防授業を開始、各調査ツールの本格実施が予定されています。これらの効果測定は行われるのでしょうか。もし行われる予定であれば、その方法やスケジュール感など何かお決まりのことやお考えがあればお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"不登校にも効果があるということで考えておりまして、その出現率の低下ということも考えております。今後また、事業者とも詰めていきながら、どのような形で効果検証ができるかということも考えていきたいと考えています。","voiceIndex":113,"id":"exchange-050"},{"speaker":"新妻委員","kind":"確認","question":"私からは３７１ページ、就学事務費から関連として、学校選択制について、３８１ページ、不登校ポータルサイト等、また、校内別室指導支援事業の関連として、不登校全般についてお伺いをいたします。学校選択制についてです。行政評価シートでは、ここ数年の学校選択制のこの希望者数が減少しているということを確認いたしました。そこで、２０２４年度の学校選択制の希望申請数と今後の動向予測を伺います。","respondent":"柏木学務課長","answer":"２０２４年度入学予定の学校選択の状況ですが、小学校、義務教育学校前期課程では、希望申請数が５１９件、希望申請の率で言いますと１５.９％となっています。中学校、義務教育学校後期課程につきましては、希望申請数が５７４件、希望申請の割合は２０％となっています。","voiceIndex":117,"id":"exchange-051"},{"speaker":"新妻委員","kind":"質問・要望","question":"待機児童の待機の方の優先順位は、兄弟枠、次に隣接する通学区域、次に旧ブロックと、そのように認識をしております。このようなことから、兄弟は同じ学校に通わせてほしいと、この議会でも要望してまいりましたが、２０２４年度の学校選択制において、兄弟枠を申請された方の状況を伺います。兄弟枠はどれぐらいいらっしゃって、その方がこの結果どのようになったのか、教えてください。","respondent":"柏木学務課長","answer":"兄弟枠の状況です。２０２４年度入学予定者は、小学校と義務教育学校の前期課程につきましては、兄弟枠で申請された方は１５３人となっています。中学校、義務教育学校後期課程につきましては３３人となっています。","voiceIndex":119,"id":"exchange-052"},{"speaker":"新妻委員","kind":"質問・要望","question":"不登校支援について伺います。そして、支援員に関しましては、ホームページで募集がされておりまして、この募集期間が延長になったという経緯があったので、３月２９日まで募集ということでありますが、今しっかりこの支援員が３０名プラス学校での募集ということになっておりますが、今現状、全校に配置をするに当たっての、この人数が充足をしているのか、確認をさせていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"支援員の募集についてですけれども、現在３０名を目途に行っておりますが、おかげさまで２０数名のエントリーがあったということで確認をしております。４月にまだ少し時間ありますので、何とか４月から始められるような配置を進めてまいりたいと思っています。","voiceIndex":121,"id":"exchange-053"},{"speaker":"新妻委員","kind":"質問・要望","question":"よろしくお願いします。その中で一つ、この人員組織体制を整備するということを教えていただいたのですけれども、校長先生の下で、校内の中には様々な組織体があると思いますが、川西市では、そこに不登校対策、そして、フリースクールの運営ということで、先生がそこにしっかりと組織の中で位置づけられていて、担当の先生がいらっしゃって組織運営をしていると、そのように伺いました。","respondent":"丸谷教育総合支援センター長","answer":"校内別室指導支援員が校内別室の運営というものを任されていくわけですけれども、校内にはその担当教員の配置も、各学校に今、なるべく行うようにということで周知をしています。そうした支援員と教員が連携をしながら、充実に努めてまいりたいと考えております。","voiceIndex":123,"id":"exchange-054"},{"speaker":"新妻委員","kind":"確認","question":"確認をさせていただきました。そして、出席扱いについて改めて確認をします。今回この別室支援員が配置をされるということで、利用者が増えてくると思われます。川西市でも言っていたのですが、そこに来る子たちというのは、やはり向上しているということで、行きづらい学校が行きやすくなったというお声が多くあると。","respondent":"丸谷教育総合支援センター長","answer":"校内別室を利用された児童・生徒、またメタバース空間に出席をして学習支援等を受けた児童・生徒につきましては、出席扱いとするということで確認をしています。","voiceIndex":125,"id":"exchange-055"},{"speaker":"新妻委員","kind":"意見","question":"ぜひ、ご尽力をいただきまして、不登校が悪いとは私は思いません。多様な学びの場があるということが重要でありまして、それぞれの個性に合った学びができるような品川区の先進的な教育をまた推進していただければと思います。すみません、時間がなくなってしまいましたので、以上で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":127,"id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問・要望","question":"品川区の調査検討委員会、こちらには保護者、地域の代表の方がいらっしゃいますが、こちらの人選はどのように行っているのでしょうか。教科書の研究評価におきましては、調査員個人の主観や感想ではなく、項目ごとに教科書の特徴が一覧表にまとめられているのが非常に分かりやすいと評価しておりますが、この項目自体はどのような基準で決められているのでしょうか。以上３点をお聞きします。","respondent":"丸谷教育総合支援センター長","answer":"教科書の調査検討委員会の地域の方等の人選についてですけれども、こちら区教育委員会のほうで人選を行っているところです。","voiceIndex":131,"id":"exchange-057"},{"speaker":"おぎの委員","kind":"質問・要望","question":"調査委員選任においては、区民の誰もが納得するような透明化を図っていただきたいと思います。資料の項目の、こちら設定基準は必要な項目ということで理解いたしました。しかし、傍聴に来られた方が分かりにくいとの意見は一理ありますので、何らかの工夫は必要かなと思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"教科書の選定に当たって、その公平性を担保するということで、Ａ、Ｂ、Ｃという記号を使用しています。一方で、他自治体で教科書会社を挙げて採択しているという自治体もありますので、今後その辺りは研究してまいりたいというふうに考えているところです。","voiceIndex":133,"id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"非常にこれ、区民の方からも関心の高い事業ですので、皆さんに分かりやすいように、また、かつ公平性を保った形で続けていっていただきたいと思います。」とあります。未来ある子どもたちの学びのために、この教育基本法、こちらにのっとり、我が国の歴史に対する愛情が詰まった教科書をしっかりと選んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-059"},{"speaker":"ひがし委員","kind":"確認","question":"本日もよろしくお願いいたします。最初に、特別支援教育費の中から就学相談について伺います。行政評価を確認させていただきました。年々就学相談の参加者も増えてきており、需要が高まっていることが確認できます。今年度の実績、そして需要の高まりを受け、受付方法、相談体制など、充実を図っていく必要があると考えますが、結果を踏まえた本区における就学相談の今後の展開について伺います。","respondent":"唐澤特別支援教育担当課長","answer":"ただ、就学先の決定につきましては、お子さんや保護者の意向を尊重して実施していくことになっております。この就学相談の広報につきましては、区の広報やホームページ、または就学前教育の関係課や施設への情報提供や、説明会を実施するなどして周知に努めております。","voiceIndex":137,"id":"exchange-060"},{"speaker":"ひがし委員","kind":"質問・要望","question":"予約方法がウェブになったと聞いて大変うれしく思っております。就学相談については、保護者そして児童のニーズに合わせて引き続き充実するように要望をします。就学相談に合わせて、転学相談についても整備する必要があると考えます。品川区、現状、転学相談というのはどのような形で行っているのかお聞かせください。","respondent":"唐澤特別支援教育担当課長","answer":"転学相談につきましては、一旦就学した先の学校のほうで、やはりいろいろな相談、保護者と学校が協議をして、その結果、転学というような形になりましたら随時転学相談の受付を実施しています。","voiceIndex":139,"id":"exchange-061"},{"speaker":"ひがし委員","kind":"意見","question":"品川区のホームページは就学相談、すごく充実しているなというふうに評価しておるのですけれども、転学相談についての記載が見つからず、他区と同じような形で対応はしっかりしてくださっているとは思うのですが、就学相談せっかくやってくださっているということで、転学相談も併せてそのページに記載していただいて相談できる仕組みというのをつくっていただければなというふうに思うのですけれども。","respondent":"唐澤特別支援教育担当課長","answer":"就学相談、転学相談ともに、区民の方、保護者の方に周知することが重要だと考えておりますので、引き続きその周知については検討研究してまいりたいと考えています。","voiceIndex":141,"id":"exchange-062"},{"speaker":"ひがし委員","kind":"質問","question":"教育支援経費について伺います。「働きがいを持って働いていますか」というような質問に対し、７０％が「そう思う」と回答しております。過酷な労働環境から、なかなか将来の不安が払拭されず転職をしている方も多いというふうに伺いました。チームとしての学校体制整備が必要と考えますが、区としてどのような取組をしているのか、また、チーム学校に対する区の見解について伺います。","respondent":"中谷指導課長","answer":"やはり、精神的にも余裕を持って業務ができ、それが持続可能な学校経営につながるというふうに考えております。こういった事例を共有、推奨するとともに、既に実践している学校の取組の成果をこれからも継続して、把握して、共有をしてまいりたいと考えています。","voiceIndex":143,"id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"土曜の授業について、品川区は１４回から８回に減らしたというふうにお伺いしております。続けていきます。品川区、庁舎内に電話録音機、次年度４０台ほど入れるというふうに伺っております。そのようなものを学校でもぜひ取り入れていただきたいというようなご意見だったりとか、機械採点を導入してほしいというようなお話を伺っておりますので、それぞれ見解について聞かせていただければと思います。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"一部の保護者から、土曜日の習い事に通わせにくい、教員からは、振替が取りにくいといったことで、校長会とも調整をしてこの結果に至っております。今後ですけれども、他自治体のところを見ながら検討していきたいと考えております。庁内で来年度試行実施ということで、まずはそちらの効果も見ていきたいなと考えています。もう一つ、学校の電話交換機がその録音に対応できるかどうかというのもありますので、そこら辺のほうの調査等も必要と考えています。","voiceIndex":145,"id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"３８７ページ、教材教具費より、学用品の無償化について伺いたいと思います。この学用品の無償化ですが、施政方針で森澤区長より、義務教育に係る経済的負担の軽減という説明がありました。ぜひ義務教育の完全無償化へ、自治体として大きな一歩を踏み込んでいただきたいと考えています。今回の学用品無償化は義務教育の無償化に向けた自治体独自の対応なのか伺いたいと思います。","respondent":"柏木学務課長","answer":"しかしながら、憲法のほうではもちろん義務教育はこれを無償にするということはありますけれども、各自治体独自の事業で実施することは、こちらのほうは財源も含めて少し限界があるのではないかと考えています。","voiceIndex":150,"id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"伺ったのは、今回の対応は憲法が定める義務教育は無償とすると、その要請に対して、自治体としてその一歩を踏み込んだ目指すものなのかどうかを伺いたいと思います。もう一点、本来は義務教育ですから、財源は国が保障すべきだと考えています。国や東京都に対して財源を求めているのか、求めるべきと思いますが、いかがでしょうか。","respondent":"柏木学務課長","answer":"財源を国等に求めていくのかです。様々な機会、特別区の教育長会ですとか区長会等を含めまして、そういうことは求めていくことも可能と考えています。","voiceIndex":152,"id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど述べたとおりなのですけれども、どうもこの理念のところがはっきりしないところがあるのです。別のほうから伺うと、その憲法が規定する義務教育の無償化の範囲はどこまでと考えているのか、授業料と教科書以外どこまでと考えているのかも伺いたいと思います。財源についても求めていくことは可能ということでしたが、ぜひ私はやはり求めていただきたいと思うのですけれども、改めていかがでしょうか。","respondent":"柏木学務課長","answer":"それと、国等に財源を求めることにつきましては、特別区の区長会ですとか教育長会、品川区１区だけの話ではございませんので、そこでほかの区とも足並みをそろえて、必要があれば求めていくということは、繰り返しになりますが可能ではあります。","voiceIndex":154,"id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"財源については可能だということであれば、ぜひ国や都に求めていただきたいと、ここは要望しておきたいと思います。憲法の規定のこの無償化の範囲について、できる限り無償化を進めていきたいというお話でありました。なぜ伺ったのかというと、新聞報道で森澤区長が予算案の発表の記者会見で、憲法で義務教育は無償とする原則が明記されている。社会全体で子育てを支えていきたいというコメントがありました。","respondent":"柏木学務課長","answer":"改めて品川区としましては、それに加えて、当然自治体でやれる範囲はありますけれども、給食費と今回の補助教材を無償にするという形で、できる限りのことをしているものです。","voiceIndex":156,"id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"いいことをやっていると思いますので、ぜひ堂々と主張していただいて、全国に広がっていければいいと考えています。今回は学校で同じ金額、子どもがかかるものは無償化というものが対象になっておりますので、この卒業旅行と修学旅行についても教育の一環として、ぜひ無償化していただきたいと思いますが、いかがでしょうか。","respondent":"柏木学務課長","answer":"修学旅行等の無償化の件ですが、まず教育委員会といたしましては今年度から実施している学校給食の無償化と、来年度予定しております補助教材の保護者負担軽減事業、まずはこの２つについてしっかりやっていくと。","voiceIndex":158,"id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"は一歩ということで、ぜひ無償化の対象も広げていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-070"},{"speaker":"えのした委員","kind":"質問・要望","question":"私からは、３８３ページ、部活動地域移行等推進経費についてお伺いします。ＷＨＯ（世界保健機関）の憲章ではウェルビーイングを使用しています。子どもたち、指導者、保護者等が個人の人生として、そしてチーム、クラブ、組織が社会の役割として、スポーツのできる環境が幸せで持続可能な取組、新時代の世代につなぎ、連携した新たな仕組みを要望し、ぜひ前向きなご答弁を願い、ご質問いたします。","respondent":"中谷指導課長","answer":"ラグビー部につきましては、７月に体験会をやりまして、９月から１１月の土曜日の期間、そして水曜日にも開催ということで全２０回。ホッケー部につきましては１０月に体験会を行いまして、１２月から２月の期間で日曜日と木曜日に開催で、全１６回を予定しています。","voiceIndex":162,"id":"exchange-071"},{"speaker":"えのした委員","kind":"質問","question":"本当にこれは通常学校ではできない種目です。８０名全員受け入れられるような会場が見つかるよう願っております。地域の保護者の方にも伺いましたが、やはり年間を通してもっと好きな種目の部活動だけをやりたい子どもたちが多くいると感じておりますけれども、なぜ継続して２学期、３学期にできないのか、またしないのか、理由があればお知らせください。","respondent":"中谷指導課長","answer":"令和７年度まではこのような形態で進めまして、またそのあと効果を検証して見直してまいりたいと考えています。","voiceIndex":164,"id":"exchange-072"},{"speaker":"えのした委員","kind":"質問・要望","question":"そちらもほうもぜひご検討していただきたいと思います。続いて、部活動地域移行民間委託の契約が４月から開始されますが、学校側から部活動の種目を選べると。そこでお伺いしますが、現状、既に学校側から希望する部活動は挙がっていますでしょうか。人気の多い種目など、選択理由も分かればお知らせください。","respondent":"中谷指導課長","answer":"運動部では、硬式テニス部や卓球部などの球技系、陸上部が複数の学校から出ております。文化部では、吹奏楽部やクッキング部などとなっております。","voiceIndex":166,"id":"exchange-073"},{"speaker":"えのした委員","kind":"質問・要望","question":"テニス、卓球、クッキングというのは面白いですよね。吹奏楽部、これは全校にあると思います。学校ごとに様々な理由があるとは思いますけれども、このニーズが高いことは理解いたしました。スポーツは区内に各種団体が存在しますが、文化系ですね。演劇なども含めまして、そういった団体もあるのでしょうか。全ての種目に指導員がつけられるような取組を要望しますが、区のご見解をお知らせください。","respondent":"中谷指導課長、丸谷教育総合支援センター長","answer":"そういった協議の延長線上として、学校と結びついていただくというようなことができればと考えています。部活動支援につきましても、様々な部活動に配置できるような考えです。","voiceIndex":168,"id":"exchange-074"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。今、部活動指導員のほうのお話が出ましたけれども、私はこれは文教委員会の際にも質問いたしましたが、部活動指導員になるには部活種目の資格などをお持ちの方が指導員になれる、または区独自の研修を受けることによって指導員資格が授与されるなど条件があるのか、区のご見解をお知らせください。","respondent":"丸谷教育総合支援センター長","answer":"任用に当たっては、競技等の専門性だけではなく、生徒への指導が適切に行える人物かどうかを面接によって確認をしております。年度当初に部活動顧問や部活動指導員を対象とした部活動指導者講習を行っておりまして、指導者としての資質の向上を図っているところです。","voiceIndex":171,"id":"exchange-075"},{"speaker":"えのした委員","kind":"確認","question":"面接もあるとのことで確認が取れました。私も日本陸上競技連盟の公認ジュニアコーチの資格を持っておりますが、やはりまず子どもたちの安全のために安全講座など、こういった面も重要だと考えておりますので、そういった取組をしっかりとしていただけると安心に存じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-076"},{"speaker":"つる委員","kind":"質問","question":"よろしくお願いします。３７１ページ、教育振興基本計画策定経費と、３８２ページの図書館費に関連して伺っていきたいと思います。そもそも冒頭、教師の労力を最小化して子どもの活動力を最大化する。そうした問題意識を持って質疑ができればと思います。冒頭、そもそも「きょういく」とは、また教師とは何でしょうか。教えてください。","respondent":"宮尾庶務課長","answer":"教育基本法と関連の法律等に規定されたこと、それらの目的を事務局としてしっかりと遂行していく、履行していくということだと考えています。","voiceIndex":175,"id":"exchange-077"},{"speaker":"つる委員","kind":"提案","question":"大人や社会が総出で子どもの教育に関わり、多様な子どものニーズに応えるチーム学校を確立し、多様で専門性が高い教職員の活躍を促進することが必要だということで質問を挙げておりましたけれども、こうしたいわゆるこども未来戦略等にある、また今後策定する教育振興基本計画、また既存の指導要領なども含めて、品川区の公教育の体制について、今現在どのようにお考えであるかを教えてください。","respondent":"宮尾庶務課長","answer":"令和６年度に策定を予定しております教育振興基本計画、ここにおいて、これまで品川区が取り組んでまいりました各種の教育施策、これらを今回この計画を策定することによって総合的に、また体系的にお示しをして。","voiceIndex":177,"id":"exchange-078"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろな議論、また観点、また深み、こうしたこともやりながら、来年度教育振興基本計画の策定とか、またいわゆるこども未来戦略で言うところの公教育の再生ということで、公明党としては先日そういった形で参議院の代表質問の場で、国に対してでありますけれども、こうした学校の授業のありようということも求めるというか表明をしたというところがあります。これは数学の授業だったそうです。","respondent":"丸谷教育総合支援センター長","answer":"児童・生徒の辞書の活用についてですけれども、こちらは主に国語の時間で辞書引き等の時間というのは設定されておりまして、子どもたちが今はインターネットでたやすく調べられる時代ではありますけれども、辞書を引く意味というのもあると考えております。","voiceIndex":179,"id":"exchange-079"},{"speaker":"つる委員","kind":"質問","question":"我が家でも辞書をよく見ると、上の子も下の子も本当にシメジを栽培しているのかというぐらい付せんがいっぱいぱあっとここについているのです。子どもたちの放課後の居場所として図書館がしっかりと確立するように、例えば「磯野、図書館行こうぜ」と言うぐらいになるような図書館のしつらえ、整備、これをお願いしたいと思うのですが、こうした図書館の整備計画などについてのお考えがあれば教えてください。","respondent":"吉田品川図書館長","answer":"品川区は、今、おっしゃられたとおりに、これまで多くの人に本を貸すということを主体としてやってきたところです。そのため、大体歩いて１０分から１５分ぐらいのところに、規模は大小ありますけれども図書館の整備を進めてきたところです。","voiceIndex":181,"id":"exchange-080"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ図書館の整備、またこれ全体計画も含めて検討いただきたいと思います。私たちも議員としては区民の心の代弁者として質問させていただきました。こうしたやり取りというのは一瞬のやり取りかもしれないけれども、やはり区民の福祉の向上だとか、それが無限の価値となるような質疑だったというような形にしていきたいと思いますので、引き続き研究ではなくて検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":183,"id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お願いします。中塚委員の質問の続きみたいになってしまうのですけれども、修学旅行もしくは移動教室があると思うのですが、こちらは教育課程なのかそれとも課外活動的な位置づけなのか、ちょっとその辺をまずお伺いしたいので、お願いします。","respondent":"丸谷教育総合支援センター長","answer":"修学旅行、移動教室ともに教育課程内で行われる行事です。","voiceIndex":185,"id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"この２つは保護者というか私費で行われているのか、公費で行われているのか、その辺の内訳を教えてください。","respondent":"柏木学務課長","answer":"本区におきましては移動教室、これは６年生も７年生もですが、移動教室については基本、公費で実施をしています。修学旅行につきましては私費で実施をしています。","voiceIndex":187,"id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これは両方とも教育課程なのですけれども、この違いというのはどうして表れているのでしょうか。","respondent":"柏木学務課長","answer":"ただ、こちらは移動教室も修学旅行も、移動教室について公費で負担しなくてはならないものではございません。自治体によっては、移動教室を私費で実施している自治体もあります。","voiceIndex":189,"id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"しっかりとしたその定義というか、どうして分けられているのかが分からないということで、それこそ義務教育の無償化というところでお話が先ほど出ておりましたので、ぜひ修学旅行も、今の時代やはり相対的な貧困率も今１６％と言われていて、母子家庭は５０％以上が相対的貧困と言われている中で、恐らく一つの教室で５人から７人ぐらいの子どもが相対的貧困になっているという状況ですので。","respondent":"柏木学務課長","answer":"教員の自己負担につきましては、基本、食事代と、あともし現地で何か飲物を買った場合ですとか何かお土産を買うという部分は、教員の自費負担となっています。","voiceIndex":191,"id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"つまり、基本的には持ち出しというのはないというふうに受け止めております。そういう意味でも、やはり教員も生徒も含めて自己負担なく修学旅行なり移動教室が実施されるということを願っておりますので、これも要望しておきます。お願いします。","respondent":"丸谷教育総合支援センター長","answer":"スクールカウンセラー、スクールソーシャルワーカーにつきまして、子どもたちのニーズ、保護者のニーズも高まっているという認識です。","voiceIndex":193,"id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問","question":"では同じ見解で非常に安心しました。そういったところで、現在のスクールカウンセラーとスクールソーシャルワーカーの配置というのはどのようになっているのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"合計５４名の配置となっております。スクールソーシャルワーカーは、ＨＥＡＲＴＳのメンバーとして、会計年度任用職員として６名を区で任用しておりまして、週三、四日フルタイムで勤務しており、要請に応じて学校に派遣をしている形態を取っております。","voiceIndex":195,"id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そういった生徒の対応を先生に任せてしまうとやはり負担が増えてしまう、業務過多になってしまうというところで、ぜひスクールソーシャルワーカー、今、五、六名で週三、四回ということなのですけれども、さらなる増員をぜひお願いしたいのですけれども、そういったご予定のほうはいかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"スクールソーシャルワーカーの役割、福祉につなげるということで非常に大きな役割になっております。この人数の拡充につきましては、実際の動きと併せて検討していきたいと考えております。","voiceIndex":197,"id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"やはりスクールカウンセラーにしろ、スクールソーシャルワーカーにしろ、児童と向き合って信頼関係をつくっていく、そういった作業が大事だと考えると、やはり一斉に解雇されてしまったりとかすることというのは、非常に子どもにとってもよくないですし、こういった問題は起きてはいけないとは考えているのですけれども。","respondent":"丸谷教育総合支援センター長","answer":"継続希望のスクールソーシャルワーカーにつきましては、その勤務実態に応じて、新規の方とも不公平のないように任用の手続、採用をしています。","voiceIndex":199,"id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本来であれば、やはり安定して会計年度、恐らく実績ある方というのはある程度評価されるとは思うのですけれども、毎年毎年というのではなくて安定して働けるような、会計年度任用職員ではないような形をぜひ正規ということも前向きに考えていただきたいと、こちらも要望します。その中で、特別支援学校は、こちらは対象になっておりますでしょうか。お願いします。","respondent":"柏木学務課長","answer":"来年度の実施予定です、補助教材の負担軽減事業につきましては、品川区立の学校が対象となっています。特別支援学校は、現在のところ対象とはなってございません。","voiceIndex":201,"id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"私からは、３８９ページの学校図書館運営費に関わって、図書館司書配置と拡充について。３８１ページの教科書採択事務について伺います。今回、学校図書館への運営支援スタッフ・司書の配置が週２.５日から３日に拡充されました。その理由と拡充内容を伺います。","respondent":"吉田品川図書館長","answer":"今まで年間７３５時間契約していたところを、その５校については８８２時間、１４７時間増加するということの変更です。この増やした理由につきましては、昨今の小学校の学級数増を鑑みた特例的なところで、試験的なところと認識しております。","voiceIndex":207,"id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"クラス増を鑑みて、大きな学校については増員をしたということだと思います。決算特別委員会でもこの拡充を求めまして、そのときは契約更新の機会でいいチャンスだったわけですけれども、そのときは今年度は据え置かれたということで、新年度については拡充されたことはうれしく思います。そして、さらなる拡充を求めたいと思います。この所管評価と最終評価の違いが生まれている理由を伺います。","respondent":"吉田品川図書館長","answer":"最終評価につきましては、年間の平均貸出数というところでは、今品川区のほうでは右肩上がり、年間学校図書館では１００万冊程度の本の貸出しがありまして、学校支援スタッフの配置につきましては各学校それぞれの適切な人数が必要であるというふうに評価を受けたところで。","voiceIndex":209,"id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"今のお答えですと、違いが生まれている理由を伺ったのですけれども、所管としては時間が不足しているのを解消したいというのと、最終評価では、これも貸出数が右肩上がりでスタッフが必要だということなのかなと思ったのですけれども、そうすると特に違いはなく、拡充していくべきだということでしょうか。伺います。","respondent":"吉田品川図書館長","answer":"そういうところを全体的に鑑みまして、今後よりよい方向で検討していければというところで考えております。","voiceIndex":211,"id":"exchange-093"},{"speaker":"のだて委員","kind":"質問","question":"そのように私は受け止めさせていただきました。そうすると、この最終評価に貸出冊数から見た課題ということで拡充をしていくということなのですけれども、先ほど右肩上がりということで答弁がありましたけれども、この実際貸出冊数の実績を伺いたいと思います。そして、この運営支援スタッフ、学校司書を配置することで貸出冊数が増えていくと、増やすことができると思うのですけれども、いかがでしょうか。","respondent":"柏木学務課長、吉田品川図書館長","answer":"令和元年度は、こちらも大体８６万冊。令和２年度が９５万冊、令和３年度が１０４万６,０００冊。令和４年度ですが、こちらは１０３万３,０００冊ということで、大体年度にもよりますけれども、大体増えてきているという状況です。その中で貸出しが増えてきているのは、ボランティアだったり、また図書委員の努力だったり、実際の司書の努力もあると思いますけれども、その全体の中で増えてきたものと理解しております。","voiceIndex":213,"id":"exchange-094"},{"speaker":"のだて委員","kind":"質問","question":"全体の中で増えてきたということで、それぞれの方が様々力を合わせて頑張っている結果だと思います。司書の方に聞きますと、やはり司書がいると子どもの目の輝きが変わってくるということでお話をされていました。そうした中でやはり本も好きになり、読書もしていくということで、やはりこの図書館の活用を進めていくためにも、学校司書の配置を週５日にすべきだと思いますけれども、いかがでしょうか。","respondent":"吉田品川図書館長","answer":"そういうのを踏まえまして検討してまいりたいと思います。","voiceIndex":216,"id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"それは一歩踏み出した前進だと考えていますので、ぜひそこからさらに拡充をしていっていただきたい、子どもの学びがさらに促進をされるようにしていっていただきたいと要望いたします。以前はある学校にその教科書を置いて、教員の方もしっかり意見を出せるようにということでやっておりましたので、そうしたやり方をしていただきたいと思うのですが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"教科書展示における区民の方からのご意見を採択事務に反映させるということですけれども、今年、この採択事務のスケジュールはこれから組んでいきますけれども、やはり採択に向けた手続・スケジュールを考えたときに、なかなかその意見を全て取りまとめて。","voiceIndex":218,"id":"exchange-096"},{"speaker":"のだて委員","kind":"質問","question":"やっている意味がないということにもなりかねないと思いますので、そこはしっかり反映できるようなスケジュールで組んでいくということが必要だと思うのですけれども、いかがでしょうか。教員の意見を保障するというところでは、今そういう仕組みになっていないというのはどういった変更があったのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"その教員の意見について、学校に見本本を置くという仕組みにはなっていないと、見本本はあくまで展示会用と、それから調査研究のためのものということで教育委員会に配布がありますので、その研究会の中で十分検討資料を作っていく中で、教員のベテランが使いやすい。","voiceIndex":220,"id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"教員についてはぜひ意見を出す場は保障していただきたいと思います。そして、この区民の意見の関係では、現時点ではこの反映が難しいというのはやはり見直しが必要だと思うのです。実際やっているわけですから、その意見を聞いて、しっかり区民の意見を反映させていくということが必要だと思いますが、改めてその改善を求めたいと思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"実際に教科書を使用するのは児童・生徒ですので、専門性のある教員が調査研究を行って、教育委員会でしっかりと採択するということが大切であると現時点では考えております。","voiceIndex":222,"id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民の意見を聞いているわけですから、それはしっかり反映できるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-099"},{"speaker":"せお委員","kind":"質問・要望","question":"よろしくお願いします。時間があれば３８１ページ、特別支援教育費をお聞きします。ですから、今回の来年度予算案を合わせると、品川区の取組は多様化してきている、すばらしいと感じています。一、二年生に対して、特に教科学習以外の学習の工夫はどのように行っていますでしょうか。来年度予算案のしながわ教育推進事業の中で新たな取組、特に一、二年生に対してとかがもしありましたら、教えてください。","respondent":"中谷指導課長","answer":"絵で表現したり、言葉だけでなくて様々な自由な表現方法で、自分で選んだ方法で伝えられるような活動を展開することが、発達段階に応じたとても充実した取組ではないかと考えていますので、こういった取組を広げていきたいと考えています。","voiceIndex":226,"id":"exchange-100"},{"speaker":"せお委員","kind":"質問","question":"ホームスクール・アンド・ホームエデュケーション家族会が毎年行っているアンケートの２０２３年度の調査では、ホームスクール・ホームエデュケーションを始めたときの子どもの年齢で最多だったのが小学校１年生で、３２.２％でした。そのような保護者が登校渋りで困ったときに、どこに相談すればよろしいでしょうか。何か今現在取り組んでいらっしゃることとかありましたら、教えてください。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"魅力のある給食にするため、毎年栄養士に集まっていただいて献立等の検討をしています。いただいた意見をそういう場には伝えて、より魅力のある給食にしていきたいと考えています。教育委員会では教育相談室を設けておりまして、そういった不登校になりかけの登校渋りのご相談、またはＨＥＡＲＴＳにご相談いただいても対応いたしますので、ぜひ窓口にご相談いただければと考えております。","voiceIndex":228,"id":"exchange-101"},{"speaker":"せお委員","kind":"質問・要望","question":"項目は学校環境整備事業となるのでしょうか。一般質問でも校庭でとお話ししましたが、すまいるスクールなどとの関連もあるということで、学校によっては屋上なども活用できるのかなと思っています。先ほどの話に戻ると、一、二年生が学校を楽しみにするきっかけの一つにもなると思っています。学校でのプレイパーク、今後検討していただきたいと思っていますが、見解をお聞かせください。","respondent":"森学校施設担当課長","answer":"既存校であれば屋上はかなり空いていますので、そういうことも可能かとは思うのですけれども、改築校につきましては屋上の部分に室外機置場であったりとか、太陽光発電、屋上緑化であったりとか、かなり設置してありますので。","voiceIndex":231,"id":"exchange-102"},{"speaker":"せお委員","kind":"質問・要望","question":"とにかく学校を楽しめるというか、過ごしやすくなる環境をぜひ充実を図っていただきたいと要望いたします。教育現場でも、教員が正しく保護者にお子さんの様子を伝えられる知識やスキルを身につけること、さらには学校公開というのもやられていますが、保護者に実際の様子を見てもらうこと、この２点については、どのように現在取り組んでいますでしょうか、お聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"学校公開は年に複数回ありますので、そういったところでお子様の様子をご覧いただいて、家庭での様子と学校での様子の違いですとか、そういったところを保護者にご覧いただいているところではあります。","voiceIndex":233,"id":"exchange-103"},{"speaker":"せお委員","kind":"質問・要望","question":"これは要望です。最後に、この特別支援教育費のところでお聞きしたいのですけれども、教育は本当に東京都が主体で都の教員がほとんどを占めていますので、東京都の指針とかもすごく大切になってくると思うのですけれども、東京都から主にインクルーシブ教育についてというのは、どのような方針が下りてきているのかというのを教えていただければと思います。","respondent":"唐澤特別支援教育担当課長","answer":"東京都のほうですけれども、これまでと同様として、多様な学びの場における児童・生徒の障害の状況に応じた支援体制の充実を図っていくというような形で、次年度の予算事業についても概要ですけれども連絡が来ているところです。","voiceIndex":235,"id":"exchange-104"},{"speaker":"せお委員","kind":"質問・要望","question":"なので、要望ですが、東京都とぜひ意見交換などを区市町村のほうでも進めていただいて、何か方向性などを東京都が示していただけると大変ありがたいと思っていますので、ぜひ意見交換などをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-105"},{"speaker":"石田（し）委員","kind":"質問","question":"私からはページ横断的になるのであれですが、教育全般の方向性についてと、給食費について３９１ページ。それと、時間があれば、これもちょっとページが分からないですが、主権者教育についてお伺いします。やはりなぜなら、これまで高橋区政そして濱野区政を通して、様々品川区は先進的な教育をやってこられたと思います。よろしくお願いします。","respondent":"桑村副区長","answer":"今日というかこの間いろいろ議論がありますけれども、なかなか答えは出ないのだと思いますけれども、ただやっていることが大切なのだと思いますので、令和６年度、また新たな意味で総務のほうで仕事をするようになるわけですので、ぜひそれを見守っていただく。","voiceIndex":239,"id":"exchange-106"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私はぜひ次の無償化のステージとしては、食材の完全国産化に取り組んでいただきたいと思います。災害があったときだけではなくて、普段からそういう付き合いをすることによって、いざというときにもお互いが助け合えることがさらにできるように、そういったいろいろな意味でぜひこの完全国産化についてやっていただきたいと思うのですが、区のご見解をお聞かせください。","respondent":"柏木学務課長","answer":"単純に言えば、児童・生徒・教員合わせまして、１日約２万４,０００食ありますので、それを賄える安定供給ができるのかというのと、あと地方との連携もありますが、正直細かいことを言いますけれども、ゴマですとか大豆、小麦、あと魚もなのですけれども。","voiceIndex":241,"id":"exchange-107"},{"speaker":"石田（し）委員","kind":"意見","question":"確かにいろいろなハードルがあるのかなと思いますが、ぜひ様々研究していただきながらその実現に向けて、完全と言うとなかなか難しいかもしれない。でもこれは、これも含めて私は国が本来やるべきことだと思っていますが、もう区がまず先頭に立ってやっていただいて、東京都も今少し動き出しました。すみません。以上で時間がなくなりましたので終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":243,"id":"exchange-108"},{"speaker":"木村委員","kind":"意見","question":"よろしくお願いします。私からは３７５ページの中ほどより下、学校支援費９,１８０万円余の中のいじめ防止対策費からですけれども、予算的には８,５７０万円余強の予算が組まれています。いじめ問題は古くからある問題ですし、大変頭の痛いところだと思っています。このいじめ問題、さかのぼればどれぐらい昔からある問題なのかお聞かせください。本音をお願いいたします。","respondent":"丸谷教育総合支援センター長","answer":"いじめがなくならない、確かにそういうところはあるのですけれども、これはもう国が法律でいじめの定義を定めたからでありまして、被害を受けた児童・生徒が心身に苦痛を感じていれば、それはいじめと認知していきましょうということですので。","voiceIndex":245,"id":"exchange-109"},{"speaker":"木村委員","kind":"質問・要望","question":"いじめは少なくなるのではなくて根絶できるのか、イエスかノーかでお答えをいただきたい。それが本当になくなるのか、なくなることができるのかどうか。これをイエスかノーかでお答えください。","respondent":"丸谷教育総合支援センター長","answer":"いじめの発生、我々はいじめが発生した後、認知を行いますけれども、それをゼロにするということは限りなく難しい、不可能だと考えておりますが、いじめが発生した際に早期対応することで、そのいじめをなくすという意味での根絶ということは。","voiceIndex":247,"id":"exchange-110"},{"speaker":"木村委員","kind":"意見","question":"なぜこのいじめ問題というものが起きるのか。私自身も暴力を振るっていた子どもの頃でしたので、今は深く反省をしております。しかし今思えば、本当にこれは寂しさを紛らわすための行為だったのかとも思っています。このいじめ根絶協議会というものはいつ設立されて、この設立の目的、都はどのような活動をしているのか。それに対してお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"いじめの加害行為を行う児童・生徒にも、やはり何か心の中に不安ですとか寂しさといったものもあるのだと捉えております。ですので、被害だけではなくて、加害行為に及んだ児童・生徒への支援というものも大切にしていきたいと考えております。","voiceIndex":249,"id":"exchange-111"},{"speaker":"木村委員","kind":"質問","question":"具体的にお聞きしますけれども、いじめた側に対しての注意というかそういうものと、あと、いじめられた側というのはどういうフォローをしているのか。それが分かれば教えてください。","respondent":"丸谷教育総合支援センター長","answer":"いじめた側に対してですけれども、実はいじめた側も、自分が気づいていない場合もございまして、そういったところは教員がしっかりと子どもと向き合って、今、行った行為が相手を傷つけている行為だということを丁寧に説明した上で。","voiceIndex":251,"id":"exchange-112"},{"speaker":"木村委員","kind":"意見","question":"そういうフォローをしてくれていると思うのですけれども、それがどのような効果を生んでいるのか、そういうことを調べたことがありますか。本当にこれは深刻な問題で、これは本当にいつまでたってもなくならない問題であろうと思っていますけれども、何か本当にそういうところに釘を刺す、そういう効果的なものが何かあるのかどうか、そういうことをお考えになってるかどうかもお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"効果的な指導というものにつきましては、次年度、いじめ予防プログラムを実施していきます。教員も一生懸命研修を今行っているところですけれども、全区立学校でいじめ予防プログラムを実施して、子どもたちが安心して学校に通えるような環境づくりを行ってまいります。","voiceIndex":253,"id":"exchange-113"},{"speaker":"木村委員","kind":"質問","question":"はっきりお聞きしますけれども、今はそのようないろいろな対策をしているけれども、実際にいじめというものはなくなっているのか、少なくなっているのかどうか。このことをはっきりとお答えください。","respondent":"丸谷教育総合支援センター長","answer":"いじめが少なくなるかどうかですけれども、子どもたちがまずいじめとはどういうものなのかということをしっかり認識する必要があると考えておりまして、それが子どもたちにしっかり定着すると、いじめは少なくなっていくという期待がありますが。","voiceIndex":255,"id":"exchange-114"},{"speaker":"木村委員","kind":"質問・要望","question":"それが本当に成功するかどうか分かりませんけれども、そういうふうにして努力をされているということは本当にこちらもありがたく思うところであります。いつの時代もこれだけは絶対になくならない問題であろうと考えていますけれども、本当に徹底して子どもに対してフォローしてあげていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-115"},{"speaker":"塚本委員","kind":"質問","question":"初めにまずお伺いしたいのは、教室の予定数は２４ということで、今現状では源氏前小学校は比較的小規模なので、全クラス１年から６年生まで２クラスということで１２クラスを使っているのですけれども、この改築にあたって教室の使用の見通し、計画というのですか。これを最初にお伺いしたいと思います。","respondent":"柏木学務課長、森学校施設担当課長","answer":"今の源氏前小学校の入学率等で算出しますと、最高で１３学級から１４学級ぐらいにはなる推計が出てあります。卒業式や入学式、イベントのときは工事が配慮して一旦工事を止める等、騒音振動が授業にあまり影響がないように配慮しながら工事を進めてまいりたいと考えております。","voiceIndex":259,"id":"exchange-116"},{"speaker":"塚本委員","kind":"質問","question":"今いろいろなご配慮いただけるということで伺いましたけれども、長い期間にわたる工事ですので、その間、小学校の足かけ６年というと、入学してからほとんど卒業するまで工事の中でずっと卒業していくという生徒もいるということになりますから、ぜひ配慮のほうをよくよくお願いしたいと思います。","respondent":"森学校施設担当課長","answer":"ＳＴＥＡＭコモンズですけれども、ＳＴＥＡＭとは科学、技術、工学、芸術、数学とあるのですけれども、５つの領域を対象とした理数教育に創造性教育を加えた教育理念、知ると創るのサイクルを生み出す分野横断的な学びということで、理科室と音楽室。","voiceIndex":262,"id":"exchange-117"},{"speaker":"塚本委員","kind":"質問","question":"３７９ページのブラインドサッカー体験教室ですけれども、区内の全ての中学校、義務教育学校のいわゆる８年生に対して実施をされていることと承知をしております。今年度までの事業の評価と、来年度以降この多様性理解、多文化共生推進というふうに銘打って行っていくこの新たなスタートというようなことも言えるかもしれませんが、その考えについてお伺いをいたします。","respondent":"中谷指導課長","answer":"今までしながわ学校２０２０レガシー事業として継続してまいりましたが、この教育活動の趣旨は継承しながら、令和７年度のデフリンピック東京開催を契機に、事業名を品川多様性理解多文化共生推進事業として時代に即した形に再構築してまいりたいと考えています。","voiceIndex":264,"id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、ページ３７５ページ、いじめ防止対策費。３７１ページ、教育振興基本計画。時間があれば３７７ページ、地域の歴史・文化学習についてお伺いします。そういう中で、昨年決算特別委員会でもちょっと質問したのですが、なかなか思いが伝わらなかったので改めて伺いますが、昨年、○○○○の中学校でのいじめ問題が発生して、当時教育委員会の下でいじめ対策委員会が設置をされ、報告がなされました。","respondent":"丸谷教育総合支援センター長","answer":"いじめの重大事態の調査についてですが、当時いじめの重大事態としての認定がなされておらず対応をしてきたというところ、まずもって重大事態として認定するという意識が教育委員会には欠けていたというところでございまして、その辺りは真摯に受け止めております。","voiceIndex":268,"id":"exchange-119"},{"speaker":"田中委員","kind":"質問","question":"そのときの、何でしょうか、受け止めは今のような話でありましたが、それを踏まえて新年度、令和６年度の予算の中にいじめ防止対策費が教育委員会にも計上され、さらに同じような趣旨のものがこの区長部局にも予算化されています。","respondent":"丸谷教育総合支援センター長","answer":"いじめが起こった際には、学校がまず一義的には早期対応することで解決を図っていくものです。そうした解決が難しい場合に、教育委員会からも支援をしていくというふうに捉えておりまして、なるべくならと言いますか、教育委員会としては、学校がとにかく解決を図る。","voiceIndex":270,"id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう関連で、教育振興基本計画につきましては、これまで極めて個性豊かな教育長の下でプラン２１とか教育ルネサンスがなされてきた中で、ただ教育というのは国家１００年の大計で、時代がどういう変化があろうとも、その根底には教育という一つの大きな柱があって、それに基づいた品川の教育がなされるべきだと考えています。","respondent":"宮尾庶務課長","answer":"当然にこの計画ができた後、この計画に基づいて教育施策を教育委員会一体となって推進をしていくという考えです。","voiceIndex":272,"id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、あと、教育の無償化の関連であります。その教育とか学用品の質、給食の内容とかも献立も含めて、それをぜひしっかりとした基準を明確につくっていただいて、無償化でどのような時代であろうとその品質は保っていくという、そういう視点での取組をぜひお願いしたいと思います。時間がありませんので、要望だけ伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":274,"id":"exchange-122"},{"speaker":"こしば委員","kind":"質問","question":"よろしくお願いします。私からは、３７７ページ、市民科・各教科充実経費について伺います。品川区のオリジナルの科目、市民科ついて伺います。市民科自体は２００６年から本格的に小・中一貫校で実施が始まったと認識しております。その前にもう既にモデル実施が行われていたと認識をしております。本格実施から、２年後には２０年を迎える中で、これからもこの「市民科」の名称を続けていくのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"今、委員からご紹介ありましたとおり、この市民科と名称を名づける際に、この社会の形成者ということで、区民ではなくて広く一般的な意味として、市民という言葉を用いて名づけたというふうに認識しております。","voiceIndex":276,"id":"exchange-123"},{"speaker":"こしば委員","kind":"質問","question":"これからも、名称のほうはなかなか変更するのは難しいということはよく分かりました。今から２０年前、ちょうど２００４年９月にモデル事業として市民科が始まったと思いますが、先ほども話が出てきましたが、当時の教育長でした若月氏が市民科創設の経緯について、当時の鈴木真澄区議の一般質問の答弁でこう述べております。市民科の目的は達成されているのかどうか、教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"なかなか市民科を９年間受けた子どもたちが今どのような社会生活を送っているのか、そういったところまでの後追いというのは難しいのですけれども、品川区といたしましては、この市民科の資質・能力をしっかり身につけた子どもたちが大人になって。","voiceIndex":278,"id":"exchange-124"},{"speaker":"こしば委員","kind":"質問","question":"２０２０年には世界各国で平均７か月の学級閉鎖が行われ、子どもたちが学校で学ぶことがとても困難となりました。コロナ禍の中で、子どもたちは対面での交流が難しくなり、楽しい食事時間も黙食を続けるなど、そういう中での市民科教育の課題はどのようなものだったのでしょうか。課題に対して市民科教育はどのように変わってきたのか、教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"この影響を取り戻すために、今年度、学校では様々な取組が再開していまして、また複数年かけて子どもたちをしっかりと育てていきたいと考えております。","voiceIndex":280,"id":"exchange-125"},{"speaker":"こしば委員","kind":"質問・要望","question":"それで、この市民科ですが、教育要領を見ておりますと、この市民科のそもそもの目的というのが、個と内面、個と集団、個と社会というそれぞれの関係性の中で１５の能力を身につけ、もって自己実現を図る力を子どもたちに身につけてもらうというふうに認識をしております。その中で、集団や社会の中での個はモラルある行動や言葉が求められます。ある程度の道徳を教えてから、そこから教育であると。","respondent":"丸谷教育総合支援センター長","answer":"市民科授業地区公開講座というものを、各校年に一回以上実施しておりまして、その中では保護者だけではなくて、地域の方にも市民科の授業を見ていただき、授業を見終えた後には協議の時間も設けております。","voiceIndex":282,"id":"exchange-126"},{"speaker":"こしば委員","kind":"質問・要望","question":"ラスト、時間があと３０秒となりましたけれども、やはり私が思うのは、総合的な学び、学校の外での活動、課外活動、これをやはりさらに時間を取って継続的に取り組んでいただきたいと考えています。そうすることによって、市民科の質もさらに上がってくると考えます。実学のさらなる拡充に向けて、教育委員会のお考えを教えていただきたいところですが、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":284,"id":"exchange-127"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、３７５ページ、いじめ防止対策費、３８１ページ、校内別室指導支援事業というか、全体的なことでお聞きをしたいと思います。話があって、だけれどもいろいろ考えると、親とかそういうことばかりで、子どもたちにお金を使ってほしいという話でありました。だって、今だって週１回行って、こういう人がいたら少し気にしてみてくださいと待ったりできているわけではないですか。","respondent":"丸谷教育総合支援センター長","answer":"そういったものを通しながら、子どもたちの変化についても気づいていけるように取り組んでまいります。","voiceIndex":286,"id":"exchange-128"},{"speaker":"石田（秀）委員","kind":"意見","question":"今言った予防も知っています。今の話も分かっているし、今言ったように担任の方というのはもちろん分かっているけれども、その中でもしっかりやっていくには、東京都のことも分かっていてあえて言っているから、予算をつけなくてはならないから、人のこともあるから、これは区長部局がぽんとやらないとこれは多分無理だと思っているから、区長部局に答えてほしいと言っているということです。","respondent":"丸谷教育総合支援センター長","answer":"スクールカウンセラーは、学校の状況を見ながら必要があれば予算のほうを要望していきたいと考えております。","voiceIndex":288,"id":"exchange-129"},{"speaker":"松永委員","kind":"質問","question":"私からは、３７５ページの帰国児童・生徒等支援費、１,３６４万９,０００円について伺いたいと思います。その中で、本区として把握されている児童・生徒は、先ほど述べさせていただいた割合でよろしいでしょうか。そして、本区においてどのような教育支援をされ、派遣講師についてでありますが、外国人の方がされているのでしょうか、併せて伺いたいと思います。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"日本語指導についてです。現在、ＩＷＣというＮＰＯ団体に委託をしておりまして、実施をしています。外国籍の児童・生徒数ですが、学務課で把握している小・中学生合わせまして約７４０名、そのうち品川区立の学校に通っている方は３７０名と把握しています。","voiceIndex":293,"id":"exchange-130"},{"speaker":"松永委員","kind":"質問","question":"そうした中で、教材費について伺いたいのですが、本年度１０万円計上されております。これは印刷代なのでしょうか。先ほども述べさせていただいたのですけれども、その点についてどのように把握されているのか、また、外国の方が転入届を出された際に、お子さんがいらっしゃる場合に、こうした事業がありますという紹介はされているのでしょうか。そうした周知方法についてお知らせください。","respondent":"丸谷教育総合支援センター長","answer":"外国籍の方、日本語指導が必要な方が転入した際には、まず学校で校長が面接を行いますので、日本語の習得状況を見ながら、こちらの日本語教室をご案内しています。","voiceIndex":296,"id":"exchange-131"},{"speaker":"松永委員","kind":"質問・要望","question":"教材費のほうは理解いたしました。その中で、講習の中で初級コースと中級コースというものがありまして、初級では３７０回、中級が１５０回ですが、この差について、どうなのでしょうか。初級を受けたら、普通は大体中級を受けるという可能性があるとは思うのですけれども、なぜこのような差が生まれているのかお知らせください。","respondent":"丸谷教育総合支援センター長","answer":"引き続き中級も受講されたいという方は、教科書を用いながら、また受験にも対応できるような形での指導を行っているところでございまして、学校でもう足りるという方は、中級は受講していないために、このような差が生まれているものです。","voiceIndex":298,"id":"exchange-132"},{"speaker":"松永委員","kind":"質問","question":"理解いたしました。その中で、７万５,０００円では、３,０００円掛ける２５回です。これはもしかしたら９万円というところでは、３,０００円の３０回ということの理解でよろしいでしょうか。２５回という回数についてですが、１日１回という意味なのでしょうか。もしそうであれば、１回に当たり何時間の受講が可能なのでしょうか、併せて伺います。そして、２５回というのは１年間の回数なのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"１回３,０００円という形で、年間で３０回ということになってあります。１回ということですので、特に時間制限というのは設けておりません。減額の理由ですけれども、実績に合わせまして、十分足りるということでの判断でこのような結果となっております。","voiceIndex":300,"id":"exchange-133"},{"speaker":"松永委員","kind":"質問","question":"今現在、山中小学校の空き教室のみということなのですが、そうであれば、日本語の言語指導とか適応指導ということで、生徒たちはそれで満足いっているのか、少し不安なのですけれども、今後、外国人の方で品川区に転入される方も結構増えてきておりますので、そうしたところの対応はどのようにされていくのでしょうか、お知らせください。","respondent":"丸谷教育総合支援センター長","answer":"現在、山中小学校で９８名の児童・生徒が指導を受けていますけれども、実はかなりキャパが満杯になってきているということで、次年度につきましては、山中小以外の教室を増やして、指導の充実を図るように考えております。","voiceIndex":302,"id":"exchange-134"},{"speaker":"松永委員","kind":"提案","question":"そうした児童・生徒は各地域に住まれている方と思います。そうした場所で、移動が難しいということで諦めている方もいらっしゃるのではないかと思います。そこで、今後、教室数を増やしていく一方、例えばスクールバスなどを提案させていただきたいのですけれども、また、学校で貸出ししているタブレットを使った通信教育のような形でも取れるのかどうかということで、この２点、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"移動についてのバスの手配等を、行う考えは今はないのですけれども、タブレットを活用したオンラインでの日本語指導というものを、既に令和２年度から実施しておりまして、移動の難しい方はオンラインでの受講もできることになっております。","voiceIndex":304,"id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"その学校に対しての対応をどう考えられますでしょうか。幾つか質問がありましたけれども、品川区によってのインクルーシブ教育という在り方をどう考えていくのか。その後、いろいろな関係機関の連携というものを考えていってほしいと思うのですが、教育委員会として、今回の条例の改定に含めて、教育委員会以上に区長部局、区長の権限を強めるということに対してのご意見を伺いたいと思います。","respondent":"柏木学務課長、宮尾庶務課長、唐澤特別支援教育担当課長、丸谷教育総合支援センター長、森学校施設担当課長","answer":"就学人口の増加と３５人学級の導入に伴いまして、各校の教室数については、まだ若干大丈夫な部分はありますが。一方で、これらの取組というのは、総合的・体系的に示すというところで課題があったというところを認識してございまして、今回の計画は。今後も就学相談の際に、そうした情報というのは保護者の方と共有しながら対応していければと考えています。区長部局とも連携する部分は今後出てきますけれども、いじめ対応は、まず一義的には学校がやっていくものだということには変わりありませんので。","voiceIndex":308,"id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、小規模校の、いろいろな考え方はあろうかと思いますけれども、整理なども含めて、考えていくべきことがあるのかなと思いますので、お願いしたいと思います。保護者のほうが、普通学級がいいとか、いろいろな要望があるのです。片や、一人一人しっかり見てほしいという親御さんもいらっしゃるのです。なので、そこをやろうとするときには、本当に専門的な知識が、これからかなり求められると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":314,"id":"exchange-137"},{"speaker":"若林委員","kind":"質問・要望","question":"１月に区内の学校のグラウンドでスライディングした児童が裂傷した事案について、今年度中に金属探知機点検をやるということで、今、進行形なのか、年度内に終わるのかということの確認と、その結果、ペグ等が見つかったのかどうかという確認もします。もう少しお願いします。１期とか２期とか３期という表示があるので、その「期」とはどういうことなのかの確認をします。","respondent":"森学校施設担当課長","answer":"２２校中、残り６校まで進めておりますので、今年度中には終わる予定です。出てきているかどうかということにつきましては、本数は出てきていると報告を受けておりまして、結果が出てまいりましたら、また報告したいと考えています。","voiceIndex":316,"id":"exchange-138"},{"speaker":"若林委員","kind":"確認","question":"外壁・屋上改修費については、いわゆる老朽化対応ということで、改築をすれば、この対応がまた低減されると思うのですが、現状、さっきの４校と中学校が１校ということで、そもそも、時間がないので確認だけですが、他区の事例を見て、改築する際に周りの道路が狭くて、どうしても拡幅をしないと工事ができないという事例がありまして、品川区においては改築に関しての取組は。","respondent":"森学校施設担当課長","answer":"道路の幅員については、特に定めてはいないのですけれども、道路が狭いと工事の期間がとても延びるというのがあります。何ｍ以上だとやるとか、やらないとか、そういうのはないのですけれども、道路が狭隘ですと工事期間が延びて、影響が大きいとは考えてあります。","voiceIndex":318,"id":"exchange-139"},{"speaker":"若林委員","kind":"確認","question":"狭くても工事は可能だということを確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-140"},{"speaker":"西村委員","kind":"提案","question":"３７９ページ、不登校対策事業費全般より、校内別室指導支援事業や、メタバース、ポータルサイトについて伺います。メタバースから伺います。学校で会えなくなったお子さんを把握し切れないところをどのようにしていくか、先生によっても対応にばらつきがあるはずで、担任に対応が集中しないようになど、以前から提案をさせていただいています。メタバースで親支援に取り組めないか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"ご提案いただきました親向けの居場所ということですけれども、今回、子どもたちの居場所づくりということで、東京都のバーチャル・ラーニング・プラットフォーム事業に参画するものでございまして、親向けの空間というのを常時設置することは難しいのですけれども。","voiceIndex":322,"id":"exchange-141"},{"speaker":"西村委員","kind":"質問・要望","question":"親のイベントですとか講演会は、不登校に子どもがなっていない親御さんも入れるものかどうか伺いたいと思いますけれども、もし親のルームが今後できましたら、保護者にとっても、実際に子どもたちに関わっている先生方、カウンセラーなどがどのように設置しているかを知る、親としてもヒントを得ることができると思っています。ぜひご検討いただきたいと思います。区のご見解をお聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"ポータルサイトについてですけれども、児童・生徒の皆さんへということで、子どもたちが読むページというのも設ける予定です。１人１台タブレットの中にもリンクを貼ることも検討しておりますので、子どもたちがそこに入れるような工夫もしてまいります。","voiceIndex":324,"id":"exchange-142"},{"speaker":"西村委員","kind":"質問","question":"とても安心いたしました。質問は変わりますけれども、不登校児童のお子さんに対して、昭和の時代、私が子どもの頃ですが、あしたは来いよと先生がうちに来てくれることがあったなと、私自身のことを思い返すのですが、現状、不登校児に訪問支援を実施しているか、また、コロナが明けましてから、オンライン授業を実施している学校があるのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"オンラインの授業ですけれども、子どもたちの状況に合わせて先生から提案をして、了承を得られれば、お互いの了解の下に実施しているケースもあります。","voiceIndex":326,"id":"exchange-143"},{"speaker":"西村委員","kind":"質問・要望","question":"学校側から伺うと、ご家庭や児童・生徒のプレッシャーになる場合もあると思いますし、難しいと思うのですが、オンライン授業がコロナが明けてからなくなってしまったという親御さんのお声も聞きまして、不登校対策として引き続き、やめてしまった学校がもしありましたら、再開のご検討をいただきたいのと、また、メタバースがせっかく始まりますから、こちらの中でとか。","respondent":"丸谷教育総合支援センター長","answer":"１人１台端末、またオンライン授業についてですけれども、これはコロナのために行われるということではなくて、不登校支援や、その他何らかの理由で学校に来られない児童・生徒、また、学校には来られているけれども、別室で過ごす生徒が教室の授業を受ける等。","voiceIndex":328,"id":"exchange-144"},{"speaker":"西村委員","kind":"質問","question":"ぜひお願いしたいと思います。最後に、遅刻をするお子さんに対して教室まで保護者の付添いが必要なのは、区内全校で同じでしょうか。校門まで来たら対応するなど、今後、校内別室指導員がこのような場合にも柔軟に対応することはできるのか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"遅刻をする児童・生徒への対応についてです。","voiceIndex":330,"id":"exchange-145"},{"speaker":"西村委員","kind":"意見","question":"学校によって、もしかしたら差があるかもしれませんので、校門まででいいということであれば、改めて、いろいろな学校でそのような柔軟な対応ができるようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":332,"id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"質問","question":"よろしくお願いします。ただ、鈴ケ森小学校は仮設校舎を造るので、体育館が大きいのではないのですが、その点についてはいかがでしょうか。設計の段階で少し多めに、先ほども幾つか人口増との関係でお話ありましたが、これから改築するところは、教室の見込みをしっかりと余裕を持って、転用可能な教室という形で対応すると思うのですが、その点についていかがでしょうか。","respondent":"森学校施設担当課長","answer":"それと、鈴ケ森小学校につきまして、できる限り全体工期が短くなるように配慮して、工事工程を組んで工事を進めていきたい、そのことか可能かどうか含めて、実施設計を行っていきたいと考えています。","voiceIndex":334,"id":"exchange-147"},{"speaker":"高橋（し）委員","kind":"質問","question":"では次、３８３ページ、図書館運営費です。図書館の持つまちづくりの視点における図書館の役割、まちづくり、まちの活性化に果たす図書館の役割というのはどのようなものでしょうか。","respondent":"吉田品川図書館長","answer":"例えば人の面で言えば、認知症カフェだとか、そういうところで人同士の連携を図るところも進めてきております。他の事例とかでは、地域の文化とか、地域資料などを通じた連携などを図っている事例もあるようなので、これまで以上に地域と共にできることを検討してまいります。","voiceIndex":336,"id":"exchange-148"},{"speaker":"高橋（し）委員","kind":"提案","question":"四万十市役所も２階に図書館を置いている。残念ながら、２階に図書館とか、そのような状況ではないのですが、幸いにも区民交流スペースが２階・３階・４階にあります。大崎のこども図書室は、小規模ながら大変人気があると伺っています。教育委員会として、ここの部分に子ども図書室を入れたいということは、どこかで主張できるというか、提案したりすることが可能なのでしょうか。","respondent":"吉田品川図書館長","answer":"必要なものがいろいろある中で、限りある床面積をいろいろな視点から、優先順位といいますか、そういうのをつけて、全体の総量を調整するなど、総合的な調整を図った上で判断されるものと考えております。","voiceIndex":338,"id":"exchange-149"},{"speaker":"高橋（し）委員","kind":"質問","question":"今は企画課、財政課の方のご答弁のような気がして、教育委員会の図書館を担当している方として、こんなすばらしい図書館の活力あるいは能力というか、パワーがあるということを主張していただくと大変ありがたいのですが、もう一回そこのところをお願いします。","respondent":"吉田品川図書館長","answer":"図書館としては、新たな意味での施設の試みというのもありますけれども、全体の調整の中では安心・安全が優先されたり、優先される事業もいろいろあると思いますので、全体を含めまして検討していければと考えています。","voiceIndex":340,"id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問","question":"地域移行等推進経費の中で、編成過程の公表のところに、学校地域連携の経費のところで、要求額と予算額の差が１億円あったと。これは教育委員会として、あるいは国も都も働き方改革、部活の見直しをしているところで、教育委員会がこれだけやりたいという状況の中で、財政のほうではしごを外したのかとここでは見えてしまうのですが、その点について、どのような事情があったのでしょうか。","respondent":"中谷指導課長","answer":"ですので、段階的にやるということを考えまして、２部活程度ということで進めて、各学校そのような規模で進めてまいりたいと思っています。今、各学校からの声を聴いております。様々あると思いますので、聴いて、丁寧に対応しながら進めてまいりたいと考えています。","voiceIndex":342,"id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、２部活とありましたけれども、３部活、４部活と希望が出てきたら、柔軟に対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":344,"id":"exchange-152"},{"speaker":"松本委員","kind":"質問","question":"よろしくお願いします。私からは３７５ページ、平和に関する指導資料作成費、３７３ページ、修学旅行費、いじめ防止対策費について伺います。令和６年度の予算案では、非核平和都市品川宣言４０周年の記念事業が計上されています。児童・生徒が関わるような非核平和都市宣言４０周年記念事業があるのか、そのようなものがあれば、お答えいただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"教育委員会で予定している４０周年に合わせたイベントというものは、検討というか、予定はないのですけれども、毎年、広島平和使節派遣ということで行わせていただいていますが、そういったところで充実したものを続けていきたいと考えております。","voiceIndex":346,"id":"exchange-153"},{"speaker":"松本委員","kind":"質問・要望","question":"４０周年ということで、私はこれは決算のときに取り上げるべきだったと反省しているのですけれども、来年度の修学旅行は奈良と京都ということで、なかなかこれは変えられないとは思うのですけれども、今後というところで、自治体によっては同じ特別区の中でも、京都・奈良ではなくて京都・広島という修学旅行を計画されているところもありますので、来年度４０周年ということもありますので。","respondent":"丸谷教育総合支援センター長","answer":"修学旅行の行き先につきましては、各学校が定めることになっておりますので、たまたま今、品川区立学校では京都・奈良が多くありますけれども、広島も一つの候補地にはなってくると考えております。","voiceIndex":348,"id":"exchange-154"},{"speaker":"松本委員","kind":"質問・要望","question":"いじめ防止対策費について伺います。昨年の１２月に品川区いじめ防止対策推進基本方針が改定されたと発表されておりまして、これを私も拝見して、率直に言って驚いたというか、かなり詳しく書いていただいていると思います。特に一区民として感謝申し上げます。その上で、中身を拝見して、少し確認していきたいところもあるのですけれども、重大事態の対応フローも記載されています。","respondent":"丸谷教育総合支援センター長","answer":"いじめの重大事態の、その後の認定の後のフローですけれども、学校で作成した様式３、これはいわゆる学校での調査結果になりますが、こちらも区の対策委員会に渡して、それを踏まえながら調査を進めます。しかしながら、被害に遭われたご家族へのヒアリングも行います。","voiceIndex":350,"id":"exchange-155"},{"speaker":"松本委員","kind":"確認","question":"ここはできるだけ予断が生じないように、客観的にお願いできればと考えています。そうすると、議会へも区様式４による報告があるということでいいのかというところを確認いたします。調査結果の公表とありますので、個人情報はもちろんマスキングが必要だと思うのですけれども、ホームページ上にも区様式４による公表が行われるという理解でよろしいでしょうか、お願いいたします。","respondent":"丸谷教育総合支援センター長","answer":"品川区いじめ対策委員会の調査結果についてですけれども、様式４をかがみ文のような形で作成して、区長への報告を上げる形になっております。","voiceIndex":352,"id":"exchange-156"},{"speaker":"松本委員","kind":"質問","question":"そのうち４件は調査終了と書かれていて、時間がある程度たっているのかなと思うのですが、こちらはそういう意味では、今のお話を踏まえると、保護者への説明と区への報告というのは、もうなされたという理解でよろしいでしょうか、お願いします。","respondent":"丸谷教育総合支援センター長","answer":"調査結果が出ましたら、速やかに保護者にはお送りし、区長報告も併せて行うような形になっておりまして、記載の４件につきましては、その手続を進めているところです。","voiceIndex":354,"id":"exchange-157"},{"speaker":"松本委員","kind":"質問・要望","question":"一方で、まだ議会への報告というのはなされていないということなので、恐らく同意のところで時間がかかっているのかなと思います。ただ、どうしても長く時間がかかり過ぎると、我々としても審議できないというか、議論できないというところがありますので、できるだけここは迅速に行っていただきたいと思います。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":356,"id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"区長部局は、いじめ早期発見・早期解決に向けた機動的な対応を図っていますが、より一層教育委員会との連携・協力の下、区長部局によるいじめ防止策の対策を総合的かつ効果的に推進していくため、品川区いじめ防止対策推進条例の一部改正を行うものですが、一方で、教育委員会制度は、教育の中立性・継続性・安定性を確保するため、学校などの教育機関を管理する責任は。","respondent":"丸谷教育総合支援センター長","answer":"いじめへの対応につきましては、先ほども答弁させていただきましたけれども、一義的には学校、教育委員会が対応するものです。","voiceIndex":358,"id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"今回はそれだけ大きな変更があったかと思います。そしてクラスの生徒も、先生に疑われたり、生徒同士で疑い合ったり、つらくて嫌な学校生活を送ったと思いますが、こういう場合は本当に迅速な対応が必要だと思いますが、これについて、教育委員会のご見解をお聞かせください。子どもたちの対応について教えてください。","respondent":"丸谷教育総合支援センター長","answer":"警察への相談につきましては、事案が立て続けに起こることで相談を行っていまして、それでもなお解決できなかった事案と考えております。","voiceIndex":360,"id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"警察関係者の方は、監視カメラをつけたらどうですかと。一刻も早くこういうことは解決して、早く子どもたちの学校生活から取り除いてやる。そういうことを考えます。それが、何か理由があって、監視カメラの設置については、教育委員会も学校の管理職も、今回は見送るという判断をされています。これはどういうことですか。どういうわけですか。教えてください。","respondent":"丸谷教育総合支援センター長","answer":"当時はそういうことも考えながら、当時の教育委員会が判断したですけれども、今回、いじめ対策委員会の調査結果につきましても、こういったカメラの設置であるとか、有効な機器は場合によっては使っていきましょうという答申をいただいていますので、今後。","voiceIndex":362,"id":"exchange-161"},{"speaker":"須貝委員","kind":"質問","question":"ですけれども、社会がこれだけ変化している中では、教育委員会も外に出て、一般社会はどうなのか、どういう問題があるのかということを、私は真剣に考えてほしいのです。これがもし我が子だったらどうなのでしょう。そう思うのが親心であり、それを知っているのは教育委員会ではないですか。学校ではないですか。学校長もそう。でも、現実は違うではないですか。もう一度お聞きします。","respondent":"丸谷教育総合支援センター長","answer":"カメラを設置するにしても、工事に一定程度の時間がかかる等、そういうことも当時検討されておりまして、あしたからできる対策は何なのかということで検討した結果、見守りの強化であるとか、そういった方法を取ったと捉えてあります。","voiceIndex":364,"id":"exchange-162"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際、そんなことはできないではないですか。げた箱をずっと誰かが張っているのですか。いろいろやっているのだと思いますが、私はそういうところはしっかり対応してほしいと思います。これだけ１００年以上続いた制度に対して、どうしても我々は変わっていっていますけれども、学校の中、それから教育委員会の制度というのは、従来どおりのやり方でずっと来ているというのが現実です。私は何度も聞きました。","respondent":"丸谷教育総合支援センター長","answer":"授業を妨害してしまう児童・生徒への対応についてですけれども、一時的に授業から抜き出しをして指導をするといったことは、これまでも行ってまいりました。","voiceIndex":366,"id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"今の答弁もそうなのですけれども、そんなにすぐ、私が悪かったのです、一緒に皆さんと、これからは仲よくやって授業を受けますという世界ではないではないですか。その子たちがいたら、いっときだけやって、指導して戻しますという考えではなくて、当面落ち着くまでは別室で授業をして、ほかのお子さんに迷惑がかからないように対処するべきだと私は思いますが、もう一度お聞かせください。","respondent":"丸谷教育総合支援センター長","answer":"しかしながら、授業を妨害してしまう落ち着かない児童・生徒も、本当はみんなと授業を一緒に受けたいのだとか、何らかの心の中のＳＯＳを発信していると捉えておりまして、そういったところを丁寧にケアしていく、そして授業に戻していく。","voiceIndex":368,"id":"exchange-164"},{"speaker":"須貝委員","kind":"質問","question":"今までそうやってきて、結局、このまま学級崩壊、学校崩壊になっているのではないですか。このジレンマもあると思うのですけれども、できないならできないなりの対策を、きちんと考えるべきではないですか。今、様々な問題がありますけれども、これに対して抜本的な対策というのはお持ちなのですか。どうすれば学校生活はよくなるのですか。その対策というのはお考えなのですか。お答えください。","respondent":"丸谷教育総合支援センター長","answer":"荒れた後の対応を繰り返すのではなくて、そうならないような学校づくり、学校風土を醸成していくことが大事だと考えております。","voiceIndex":370,"id":"exchange-165"},{"speaker":"須貝委員","kind":"質問","question":"私たちは小・中学校のときは先生にたたかれ、廊下に立たされ、バケツを持っていろと。でも、みんなそれなりに成長して、仲よく暮らしていきました。今は何も、どなってもいけないのです。もちろん、立たせることもいけない。こんなことで本当にいい子どもたちを立派な社会に押していけるのですか。羽ばたかすようにできるのですか。もう時間がないので、一応その辺について、また次回質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":372,"id":"exchange-166"},{"speaker":"鈴木委員","kind":"質問","question":"私からは、３７２ページの教育指導費から、教員の働き方改革について伺いたいと思います。私の学校は、朝６時過ぎから働き始めています。校庭で遊びます。子どもたちは、先生に１人でも振り向いてほしいのです。こういう状況を伺って、本当に先生たちが子どもたちに寄り添って、必死に頑張っている姿を想像して、胸が熱くなる思いがしました。国の対策も含めて何が必要と考えるのか、伺いたいと思います。","respondent":"中谷指導課長","answer":"教員の悩みに対応できるように、管理職がどのように若手教員とお話をし、配慮していくべきなのかといったところを、しっかり手引を基に活用し、実践できるようにしてまいりたいと思います。","voiceIndex":374,"id":"exchange-167"},{"speaker":"鈴木委員","kind":"質問・要望","question":"病休を取られている方に対しての補充ができていない欠員、それから産休・育休の補充ができていない人数も教えていただきたいと思います。今、区の固有教員というもののお話もありましたけれども、これをぜひ増やしていただきたいと思うのですが、現在何人いて、これを働き方改革のためにも増やしていただきたいと思うのですけれども、この点もいかがでしょうか。よろしくお願いします。","respondent":"中谷指導課長","answer":"固有教員ですけれども、現在２５名でやっておりますが、次年度、まず３０人を満たすためにという目標とともに、段階的に、行く行くは各学校に１人配置できるようなシミュレーションで増員をしてまいりたいと考えています。","voiceIndex":376,"id":"exchange-168"},{"speaker":"大倉委員","kind":"質問・要望","question":"学校の改築のところで言うと、以前も少しお話をさせていただいた、学校自体が地域の歴史だと私は思っていて、今までの学校を卒業した卒業生も含めて、コミュニティ・スクールも進めていく中で、そういった歴史を新しい子どもたちもしっかりと知っていくということは必要だと思っていて、その際に、ＶＲを活用してインドアビューみたいな形で、学校をアーカイブとして、記録として残していくという取組は。","respondent":"中谷指導課長、吉田品川図書館長、丸谷教育総合支援センター長、森学校施設担当課長","answer":"次年度、そのような研修会を実施していきたいと考えています。この辺もハード、建物に依存してしまう部分もありますが、品川区内の図書館でどのようにできるかということについては。今年度も、弁護士をお呼びした授業は３校で実施しているという実績がありますので、こうした実績を踏まえながら。委員ご紹介のＶＲ等につきましては、区長部局では導入するというお話も聞いておりますので、導入したところの状況等を確認しながら。","voiceIndex":379,"id":"exchange-169"},{"speaker":"大倉委員","kind":"質問・要望","question":"次に行きます。市民科でしょうか、地域の方とかに学ぶ学習があると思うのですが、そういったところの費用、予算化のところで、現状どうなっているのかというところと、学校で必修科になっている授業において、予算化がなかなかできていないところがあると思っていまして、そこはしっかりと必修授業としてある中では、予算もつけながら実施をしていただきたいと思いますが、いかがでしょうか。","respondent":"丸谷教育総合支援センター長、柏木学務課長、中谷指導課長","answer":"地域の歴史文化学習ということで実践しているものがございまして、こちらは謝礼として、１回３,０００円の商品券をお渡ししているものです。ただ、活用方法等で差があったりというのがございまして、今、ＩＣＴ支援員が、試行ではありますけれども、実際、学校の使い方でよかったこととか。そのためにも、研修会から顔の見える関係をというところで、まず教員同士がしっかりコミュニケーションが取れるようにしてまいりたいと考えています。","voiceIndex":384,"id":"exchange-170"},{"speaker":"大倉委員","kind":"意見","question":"タブレットについては、リースが令和８年ということになると、今後どうしていくかというところでは、今、運用はある程度、軌道に乗ってきているというところで、このままタブレットでいくのかなというところは理解しました。先ほど来あったいじめも定量化して、この子が少しいつもより体調が悪そうとかと分かれば、いろいろな人の目に触れると思いますので、そういったところも今後お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":388,"id":"exchange-171"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは３９５ページ、学校施設建設費、城南第二小学校、３７３ページ、修学旅行費について伺ってまいります。昨年の決算特別委員会で、校舎を改築中である東品川の城南第二小学校について、通学路の安全について要望させていただきました。そこで決算特別委員会で、地元の皆さんから要望があって、学校側からの要望もあって、そして私も現場を拝見して、議会からも要望させていただきました。","respondent":"森学校施設担当課長","answer":"城南第二小学校の工事中の通学路の件です。委員ご指摘のとおり、様々なご意見を賜りまして、まず道路課で、北側の道路の学校敷地側の４０ｃｍほど、路肩の部分を広げて、ラバーポールも移設した上で、ペイントをし直し、児童が歩きやすいように道路を改修しています。","voiceIndex":390,"id":"exchange-172"},{"speaker":"あくつ委員","kind":"確認","question":"１１月１８日に、私も交通誘導員から連絡をいただいて、あとは校長からも連絡をいただいて、現場を見に行ってまいりました。もう１点加えまして、城南第二小学校の区内の学校建築現場についても、通学路の安全をご確認いただいたということですが、これは後で聞いたのですけれども、城南第二小学校のように交通安全の工夫が必要であったところがあったのか、また、どのような確認をされたのか教えてください。","respondent":"森学校施設担当課長","answer":"現在工事中の他の学校についてです。教育委員会から道路課に情報提供して、確認をしていただきました。道路課で確認していただいたところ、安全対策を取るところは特にはないと聞いてあります。","voiceIndex":392,"id":"exchange-173"},{"speaker":"あくつ委員","kind":"提案","question":"ベーシックサービスの観点から、教育に係る費用の無償化について伺ってまいります。昨年の区議会議員選挙前の３月に、区民の声を集めまして、区議会公明党として、エネルギー価格・物価の高騰対策に関する緊急要望というものを、森澤区長へ直接申入れをさせていただきました。私も政調会長として、当時その取りまとめを行って、５点の要望を申し上げました。この動きを見て、東京都は補助金をつけた。","respondent":"柏木学務課長","answer":"今後の修学旅行費の無償化の検討ですが、まず、委員からもございましたが、給食の無償化、あと、補助教材の負担軽減事業をしっかりしていって、その上で修学旅行の無償化について検討する必要があれば、財源も含めて検討したいと考えています。","voiceIndex":394,"id":"exchange-174"},{"speaker":"あくつ委員","kind":"質問","question":"答えにくいところをいろいろ答えていただいて、ありがとうございました。時間がないので質問に参ります。最後になりますけれども、こうした厳格な働き方改革の適用によって、工期とか予算等に影響が生じた場合、そのしわ寄せが現場や下請に行かないように、受注者である事業者の申出があった場合、発注者である自治体が柔軟な対応を取る必要があると思いますが、発注者である教育委員会のご見解を伺います。","respondent":"森学校施設担当課長","answer":"今後につきましては、４週８休ができるように、様々対応を取っていきたいと考えております。","voiceIndex":396,"id":"exchange-175"},{"speaker":"あくつ委員","kind":"確認","question":"国からの通知があったかどうかというのを確認させてください。","respondent":"森学校施設担当課長","answer":"国からもそのような通達が出ておりますので、それを踏まえまして、しっかり考えてまいります。","voiceIndex":398,"id":"exchange-176"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３７５ページ、いじめ防止対策費についてお伺いします。来年度、いじめ防止に向けた予算が大幅に増額されております。区のいじめ根絶に向けた強い意気込みを本当に感じております。大前提として、いじめの認知件数および出現率が３年連続増加していることは、非常に大きな課題だと私は思っております。その原因というのは何と考えているのか、お知らせいただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"いじめの認知件数、出現率の増加の原因ですけれども、いじめそのものが増えているとは捉えておりませんで、各学校がいじめを見逃さず、適切に認知して対応している結果だと捉えております。","voiceIndex":401,"id":"exchange-177"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。そうすると、それぞれの学校長の下に、そういうことをやっていくということで、私なりに認識をしました。次に、プレス向け発表の資料では、根本的ないじめの未然防止に努めて、いじめを許さない学校風土を醸成と記されております。本年度予算においても、学校風土に関する調査費が計上されていると思うのですけれども、現段階で調査から分かったことがあったら教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"今年度まで実施をしてまいったのは、学級風土調査という調査でございまして、中学校、義務教育学校７年生を対象に、学級の様子を分析し、各学校の担任が学級の実態を把握し、その後の指導に活かしてきたところです。","voiceIndex":403,"id":"exchange-178"},{"speaker":"高橋（伸）委員","kind":"確認","question":"そうしますと、来年度も、対象は７年生とおっしゃっていましたか、同じような内容でいくのかどうかというのを確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"来年度につきましては、学校風土調査ということで実施をしてまいります。学級に注目するのではなく、学校全体に注目をしていくものでして、これは１年生から９年生、全ての学年で年２回実施するものです。","voiceIndex":405,"id":"exchange-179"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"先ほどこしば委員からも質疑があったと思うのですけれども、道徳という質疑がありました。これは私も思っているところがありまして、学校任せの保護者が一定数おられると思います。これは要望で収めさせてもらいます。今申し上げたように、学校は本当に教育の場だと考えています。そこで、来年度に向けて、品川の教育について、改めて来年度の教育についてお伺いしたいと思います。よろしくお願いします。","respondent":"伊崎教育長","answer":"ほかの関係機関や専門機関との連携を取りながら、一人一人の可能性を引き出すことのできる品川区の教育を進めていきたいと考えております。","voiceIndex":407,"id":"exchange-180"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6697#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":128197,"voices":409}},{"id":"r06-20240321-3","meetingId":"r06-c-budget","date":"2024年3月21日","dateIso":"2024-03-21","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時２０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を110件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"おはようあります。初めに、デジタル通貨を通じた地域経済の活性化に向けて質問いたします。「Tokyo Tokyo Point（仮称）」について、東京都から都内自治体に対して何らかの情報は通知されているのでしょうか。教えてください。お聞きします。これらアプリの登録者や使用状況について教えていただきたい。このアプリを通じて区民が受ける利益は何かを教えていただきたいと思います。","respondent":"久保田企画部長、溝口防災まちづくり部長、阿部健康推進部長","answer":"「Tokyo Tokyo Point（仮称）」は、東京都の令和６年度予算に盛り込まれた事業でありますが、現在。私からは、しなみちレポートの利用状況についてご説明します。私からは、健康ポイント事業の令和５年度の実施状況についてお答え申し上げます。本年度、参加者の数は約３,８００人です。","voiceIndex":4,"id":"exchange-001"},{"speaker":"こしば委員","kind":"質問・要望","question":"先ほど健康ポイントについては、動機づけを図っていくインセンティブの話が出てきたと思います。一方でしなみちレポートは、道路を改善していくことで区民の「困った」を取り除く利益があると思いますが、私は本区に貴重な情報を提供してくれた区民には、相応の利益としてインセンティブを贈与する取組を検討いただきたいと考えますが、本区のお考えを教えてください。","respondent":"久保田企画部長","answer":"その意味では、しなみちレポートや健康ポイントなど、区のオリジナルアプリと連携できる可能性はあると考えているところです。","voiceIndex":8,"id":"exchange-002"},{"speaker":"こしば委員","kind":"質問・要望","question":"まさに答弁のとおり、可能性があるということで、可能性から実現に向けて取り組まれることを期待しております。その上で、「Tokyo Tokyo Point（仮称）」は東京都全体の活性化に資すると認識していますので、ぜひ品川区の独自の要望を上げてもらいたいと考えますが、お考えをお願いいたします。これまでも、品川区独自のデジタル地域通貨を求める声もありました。","respondent":"久保田企画部長","answer":"初めに、品川区としての要望のことについてですけれども、東京都の予算特別委員会の中で、区市町村に対して来年度早期に連携や活用の方向性を含めた説明会を開催する、また、地域活性化に資する仕組みとなるよう開発を進めていくというような答弁がありました。","voiceIndex":10,"id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"続きまして、２番目、童謡・唱歌を通じた心の教育についてお伺いいたします。蝉時雨を聞けば夏の訪れを感じ、鈴虫の音色を聞けば秋の訪れを感じるのが日本人ではないでしょうか。お聞きします。童謡や唱歌には、教育、情操、道徳の要素がある中で、音楽の授業はもとより、様々な場面で童謡や唱歌が歌われる機会をつくり出していただきたいと考えますが、併せてお考えを教えてください。","respondent":"米田教育次長","answer":"その意義につきましては、音楽科の意義でもある、音楽のよさや楽しさを感じるとともに、思いや意図を持って表現したり、味わって聞いたりする力を育成するとともに、音楽と生活との関わりに関心を持って、生涯にわたり音楽文化に親しむ態度を育む中で。","voiceIndex":12,"id":"exchange-004"},{"speaker":"こしば委員","kind":"質問・要望","question":"まさに総合的な学習、生活科、また体育、国語科でも応用されるという認識です。ぜひ展開していただきたいと思います。そのきっかけづくりとして、区主催のリカレント教育を設けて、童謡を大人になってから学ぶ機会をつくるのも検討してみてはいかがでしょうか。併せてお考えを教えてください。","respondent":"廣田文化スポーツ振興部長","answer":"例えば高齢者の施設等において、音楽療法の一つとして童謡を用いまして、精神の安定や脳の活性化、認知症の予防などに有効という見解もございまして、童謡に触れることは一定の効果が見込まれると言われていると認識しています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"こしば委員","kind":"質問","question":"ぜひ区民のニーズも取り上げて、前に進めていただければと思います。学びには繰り返しが必要です。この、繰り返し童謡・唱歌が歌われる環境。例えば、学校行事、地域行事、地域のパトロールにも童謡を繰り返し流していく取組は、これまでにありましたでしょうか。教えてください。なければ、ぜひ検討をお願いしたいと思いますが、お考えを教えてください。","respondent":"米田教育次長","answer":"区立学校の閉校式の折に全校で「ふるさと」を歌い、母校に別れを惜しんだ学校もありました。市民科で実施している、障害のある方やお年寄りの方と接する機会に、そうした歌での交流活動を充実していくことも、共に学ぶ機会として重要なことであると認識しております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"こしば委員","kind":"質問・要望","question":"まさに様々、運動会等でも活用されていると認識しております。ペットとの共生社会について伺います。これからの品川区は、犬をはじめとしたペットとの共生社会の実現により、豊かな暮らしを求める区民が多くなると想像されます。ドッグランの設置は、犬が走り回れる環境を求める飼い主の方からは評価されます。そういう状況下でどのようにドッグラン設置に向けて進めていくのか、お伺いいたします。","respondent":"溝口防災まちづくり部長","answer":"そこで、令和６年度に予算計上しておりますドッグラン設置検証では、令和５年度下半期から試験的に実施しております愛犬マナー教室や講習会の開催時に合わせて設置しております仮設のドッグランを継続しながら、利用者の方の声、またはほかの公園利用者。","voiceIndex":18,"id":"exchange-007"},{"speaker":"こしば委員","kind":"質問","question":"ご答弁のとおり、周辺の方々の声も必ず聞いて取組をお願いしますとともに、具体的に現在で区内のどの公園をドッグラン仮設の場所にしようと検討されているのか、教えてください。その公園以外の設置について、今後の展開についても併せて教えてください。","respondent":"溝口防災まちづくり部長","answer":"他の公園の展開につきましてですが、まずは現在、令和６年度から具体的に実施を進める取組を継続して実施して、その効果や区民・公園利用者等のご意見といったものを参考にしながら、今後の展開について検討していきたいと考えているところです。","voiceIndex":20,"id":"exchange-008"},{"speaker":"こしば委員","kind":"質問","question":"多くの区民から愛され、利用されるドッグランが設置されることを望みますが、いろいろな考えがあると思います。考え方も生活感も多様化した現代だからこそ、それぞれに配慮されたドッグランが望ましいと考えます。そのようなドッグランとなるために、区は、どのようなことが必要であって、またどのような点が重要であると考えますでしょうか。お伺いいたします。","respondent":"溝口防災まちづくり部長","answer":"飼い主の方にマナーの向上といったものも図っていただかなくてはいけないところもありますので、設置だけでなく、マナー向上に向けた取組といったものを併せてやっていくことが重要と考えているところです。","voiceIndex":22,"id":"exchange-009"},{"speaker":"こしば委員","kind":"質問","question":"そういう中で、１００％は難しいので、その中で６０％、７０％といった着地点を共に考えて、前に向けて実施していけることを期待しまして、最後の質問に移ります。４つ目は、品川区シビックプライドについて伺います。ただ、最近では品川区歌をお聞きする機会はほとんどないのですが、そもそも品川区歌の意義は何でしょうか。現在ではどのような場面で歌われているのでしょうか。教えてください。","respondent":"久保田企画部長","answer":"「品川区民の歌」が区民の方々に広く伝わっていないということは私どもも認識していますけれども、時期を同じく制定されました「品川音頭」や「品川甚句」は、区民まつり等で広く親しまれており、区民の郷土愛を育む力になっているのではないかと考えているところです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"こしば委員","kind":"質問","question":"部長の答弁から、「連帯感」、また「ふるさと」、「郷土愛」という言葉をいただきました。今の区歌をこれからも続けていくのか、展開されていくのでしょうか。お考えを教えてください。これからの未来を切り開く若い方々が口ずさみたくなるような歌を、品川区の言わば公式の歌として展開することで、品川区の新たな誇りが生まれてくることを期待いたしますが、併せてお考えを教えてください。","respondent":"久保田企画部長","answer":"そうした中で、今後、検討していく展開の中では、令和６年度から推進していきます都市ブランディング事業の中で、区民の歌の活用ということも、品川のブランドの可視化の手法の一つとして捉えまして、区民とのワークショップ等を通じて検討していきたいと考えているところです。","voiceIndex":26,"id":"exchange-011"},{"speaker":"こしば委員","kind":"質問","question":"様々なシビックプライドの選択肢があると思います。その１つの選択肢として考えていただきたく、質問をさせていただきました。以上で、私からの質問は終わらせていただきます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"西村委員","kind":"質問・要望","question":"議員の役割は、区政のチェックと、自らを選んでくれた区民の声をつぶさに聞いて分析し、区政への反映を求めて政策要望を行うことだと考えます。デフリンピック２０２５に向けて伺います。昨年１０月に行われたアイルしながわでの「デフスポーツ＆アートフェア」に私も伺いましたが、障害を持っている方たちへの理解について、スポーツを通じての取組を推進していただきたいと思います。そこで、伺います。","respondent":"廣田文化スポーツ振興部長","answer":"啓発イベントにおきましては、選手との交流に加えまして、様々なコミュニケーションツールのご案内や、手話の体験をする場も設けたいと考えているところです。開催に当たりましては、集客が見込める文化イベントと同時に実施いたしまして、効果的に実施したいと考えております。","voiceIndex":30,"id":"exchange-013"},{"speaker":"西村委員","kind":"質問","question":"現在の認知度はいかがでしょうか。目標数値を掲げてほしいと思いますが、いかがでしょうか。パラリンピックのときも、目標数値を掲げて上位にまでなっていたと記憶しておりますので、併せて伺います。自治体連携をどのようにお考えでしょうか。子どもたちの交流、文化交流、観光地としてのおもてなし企画など、品川区らしい区への呼び込みをぜひ展開されたいと思いますが、ご見解を伺います。","respondent":"廣田文化スポーツ振興部長","answer":"交流についてなのですけれども、品川区の近隣で開催されるのが、大田区、世田谷区などが挙げられるのですけれども、現在、東京都との情報共有に努めておりますが、練習場所や宿泊場所については、今、調整中というところと、スケジュール等について。","voiceIndex":32,"id":"exchange-014"},{"speaker":"西村委員","kind":"質問・要望","question":"ぜひ近隣区との自治体連携に積極的に取り組んでいただきたいと考えています。スポーツが与えてくれる力というのは本当にすばらしいと思いますので、ぜひとも積極的に取り組んでいただきたいと思います。観光施策は、これまでの実績もありますので、品川区らしい施策を要望させていただきたいと思います。次に、教育、子育てについて伺ってまいりたいと思います。見解と取組を伺います。","respondent":"米田教育次長","answer":"一方で、学校を取り巻く環境が複雑化・多様化し、求められる役割が拡大していると認識しております。区教育委員会では、教員一人一人が健康で生き生きと働くことができる環境の整備を行い、学校教育の質の維持向上を図っているところです。","voiceIndex":34,"id":"exchange-015"},{"speaker":"西村委員","kind":"質問・要望","question":"特に人員の部分で強化していただけることは大変ありがたいと思います。とはいえ、これほどに先生という職業が求められるのは、教育が人間を育てる基盤として重要だからであります。保育園、幼稚園、学校などでの相談は、どうしても子どもの相談になりがちです。今、子育て中の親たちがどのようなことに悩んでいるのか、子ども家庭支援センターに届く声、相談内容としてどのような声が届いているかを伺います。","respondent":"柏原子ども未来部長","answer":"育児しつけ相談につきましても、家庭内における幼児のしつけ等の相談ですが、令和４年度は１１７件ございましたけれども、令和５年度は現在においてもう１１８件になってございまして、年度末に向けてはさらに多くなってくるだろうというところを見込んでいるものです。","voiceIndex":36,"id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"相談件数が増えているというのは、一方で相談しやすいということでもあると思います。子育ては、誰かに教わる機会はあまりなく、我流になりがちです。今の社会に足りないことは、子どもが育ち、家族も育つ芽を育むために、大人が学ぶことだと考えています。次年度の取組と、区の見解をお聞かせいただきたいと思います。新しく始まるこの講座の目的と狙いをお伺いします。","respondent":"柏原子ども未来部長","answer":"令和６年度予算に提案させていただいている事業についてご案内させていただきたいと思います。親と子の関係を育てる専門プログラムということで実施を予定してございまして、構成は大きく２本立てを考えてあります。","voiceIndex":38,"id":"exchange-017"},{"speaker":"西村委員","kind":"質問・要望","question":"大人が子育てについて学ぶことは、青年期に起こる家庭内暴力や無気力などの問題行動を予防する発達予防学という観点においても重要だと伺いました。親子関係形成講座は、いずれ職員が自立して講師ができるようにファシリテーターを習得するとも伺っております。この講座の案内は、ぜひ不登校児童・生徒の保護者にも伝えて、様々に周知に取り組んでいただきたいと要望いたします。ご答弁をお願いいたします。","respondent":"米田教育次長","answer":"いずれにしましても、ただ１つ同じ課題はなく、個々の課題の状況を整理・把握して対応に努めていく必要があり、課題を解決していく上で、家庭との連携は必要不可欠であると考えております。","voiceIndex":40,"id":"exchange-018"},{"speaker":"西村委員","kind":"質問・要望","question":"品川区立で自立を促す場所、都会にいてしんどくなってしまったのであれば、自然の中で過ごす機会を提供できないでしょうか。現在、登校が難しい児童・生徒や希望する家庭に対して検討してみるのはいかがでしょうか。日野学園ほか区内３校でコロナ後に再開している勉強合宿の実績も活かせるのではないかと思います。宿泊型の学びの場のモデル実施をご検討いただきたいと思いますが、ご答弁をお願いいたします。","respondent":"米田教育次長","answer":"教育移住については、子どもや保護者が考える、よりよい教育環境が整った地域に移住することであり、その実行については、保護者や本人の意向によって実施されるものであると認識しております。","voiceIndex":42,"id":"exchange-019"},{"speaker":"西村委員","kind":"質問・要望","question":"ここで１つ、３年生の頃からほとんど学校に行かなくなり、教育移住した保護者の声を届けします。学校は居場所です。次に、職員の働き方について伺います。職員の働き方、職場環境をよくすることは、区が住民に対して負っている役割を全うするための重要な基盤であることを改めてご認識いただきたいと思い、お伺いいたします。ハラスメントがあったとの訴えは何件ぐらい届いているのか、伺えればと思います。","respondent":"堀越総務部長","answer":"それからハラスメントの関係ですけれども、パワーハラスメントにつきましては、相談全体としては２３件で、申出者が調査を希望されて、調査して対応したものが６件で、セクシュアルハラスメントは数件相談があって、いずれも相談対応をして、解決に向けて対応したものです。","voiceIndex":44,"id":"exchange-020"},{"speaker":"西村委員","kind":"質問・要望","question":"昨年、全庁的にアンケートを取ったと伺っておりますが、アンケートでどういう課のご意見が多かったのか、具体的にどのような内容か、お話しいただける範囲でお願いしたいと思います。次年度、コンプライアンス推進担当ができると伺っておりますが、こちらも併せてお伺いいたします。これは非常に重要なことであり、ガイドラインなどの策定を求めますが、いかがでしょうか。","respondent":"堀越総務部長","answer":"改めてガイドライン等の対応についても検討していきたいと考えているところです。","voiceIndex":46,"id":"exchange-021"},{"speaker":"西村委員","kind":"質問・要望","question":"人事当局を中心に、２３区でもトップクラスの働きやすさを実現していただきたいと考えています。最後に、これまでの歴史も踏まえまして、お伺いしたいと思います。新しい体制になるにおいて何を望むのか、これまでどういう思いでやってこられたのか、その中でどのような変化があり、職員や品川区役所であるべきだと思っておられるのか、最後にお聞かせいただければと思います。","respondent":"桑村副区長","answer":"どういう話をすればいいのか、少し難しいところはあるのですけれども、１つは、品川区全体というのは、区民憲章にあるとおり、江戸の昔から交易の拠点であり、文化と産業の発祥地であるということで、非常に交流が盛んで、人と人との、何ですか。","voiceIndex":48,"id":"exchange-022"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこで、予算額についてお聞きし、今後の事業継続において、財源も含めて、区のお考えを伺います。都の予算の概要をご説明いただき、事業継続の区のお考えを伺います。２０２６年度以降の事業継続において、補助が２分の１となった場合の予算規模と財源を伺います。０歳から２歳の第２子の保育費無償化と、０歳児おむつ宅配、学用品の無償化は、財源と今後の継続についての区のお考えを伺います。","respondent":"米田教育次長、柏原子ども未来部長、久保田企画部長","answer":"東京都公立学校給食費負担軽減事業、東京都の制度ですが、こちらの概要については、学校給食を実施している各区市町村が。都の補助が２分の１となった場合ですけれども、令和６年度予算案におきまして、都補助を約１億５,０００万円と見込んですけれども、これが２分の１。事業実施に際しましては、事務事業評価による課題の洗い出し等も行ってまいりますが、また財源の確保におきましても。","voiceIndex":52,"id":"exchange-023"},{"speaker":"新妻委員","kind":"質問・要望","question":"引き続き、国や都へ働きかけていただきながら、安定した財源を確保した上での事業継続を要望いたします。款別審査では、公明党が進めようとしているベーシックサービスの視点から、子ども世代だけではなく高齢世代を支援する施策の展開を求めたところです。高齢者のベーシックサービスとして、高齢者の住まいの総合的・包括的な支援について伺います。見解を伺います。","respondent":"久保田企画部長、中村都市環境部長","answer":"単身高齢者の推計は算定してございませんが、私どもで試算いたしますと、現在の単身高齢者の割合が約３９％ですので、単身高齢者は、それから推計いたしますと、令和４２年時点で約５万６,０００人になり。居住支援法人ですが、今、得意、不得意がありまして、高齢者の支援が得意だったり、ひとり親世帯の支援が得意だったりといった特徴や得意分野がありますので、それらを活かした効果的な連携と協力について検討してまいります。","voiceIndex":56,"id":"exchange-024"},{"speaker":"新妻委員","kind":"確認","question":"ただいまご答弁をいただきまして、今後、高齢者が増えること、そしてさらに単身高齢者も大幅増になることが分かりました。今回の住宅セーフティネット法の改正では、全国の好事例をモデルとして、居住支援法人となった社会福祉法人やＮＰＯ法人等が、要配慮者のニーズに応じて、安否確認、見守り、適切な福祉サービスへの連携を行う居住サポート住宅認定制度が創設される予定です。それぞれ伺います。","respondent":"中村都市環境部長、今井福祉部長","answer":"サブリースの住宅の借り上げを行う法人には、経済力や一定の条件も必要だとは思いますけれども、今後、居住サポート住宅の認定に向けてしっかりと検討してまいります。現在、区としましては、住まいの総合窓口である住宅課で相談を受ける中で、区営住宅などのご説明のほか、高齢者からのさらなる相談は、高齢者地域支援課、高齢者住宅担当で受けております。","voiceIndex":59,"id":"exchange-025"},{"speaker":"新妻委員","kind":"質問・要望","question":"昨年行った区民アンケートの、誰もが生きがいを感じ、自分らしく暮らしていくために必要な取組との問いでは、１位が子ども、２位が高齢者との結果となりました。高齢者の住宅の確保と支援を中心とした、高齢者の皆様に安心して住み続けていただける総合的・包括的な高齢者丸ごと支援をメッセージとして打ち出していただきたいことを、区議会公明党は力強く要望いたしますが、見解を伺います。","respondent":"新井副区長","answer":"加えて、やはり予算というものは、区民に対する、あるいは社会に対するメッセージだと考えておりますので、ご指摘いただきました高齢者の住まいの支援、もとより認知症対策や、あるいは担い手対策、あるいはフレイル予防といった、高齢者施策に関する政策パッケージを。","voiceIndex":62,"id":"exchange-026"},{"speaker":"新妻委員","kind":"質問","question":"引き続き、どうぞよろしくお願いいたします。そこで、在宅介護支援センターのケアマネジャーの人数を伺います。ケアマネジャーの人数は充足しているのでしょうか。お１人のケアマネジャーが担当する人数、今後の認定者の伸び率の予測をお知らせください。そして、現在、ケアマネジャーの研修や意見交換の場はどのように行われているのでしょうか。今後予定されていることを伺います。","respondent":"今井福祉部長","answer":"研修の質の平準化を図るため、国として研修実施の指導者用のガイドラインを作成して、これを私ども品川区でも活かしてまいりたいと考えております。","voiceIndex":64,"id":"exchange-027"},{"speaker":"新妻委員","kind":"質問","question":"ケアマネジャーは、ケアプラン作成、医療連携、施設等社会資源のコーディネートなど、介護サービス利用者を支え、地域包括ケアシステムを構築する役割を担っていますが、介護のご相談を受けた際、ケアマネジャーの力量は本当に様々であると実感しています。そのための品川区版ケアマネジャーガイドラインの策定を含めた、ケアマネジャーの負担軽減や質の向上において、具体的な取組を伺います。","respondent":"今井福祉部長","answer":"令和３年度から取り組んでまいりました、ＩｏＴを活用したケアマネジメント向上支援事業を踏まえ、国が推奨します適切なケアマネジメント手法をさらに進化させるツールといたしまして、令和６年度は、ケアプラン自己点検ソフトを導入・活用していく予定です。","voiceIndex":66,"id":"exchange-028"},{"speaker":"新妻委員","kind":"質問・要望","question":"最後に、八潮地区についてです。新年度の八潮まちづくり検討予算案は５７５万６,０００円、款別審査で委託費と確認いたしましたが、改めて詳細をお聞きします。次に、八潮まちづくり庁内検討会が立ち上がっていますが、継続的な開催で、八潮地域の特性を活かした八潮のまちづくりが進むよう要望いたしますが、今後の会議の予定を伺います。視察をして得られたことは何か、お知らせください。","respondent":"川島地域振興部長","answer":"庁内会議については、八潮南特別養護老人ホームや八潮南保育園跡地の在宅子育て支援施設なども八潮地区内にあることから、来年度は庁内検討会議を継続的に開催するとともに、各所管とも密接に連携し、八潮地区の特性を踏まえたまちづくりのコンセプト検討を進めてまいります。","voiceIndex":68,"id":"exchange-029"},{"speaker":"新妻委員","kind":"提案","question":"八潮南保育園跡地の子育て支援施設について伺います。例えば、食事をしながら多世代の交流ができるよう、システムキッチンなどの整備、施設の出入口にベンチの設置などを提案いたしますが、見解を伺います。次に、八潮南特別養護老人ホーム増床計画、こみゅにてぃぷらざ八潮と八潮地域センターについて伺います。併せて想定容量をお聞かせいただき、設置することでどのような効果があるのか、伺います。","respondent":"柏原子ども未来部長、川島地域振興部長、久保田企画部長","answer":"具体的にご提案のありました事項につきましては、今後、運用方法などと併せて検討を進めてまいりたいと考えています。こみゅにてぃぷらざ八潮に隣接しております八潮南特別養護老人ホームのスペースの活用につきましても。設置の効果といたしましては２つありまして、環境面では年間のＣＯ２削減量として、約３万平米の森林のＣＯ２吸収量とほぼ同じと想定しています。","voiceIndex":70,"id":"exchange-030"},{"speaker":"新妻委員","kind":"質問・要望","question":"先日、八潮在宅子育て支援施設は、都内の公共施設では初となる、既存建築物の改修でＺＥＢ認証を取得し、また八潮南特別養護老人ホームも、公立の特別養護老人全国初、また民設を含む都内の特別養護老人ホームにおいても初となるＺＥＢ認証を取得したとありました。区の指導の下、区と地域が一体となって、これからの八潮地区のまちづくり検討が進みますよう要望いたしまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-031"},{"speaker":"こんの副委員長","kind":"提案","question":"初めに、防災・減災対策のさらなる強化を求め、質問いたします。住宅建物の耐震化についてです。今朝も９時８分、茨城県南部を震源とする地震があり、品川区は震度３でした。そこでお聞きします。区内の住宅建物についての耐震化の実績や、未耐震の件数、これまでの取組への評価と、新年度に予定されている事業、在宅避難の促進策として耐震改修費用助成の増額を提案します。それぞれお答えください。","respondent":"中村都市環境部長","answer":"住宅の耐震化を推進していく中で、改修工事の助成につきまして、今後、工事費の状況や区民ニーズ等も踏まえ、しっかり検討していきたいと考えております。","voiceIndex":76,"id":"exchange-032"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"進めていただきたいと思います。積極的な事業展開をお願いしたいと思います。そこでお聞きします。耐震性を高めるための工事の具体的な内容と耐震の効果について、同じく工事の実績と課題について、区民への分かりやすい周知・啓発と、年度途中、事業予算が足りなくなった場合は補正を組むなど、積極的な事業展開を図ることを要望いたします。それぞれお答えください。","respondent":"中村都市環境部長","answer":"さらなる予算措置につきましては、予算の執行状況を確認しながら、区民のニーズや要望に応えられますように、しっかりと検討してまいります。","voiceIndex":78,"id":"exchange-033"},{"speaker":"こんの副委員長","kind":"質問","question":"次は、区民避難所の機能強化についてお聞きします。能登半島地震では甚大な被害を受けた断水によって、最大約６万６,８００戸の飲料水や生活用水が使用できなくなり、トイレ問題は深刻化しました。さて、品川区は在宅避難を促進するため、新年度は簡易トイレを区民１人２０個配布するとしたことは評価いたします。断水した際、トイレ使用後は流すためにバケツ１杯の水が必要となります。そこでお聞きします。","respondent":"溝口防災まちづくり部長、滝澤災害対策担当部長、米田教育次長","answer":"その後、追加や変更された施設につきましても、下水道局の計画等の改正に合わせまして、その都度追加し。各学校に配備しておりますＤ級ポンプや、災害対策備蓄倉庫などに配備している排水ポンプを活用して、プールの水を一時的に地上の水槽にくみ出した後。課題といたしましては、耐震化された便器数が学校ごとにばらつきがあり、これにつきましては、学校改築やトイレ改修工事に合わせて増設していく考えです。","voiceIndex":80,"id":"exchange-034"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"既に改築された学校には設置されていると認識していますが、今後、改築される２０校においても、エレベーターの設置を要望いたします。そこで、お聞きいたします。防災の観点からの学校施設の在り方についてのご見解と具体的な取組について、エレベーター設置の現状と未改築校への設置のお考え、改築は可能な限り計画を早め、エレベーター設置校の拡充を要望します。それぞれお答えください。","respondent":"米田教育次長","answer":"改築の際に必ず設置しており、今後も整備を進めてまいります。最後に改築のペースですが、現在においては年１校のペースで改築しております。財政状況等も勘案しながら、今後については検討してまいりたいと考えています。","voiceIndex":84,"id":"exchange-035"},{"speaker":"こんの副委員長","kind":"質問","question":"どうぞよろしくお願いいたします。次の質問です。障害福祉についてお尋ねします。初めに、障害者の就労についてお聞きいたします。これまで、障害のある方などは健康面に課題があるなどから、毎日６時間、年間を通じて安定して働くことは難しく、労働社会から取り残されてしまう現状がありました。さて国は、障害者雇用促進法を改正し、今年４月から雇用時間は週１０時間以上２０時間未満となります。","respondent":"今井福祉部長","answer":"最後に今後の展開についてですが、令和６年度から超短時間雇用専任のコーディネーターを就労支援センターへ配置し、企業へアプローチするとともに、働きたい障害者の方との面談を行い、超短時間雇用に適した業務とのマッチングを具体的に進めるなど、企業と障害のある人をつなぎ。","voiceIndex":86,"id":"exchange-036"},{"speaker":"こんの副委員長","kind":"提案","question":"先ほどご紹介いただきましたシンポジウムを参考に、ぜひ庁舎内で実施する超短時間就労だからこそ、様々な障害や疾患のある方々を包摂できる社会の実現のため、誰一人取り残さないインクルーシブな雇用と労働の場であってほしいと思います。そこでお聞きします。マッチング機能の充実を図るため、業務支援室に専任のコーディネーター配置を提案します。それぞれお答えください。","respondent":"堀越総務部長","answer":"令和６年度は超短時間雇用を進めるという観点から、週１２時間、これは３時間掛ける４日ですけれども、この枠を新たに設定したところです。業務支援室に集約する以外にも、各所属で直接配置ということも検討していきたいと考えています。","voiceIndex":88,"id":"exchange-037"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"ぜひ、障害部門とも連携しながら、障害者の雇用促進を図っていただきたいとお願いしたいと思います。次は発達障害についてお聞きします。しかし、就学時健康診査後、入学までの数か月で、学校との連携や支援体制を組むことは容易ではなく、また現在、相談支援や療育支援施設の現状は、供給が追いついていない状況にあり、今後、早期健診の導入とともに支援体制の拡充が求められます。そこでお聞きします。","respondent":"今井福祉部長","answer":"現在、児童発達支援センターは１か所ですが、今後、区立大原児童センターとともに、小山台住宅跡地の２か所、合わせて３か所を区内で整備していく予定です。","voiceIndex":90,"id":"exchange-038"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"今、現状をるるご説明いただきましたが、拡充に向けてご尽力いただきたいと思います。そこでお聞きします。３歳児健診と就学時健康診査での健診のタイミングや効果について、国が推進する５歳児健診の目的や経緯について、５歳児健診への見解と導入のお考えをお聞きするとともに、健診後のフォローアップ体制を求めます。それぞれお答えください。","respondent":"阿部品川区保健所長","answer":"この健診の経緯につきましては、詳細な検討の始まりにつきましては確認できてございませんけれども、２００５年４月に発達障害者支援法が施行されまして、この頃から５歳児健診の実施について専門家等からご意見が出たりしまして検討されてきたもの、また。","voiceIndex":92,"id":"exchange-039"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"国のガイドラインも参考に、進めていただきたいと思います。最後に、若者の支援対策についてお尋ねします。国の孤独・孤立実態把握に関する全国調査や、品川区地域福祉計画の事前アンケート調査において、２０代から３０代の若者の多くが孤独・孤立を感じているという結果が出ています。既に今年度は孤独・孤立に関わる関係団体や当事者へのヒアリングなどを実施されたと承知しています。そこでお聞きします。","respondent":"今井福祉部長","answer":"今年度実施した６つの支援団体へのヒアリングでは、区との連携を進める中で、さらに医療機関等との連携や、カウンセリング等のサポートの強化、地域のイベントや公共サービスとの接点を持つ必要性など、支援する側の課題認識を伺うことができました。","voiceIndex":94,"id":"exchange-040"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"男女には性差があり、それぞれ悩みも異なりますが、特に性に関する悩みなどは、多くの若者が家族や友達に相談できず、１人で抱え込み、インターネットで情報を入手できても不正確な情報もあり、気軽に相談できる環境づくりが求められます。思春期など、若者の体や性に関する悩みについての現状と課題の認識、若者支援の必要性についてのご見解、いつでも気軽に相談できる体制や場の整備を要望します。","respondent":"柏原子ども未来部長","answer":"何か不安を感じたときに気軽に簡単に相談できる仕組みは必要なものと考えてございまして、区として安心して相談できる場、またはその体制といったことは、今後、検討を進めてまいりたいと考えています。","voiceIndex":96,"id":"exchange-041"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"前向きなお考えをありがとうあります。ぜひ体制を整えていただきたいと思います。そこで、相談体制というか体制整備について、幾つか要望したいと思います。例えば保健師など専門家による相談体制、また相談についてはＳＮＳやオンラインなども可能とする体制、こうしたことを要望したいと思います。これについてのご所見を伺いたいと思います。","respondent":"柏原子ども未来部長","answer":"今お話がありましたように、対面ではない相談といったところも想定されるところです。ご提案内容も含めまして、他自治体の事例なども参考しながら、今後、検討を進めてまいりたいと考えています。","voiceIndex":98,"id":"exchange-042"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"若者支援とともに、ほかにも要望しました内容につきましても、どうぞ進めていただきますよう、よろしくお願いいたします。以上をもちまして、区議会公明党の総括質疑を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-043"},{"speaker":"山本委員","kind":"確認","question":"しながわ未来を代表して、吉田副委員長と共に総括質問を致します。区内経済の活性化と物価高対策について伺います。このポイント還元事業で使えるキャッシュレス決済事業者はどこか、ポイント還元の利用者が区民か区民でないかが確認できるのかどうか、確認できる場合は、前回の実績も含め、事業者ごとにお教えください。","respondent":"川島地域振興部長","answer":"キャッシュレス決済ポイント還元事業につきまして、物価高騰の長期化による深刻な経済的影響を踏まえまして、区民生活の下支えとともに区内経済の活性化を図ることを目的として、６月より開始予定としているものです。","voiceIndex":103,"id":"exchange-044"},{"speaker":"山本委員","kind":"質問・要望","question":"理解いたしました。切れ目のない支援の取組姿勢について評価いたします。本事業は、区の独自財源５億円を使います。来年度の春に実施する区内共通商品券に対する区の支援額２億円と比較して２.５倍です。後ほどの話につながりますが、より有効で効果的な手段を検討していくことを要望いたします。続けます。委託先および委託費用についてお教えください。利用店舗について、商品券と比較してお教えください。","respondent":"川島地域振興部長","answer":"この費用の中には、事業の企画、ＰＲ業務、各種印刷物の企画・作成、対象店舗の募集および取りまとめ、コールセンター業務などが含まれてあります。それから、利用店舗数につきましては、本年６月の実施時の利用店舗数が８,０００店舗の見込みです。","voiceIndex":105,"id":"exchange-045"},{"speaker":"山本委員","kind":"提案","question":"理解いたしました。以上を踏まえて、次の質問に進みます。次は、「Tokyo Tokyo Point（仮称）」を使った商品券のデジタル化について伺います。商品券のデジタル化については、昨年の決算特別委員会、一般質問でもご提案し、具体的にデジタル地域通貨へのステップとしての導入をご提案いたしましたが、来年度、調査費用として新たに２４２万円を計上されました。区のご意見を伺います。","respondent":"川島地域振興部長","answer":"引き続き、東京都の施策の動向を注視しながら、今後の事業の実施方法、実施手法等を検討してまいりたいと考えています。","voiceIndex":107,"id":"exchange-046"},{"speaker":"山本委員","kind":"提案","question":"今後いろいろと話が進んでいく中で、活用の前向きなご検討を要望し、次の質問に進みます。デジタル化は、行政が行う施策を効率的・効果的に進める大きな鍵となるものと考えており、本件は、２０２２年の区長選挙以来、私が繰り返し提案してきた事項です。本件においても、東京ポイントのプラットフォームを使えば、私が昨年の一般質問で詳しくご提案した区独自のポイントサービスが実現できると考えます。","respondent":"久保田企画部長","answer":"「Tokyo Tokyo Point（仮称）」についてですが、現在、東京都からこの事業の詳細な説明はありませんが、これまでの区の取組や、他の自治体での事例などを見ますと、ポイント付与によるインセンティブには一定の効果があると考えており。","voiceIndex":109,"id":"exchange-047"},{"speaker":"山本委員","kind":"質問・要望","question":"要望して続けます。品川ポイントの名称とグレードアップの事業スキームを含めての検討を要望いたします。品川ポイントの名称の使用など、東京ポイントを使って区独自のものを構築するに当たり、区から都へ、プロアクティブに動いていくことが重要だと考えますが、区のお考えを伺います。そのためには、区で活用したい施策を早めに考えていくことが必要であると考えますが、区の見解を伺います。","respondent":"久保田企画部長","answer":"東京都やＧｏｖＴｅｃｈ東京の開発状況とともに、他区の動向等を注視しつつ、区にとっての有効性やメリットを見極めながら、引き続き検討していきたいと考えております。","voiceIndex":111,"id":"exchange-048"},{"speaker":"山本委員","kind":"質問","question":"ぜひよろしくお願いいたします。次に、進め方です。これまでの繰り返しとなりますが、対象となる各課のメンバーが参加する横断的なプロジェクトチームをつくるのはいかがでしょうか。参加メンバーは、職員の方々のやりがいを重視し、希望者を募る公募形式とするのはいかがでしょうか。現場の各課にアイデアを募集し、さらに幅広い活用を促すのはいかがでしょうか。区のご見解を伺います。","respondent":"久保田企画部長","answer":"区としまして、「Tokyo Tokyo Point（仮称）」の検討に当たりましては、区民の利便性の向上や、区にとっての有効性など、横断的な視点を持ちまして、各部課と連携しながら進めていきたいと考えているところであります。","voiceIndex":113,"id":"exchange-049"},{"speaker":"山本委員","kind":"質問・要望","question":"この話が進んでまいりましたら、ぜひともご検討をお願いしたいと思います。この１年で大きく動くと考えます。今がチャンスです。ぜひともこの機会を捉え、品川区として、地域のデジタル化と、ポイントサービスを使った行政施策の効果最大化への取組を前に進めていただくことを要望し、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":115,"id":"exchange-050"},{"speaker":"吉田副委員長","kind":"質問","question":"実は、しながわ未来としては、代表質問でも款別審査でも職員の研修について伺っておりますが、問題意識が伝わっていないと判断し、再度の質問となります。１、品川区への入職に際して、基礎研修としてどのような内容の研修が何回くらい行われるのか伺います。２、講師はどなたがお務めになるのでしょうか。３、接遇研修と行政文書の作成研修については、いつの時点で行われるのでしょうか。伺います。","respondent":"堀越総務部長","answer":"そのほか、いろいろな国からの通知ですけれども、いろいろ今般のコロナ禍などもございまして、いろいろ多様な国の膨大な文書が来ているようなところもありますけれども、それをしっかり読み込むということが１つと、それから。","voiceIndex":117,"id":"exchange-051"},{"speaker":"吉田副委員長","kind":"質問","question":"今、総務部長にご答弁いただきましたが、要するに研修はできているというご認識でしょうか。今起きている事態を把握された上でのご答弁でしょうか。その２点を伺います。","respondent":"堀越総務部長","answer":"併せて、今は時代の変化が激しい時代ですので、そういった事業を企画する力と、公務員としての基礎的な知識や、今ご質問されている文書などの基礎的なベースとなる知識についても研修が必要だと思っていますし、今行っていることに加えて様々検討しながら。","voiceIndex":119,"id":"exchange-052"},{"speaker":"吉田副委員長","kind":"質問","question":"基本的な研修は全て行われているということですが、ではなぜ今、私の周辺で起きているような、適切でない行政文書の発出が複数回あるのでしょうか。それにもかかわらず、生活者ネットワークの議員が簡単に指摘できるレベルのミスがどうして起こるのか伺います。","respondent":"堀越総務部長","answer":"職員の意識や、もしかしたら故意ではなくてヒューマンエラー的な部分があったのかもしれませんが、それについても適切に対応していかねばならないという認識は持っておりますので、今お話しした、個別の事例は委員もご質問はなかなか難しいということでしたので。","voiceIndex":121,"id":"exchange-053"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ただ、現に複数回、適切でない行政文書の発出が行われており、それが、だから研修では解決しないということになるかと思うのですが、研修で解決しないなら何が必要なのか、ぜひ見解を伺います。今行っている研修では、現実に解決できていないと思います。研修の足りないところや、それから研修でできないのであればどういうことが必要か、もしお考えがあればその点についても伺いたいと思います。","respondent":"堀越総務部長","answer":"その後の適切な対応、やはりその後の事後処理に責任を果たすというところが大事であり、評価に影響すると思っていますので、こういった評価の考え方について意思啓発を図って、しっかり対応している職員が評価されるように、またミスや間違いがそのままにされることがないように。","voiceIndex":123,"id":"exchange-054"},{"speaker":"吉田副委員長","kind":"質問","question":"ごめんなさい。先ほどきちんとご答弁いただかなかったような気がするのですけれども、現在、複数、私の周辺で適切でない行政文書、これは言い方が分からないですよね。その辺は、これは研修の問題なのか、それともそのときの行政手続の過程で、少し何か気の緩みといいますか、そういうものがあるのではないかと思いますが、その点についてのご見解を伺いたいと思います。","respondent":"堀越総務部長","answer":"今のお話で、なぜなのかというところですが、もしかしたらミスがあったのかもしれませんし、それは今、具体の事例のところで、区側の見解と、受け止められる方の見解がもしかしたら異なっているのか、１つの事例としては分かりづらいですけれども、ただ、いろいろな場面で。","voiceIndex":125,"id":"exchange-055"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"だから、総務部長は今起きていることをご存じないということですよね。ミスの指摘というか……。ミスのことと、それからミスが起きたということと、そのミスの修正を、そちらがミスしたのですけれども、こちらに求められているわけです。そういうミスが起きたときの解決の仕方についても少し課題があるのではないかと思いますが、その点については、もう研修の段階ではないということでしょうか。","respondent":"堀越総務部長","answer":"研修では様々、ケーススタディーで学んで、予防的な措置を致しますし、もし何かそういうことがあったら、それはしっかりと適切に、ある意味、厳格に厳正に対応していくという考えはしっかり持っております。","voiceIndex":127,"id":"exchange-056"},{"speaker":"吉田副委員長","kind":"質問","question":"これからもそういう事態が起きないように、今回の事例も、いずれは個別の事例になっていくと思うのですけれども、そういうことも研修の中に取り入れながら、さらに検証を深めていくという見解でよろしいでしょうか。それを、担当だけでなく所管全体で解決するという姿勢で臨まれていると理解してよろしいでしょうか。接遇に関してもそういうことが起きておりますので、その点についても見解を伺います。","respondent":"堀越総務部長","answer":"接遇に当たって文書の読み込みが足りないのではないかですが、１つの事情を申し上げますと、この間のいろいろなコロナ禍やワクチンの関係など、特にそれに代表されるような、ある意味、膨大な量の文書がわーっと来ているという状況もあって。","voiceIndex":129,"id":"exchange-057"},{"speaker":"吉田副委員長","kind":"質問","question":"指摘する不適切な表現とか、そういうことが起きてしまうのはなぜなのだろうかというのが本当に疑問です。優秀さの問題ではなくて、研修によって全体で解決できる問題にしたいと思って、今日この場で質問に取り上げました。私たちが簡単に、「これは間違っているでしょう」と言えるようなことをなぜ見逃したのか。それは研修の問題ではないとしたら、何か要因が考えられるか、ぜひ伺いたいと思います。","respondent":"堀越総務部長","answer":"個別の事情につきましては、先ほどもご答弁いたしましたとおり、法令違反等に照らし合わせて、しっかり対応していかなくてはいけないという部分はありますので、それについてはしっかり対応して、それぞれ決裁する者の責任等もありますので。","voiceIndex":131,"id":"exchange-058"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そのために研修ということで伺いましたが、やはりこういう不適切な行政文書の発出というのは、もしかしたら、私も質問をしながら研修だけでは解決できないかと考えています。そちらは「こういうふうにしてほしい」、私たちは「いや、それはできません。その点については、ぜひご協力いただきたいのですけれども、その点についてご見解を伺います。","respondent":"堀越総務部長","answer":"今、お話を頂きました。所管でも説明はさせていただいているとは思います。今、個別の案件についてのお答えはなかなか難しいですので、組織として、区として対応していくということを、必要に応じて、それはしっかりと対応させていただきたいと考えています。","voiceIndex":133,"id":"exchange-059"},{"speaker":"吉田副委員長","kind":"質問","question":"この後もこの問題について個別に対応していただけると考えてよろしいでしょうか。過去にも不適切な、行政文書にもなっていないのか、一課長が勝手に出してしまった行政文書らしきものについて副区長にも対応していただいたのですけれども、そのような区としての対応を、今後このケースについても適用していただけるかどうか、伺いたいと思います。","respondent":"堀越総務部長","answer":"案件は拝見していませんので、今ここで確定的なお答えはなかなか難しいですが、区としての対応は、法令にのっとって基礎的な事務、正確な事務を行うのが区の責務ですので、それに沿って対応していく。","voiceIndex":135,"id":"exchange-060"},{"speaker":"吉田副委員長","kind":"確認","question":"これは、やはり大きな問題だと思います。これは、もしかすると研修だけの問題ではないかもしれませんけれども、私たちも一緒に解決に向けて動こうという姿勢ですので、改めてその辺について、今後も皆さん全庁的に、所管の方だけでなく対話に乗っていただけると理解してよろしいでしょうか。ごめんなさい。しつこいようですが、最後にその確認だけ頂きたいと思います。","respondent":"堀越総務部長","answer":"繰り返しの答弁になって恐縮ですが、区として基本的な考え方につきましてはしっかりとして、窓口で対応する。コミュニケーションをしっかり取らせていただく。それから法令にのっとった、それから規定にのっとった正確な事務を行う。","voiceIndex":137,"id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"日本共産党品川区議団を代表して、鈴木ひろ子委員と共に総括質疑を行います。私からは、防災対策について伺います。今回の予算案には、感震ブレーカー設置助成の対象を区内全域に拡大するなど、私たちが求めてきた予防策を強化しています。区民を守るために、公助として、被害を未然に防ぐ予防策を位置づけるよう求めます。いかがでしょうか。公助が果たすべき役割は何でしょうか。伺います。","respondent":"滝澤災害対策担当部長","answer":"さらには、荒廃した被災地にインフラなどを回復させ、倒壊家屋などを撤去して更地に戻す復旧や、被災地をよりよいまちへ再建を行う復興も、重要な公助の果たすべき役割と認識しております。これらの公助の役割を的確に実施すべく、区としてその体制整備に努めてまいります。","voiceIndex":141,"id":"exchange-062"},{"speaker":"のだて委員","kind":"質問","question":"しかし、そうではなくて、実際、災害が起きたときに、先ほど公助は２％だったということですけれども、起こった後には、なかなか実際に命を助けるというところでは難しいところがあると思うのですが、その被害を未然に防ぐというところで公助の役割を発揮することが必要だと思いますが、いかがでしょうか。","respondent":"滝澤災害対策担当部長","answer":"先ほどの答弁でも申し述べましたけれども、被害を未然に防ぐ予防策としての公助の位置づけとして、建物の耐震化・不燃化、交通ネットワークやライフラインの強靱化対策などを実施することの重要性や、区として地域防災計画において、新たに災害予防。","voiceIndex":143,"id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"しっかり位置づけていただいたということで、ぜひ、そこの役割をさらに発揮していただくように、そして区民の生命・財産を守るように、強く要望したいと思います。次に、具体的な予防策について伺います。不燃化特区で一番効果を上げている地区名と、どれだけ効果が上がっているのかを伺います。木造住宅の耐震化促進や、不燃化特区の助成制度を区内全域に拡大することを求めますが、いかがでしょうか。","respondent":"中村都市環境部長","answer":"その中で建物の除却・建て替え等の助成支援を、今、行っているところです。相対的危険度が高い対象地域において重点的な取組を進めていくといった考えです。","voiceIndex":145,"id":"exchange-064"},{"speaker":"のだて委員","kind":"質問","question":"１１.６％も効果が上がっているということで、それならば、なぜ拡大しないのか。拡大すべきだと思いますが、改めて伺いたいと思います。","respondent":"中村都市環境部長","answer":"現在、耐震診断の助成については区内全域で実施しています。今年度は耐震診断の助成率が２分の１ですけれども、令和６年度予算の中では１０分の１０の助成として、制度としてやっていきたいというところで、こういったところで予算の承認をお願いできればと考えています。","voiceIndex":147,"id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"耐震診断は全域に拡大したということで、ぜひこの不燃化特区の助成制度も対象を拡大して、さらに全区に広げて、耐震化をさらに進めていただきたいと思います。次に、上下水道の耐震化です。能登半島地震でも、いまだに石川県内約１万５,０００戸で断水しており、全面復旧は４月以降の見込みです。石川県の水道管耐震化は３６.８％にとどまっていました。それぞれ伺います。","respondent":"溝口防災まちづくり部長","answer":"財源も含め、管理する東京都において、適切かつ計画的に進められているものと認識しています。具体的に１００％という形の計画はございませんが、短期的・中期的な目標を定めて、対象施設や地区を重点化するなど、着実に耐震化について進められていると認識しています。","voiceIndex":149,"id":"exchange-066"},{"speaker":"のだて委員","kind":"質問・要望","question":"東京都の計画では、水道管の耐震化は２０３０年度末に６１％の目標ということで、１００％の計画は持っていないという状況です。区民の生活を守るために、一般会計から公費を投入し、促進することが求められています。公費を投入して上下水道の耐震化を早期に進めること、東京都に上下水道の耐震化１００％の計画を立てること、それぞれ東京都に求めていただきたいと思いますが、いかがでしょうか。","respondent":"溝口防災まちづくり部長","answer":"引き続き、上下水道の耐震化が図れるように、区といたしましては情報収集に努めるとともに、必要に応じて適切な対応といったものを行っていきたいと考えているところです。","voiceIndex":151,"id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"適切に対応していきたいということで、ぜひ公費を投入して進めるように、そして計画１００％を立てるようにということで求めていただきたい。災害用トイレが足りているとなぜ言えるのか、発災４日目以降はどうなるのか、伺います。国のマンホールトイレ整備のガイドラインの整備基準を伺います。避難所と既存公園に、下水道直結型マンホールトイレを増やしていただきたいと思いますが、いかがでしょうか。","respondent":"滝澤災害対策担当部長、米田教育次長、溝口防災まちづくり部長","answer":"国や都からの物資支援に効果的に対応すべく、品川区に届けられた物資の仕分や輸送体制を平素から確立して、災害時にも的確に対応していくとともに。今後も最新の技術を導入しながら防災力向上に努めてまいりたいと考えております。マンホールトイレ設置に当たっては、井戸等の水源の確保といったところも必要ですし、技術的な課題もありますので、公園改修の際に技術的検証を行いながら。","voiceIndex":153,"id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"４日目以降もトイレが十分足りているというような答弁だったと思いますが、輸送に関して、やはり道路は大体、この間、大きな地震が起きると大渋滞になってしまうということで、寸断されてしまう可能性もあります。だからこそ、下水道直結型マンホールトイレが大きな効果を発揮すると思いますが、いかがでしょうか。ぜひ増設していっていただきたいと思うのですが、いかがでしょう。","respondent":"米田教育次長、滝澤災害対策担当部長","answer":"学校ですけれども、品川区地域防災計画に基づく区民避難所としての機能を充実させる必要があると認識しているところです。４日目以降のトイレの充足についてですけれども、半島型地震、能登半島の場合には、骨幹路線を開通して、その後、くし形に進路を切り開くという非常に困難なオペレーションを実施しています。","voiceIndex":157,"id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"学校の避難所のトイレについても、既存のところもできるところでぜひ進めていただいて、トイレで困ることがないようにということで整備を進めていただきたいと要望しておきたいと思います。今、防災対策の予算が、この１０年間で７割以上も国では削減され、逆に軍事費は４割以上増えて、今年度予算は過去最高の８０８兆円という状況です。国・自治体がその責任を果たすことを求めて、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-070"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、ジェンダー平等推進条例、国民健康保険・後期高齢者医療・介護保険のトリプル値上げは引下げこそ、それから介護の人材確保、地域包括支援センターの設置を求めて質問したいと思います。ジェンダー平等推進条例とユースクリニックについて伺います。共産党が代表質問で求めたユースクリニックについて、区は検討すると答弁しましたが、ユースクリニックとは何か。","respondent":"堀越総務部長、柏原子ども未来部長","answer":"併せて相談体制の拡充や、それから計画的な施策の推進などについても、これから取り組みまして、各施策に条例の考え方を活かしていきたいと考えているところです。検討内容、スケジュールですけれども、こういった必要性に鑑みながら、どういった機能ができるのか、相談体制はどういったものがいいのかというのを、今後検討してまいるといったところです。","voiceIndex":162,"id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ジェンダー平等推進条例を基に、遅れたジェンダー平等をぜひとも進めていただきたいと思います。特に、自分の人生を自分で豊かに選び取る権利の保障、リプロダクティブ・ヘルス・ライツの具体化、その一つであるユースクリニック品川版を早急に具体化するよう求めて次の質問に移ります。国民健康保険と後期高齢者医療保険の保険料は、どちらも過去最大の値上げ額となるのか確認させてください。","respondent":"阿部健康推進部長、今井福祉部長","answer":"後期高齢者医療制度につきましては、令和４・５年度が１０万４,８４２円、令和６年度は１１万１５６円、値上げ額は５,３１４円で、こちらは令和７年度には１１万２,５３５円となる見込みです。その前の年が、値上げ額、増額が５００円でございまして、今回は４００円ということになっております。","voiceIndex":165,"id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２３区の区長会も、さすがにこれを放置できないと、昨年１１月に厚生労働大臣宛に、国民健康保険制度の見直しに関する提言を出しました。この中の国民健康保険の構造的課題とは何か、ご説明いただきたいと思います。国民健康保険制度が危機的状況だと、この中では述べていますが、５項目の見直しを要望しています。区民に関わる１から３項目までを読み上げて、ご説明いただきたいと思います。","respondent":"阿部健康推進部長","answer":"この提言の中の１から３項目を読み上げます。１、被保険者の低所得化や、１人当たり医療費増による保険料増は、個々の自治体の努力だけで解決できることではないことから、国民健康保険財政基盤の更なる強化及び国庫負担割合の引上げを実施することにより、制度の維持を図ること。","voiceIndex":168,"id":"exchange-073"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今ご説明いただきましたように、国民健康保険制度がいかに危機的な状況か。これは区長会の認識でもあると思います。私は経年的に、改めてどれだけ国民健康保険料が値上げされ続けてきたのか、具体的に伺いたいと思います。４０代夫婦、子ども２人、４人世帯の場合、今から１５年前、２００９年度と、新年度の保険料が幾らなのか。年収３００万円と５００万円について、それぞれお答えいただきたいと思います。","respondent":"阿部健康推進部長","answer":"４０代夫婦、未就学児の子ども２人、４人世帯の、年収３００万円と５００万円の場合の、２００９年度と２０１４年度、２０２４年度の保険料についてお答えいたします。","voiceIndex":170,"id":"exchange-074"},{"speaker":"鈴木委員","kind":"質問","question":"１５年間、実質賃金は上がっていません。しかし国民健康保険料は、今の３００万円の方でも１８万円から４０万円に、２倍以上に上がっているわけです。改めて、この保険料が妥当なのか、負担が重いとは考えないのか、伺いたいと思います。同じ収入で、しかも所得の少ない人の国民健康保険が、加入保険によってその２倍もの差があるというのは是正が必要だと思うのですが、いかがでしょうか。","respondent":"阿部健康推進部長","answer":"根本的な問題につきましては、先ほど申し述べました構造的な課題というものがありますので、こちらの解決が非常に重要であると考えているところです。","voiceIndex":172,"id":"exchange-075"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この保険料、これだけの過酷な保険料が重いとは考えない。高いとも言えない。それが区の立場でしょうか。国民健康保険料の負担が重いというのは、全国知事会も市長会も区長会も、国費を１兆円入れるべきだ、国費を増やせと求めているではないですか。それなのに、負担が重いとは区は言えないというのはなぜなのか、改めて伺いたいと思います。なぜ言えないのか。これもお答えいただきたいと思います。","respondent":"阿部健康推進部長","answer":"区といたしましても、もちろん今の状況がいいということではなく、国にも要望していることですので、引き続き、東京都、国に対して要望してまいります。","voiceIndex":174,"id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなのに、それを言えない。私は、これはこういう立場に、しっかりと区民の立場に立っていただきたいと、これは強く求めておきたいと思います。国も立っている立場ですから、そこにしっかりと立ってください。これを戻して引き下げることを求めたいと思いますが、いかがでしょうか。それから、区としてすぐにできる、１８歳以下の子どもの国民健康保険料は無料化を求めます。いかがでしょうか。","respondent":"阿部健康推進部長","answer":"現在、令和５年６月１日現在で１８歳までの被保険者の人数は４,１８８人で、これらの方に対して保険料無料化に必要な予算は約２億円と試算していますけれども、現行で既に未就学児については、既に５割、減額しておりますので、約１億５,０００万円必要と試算しています。","voiceIndex":176,"id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問・要望","question":"国民健康保険減免は、国民健康保険法第７７条で、国民健康保険料の減免ができるとなっています。ぜひ、区でできる、すぐにでもできる子どもの国民健康保険料の無料化に踏み出していただきたい。これを強く求めて、介護保険の質問に移ります。この事態を区としてどう捉え、改善のために何ができると考えるか、伺います。人材登録・紹介の仕組みを区が行うとした場合、課題が何か、伺いたいと思います。","respondent":"今井福祉部長","answer":"私ども、人材登録の仕組みにつきましては、区が行うための課題というのは、今、東京都でも福祉人材情報バンクシステム「ふくむすび」というのもありますので、こちらにも既に区内の事業者８０事業者ぐらいが登録している現状ですので、その状況を確認していきたいと考えています。","voiceIndex":178,"id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問・要望","question":"制度そのものをゆがめるものだと思います。次に、地域包括支援センターについて伺います。２３区で品川区だけが、地域包括支援センターが地域に一か所も設置されていません。それから、ぜひ地域に設置していただきたいと思いますが、いかがでしょうか。どんな活動をしているのか、ホームページでかなり詳しく紹介されている、例えば世田谷区の状況など、ご覧になられているか伺いたいと思います。","respondent":"今井福祉部長","answer":"地域包括支援センターの仕事といたしまして、地域支援の総合相談、それから虐待防止などの権利擁護事業、介護予防ケアマネジメント、包括的ケア、継続的ケアマネジメントがありますが、区といたしましても、介護保険制度の推進委員会と共に、幅広い方と共のご意見を聞きながら。","voiceIndex":180,"id":"exchange-079"},{"speaker":"鈴木委員","kind":"質問","question":"私は在宅介護支援センターにどれだけ配置されているかということで伺ったので、その数をお答えください。","respondent":"今井福祉部長","answer":"在宅介護支援センターにおける設置につきましては、今、手元に資料としては、全体の数値、保健師５人、社会福祉士２３人というのが、地域包括支援センター全体の数字ということでお答えします。","voiceIndex":182,"id":"exchange-080"},{"speaker":"鈴木委員","kind":"質問・要望","question":"実際は在宅介護支援センターでやっているわけですから、それを答えてくださいというのが私の質問でした。質問にはしっかりと答えていただきたいと思います。そして、地域包括支援センターが設置されていないのは品川区だけなのです。保健師や、そして社会福祉士をしっかりと配置していただいて、地域の質の向上のためにもぜひ進めていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-081"},{"speaker":"筒井委員","kind":"質問・要望","question":"品川改革連合を代表して、藤原正則委員と共に総括質疑を行います。事務事業評価について伺います。効率的かつ活発な質疑に資するものと言えます。品川区においては、今後とも事務事業評価によって無駄削減を行い、貴重な税金の、真に必要な行政サービスへの振り分けを、引き続き行っていただきたいと存じます。そこで、今回の事務事業評価による無駄削減の判断基準と評価の方法を改めてお教えください。","respondent":"久保田企画部長","answer":"事務事業評価についてですけれども、初めに評価の考え方等についてお答えいたします。行政評価シートを活用しまして、事業の必要性、有効性や効率性等の観点から、可能な限り定量的な数値実績に基づきまして、客観的に評価を行ったものであります。","voiceIndex":189,"id":"exchange-082"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。したがって、引き続き、評価の対象は全事務事業を行うべきと考えますが、いかがでしょうか。そして、区側の負担が増えたというのは事実かと思われるので、区側の負担軽減ということと、やはり区政の根幹であるということに鑑み、所管である政策推進担当課などの人員増強、体制の強化を行うべきと考えますが、いかがでしょうか。","respondent":"久保田企画部長","answer":"初めに次年度以降の評価についてですけれども、効果の高い評価を維持・継続するためには、評価対象事業の選定方法や評価の考え方等を整理して、めり張りをつけた実施手法を検討していきたいと考えているところです。","voiceIndex":191,"id":"exchange-083"},{"speaker":"筒井委員","kind":"質問・要望","question":"説明会についてですけれども、ぜひ区長に行っていただきたいのですけれども、事務事業評価で生み出した財源によって、ウェルビーイング予算というものを今年度つくられましたけれども、そもそもやはり、区民がウェルビーイングという言葉が分かっていないという方もいらっしゃいますので、むしろこういった事務事業評価の説明会をやることで、区長の思い、なぜウェルビーイングという言葉に引かれたのか。","respondent":"久保田企画部長","answer":"ウェルビーイング予算の編成の手法等も踏まえまして、例えばプレス発表で区長が直接ご説明をする機会、またタウンミーティング等でも、これまでの区長の考え方等を、この１年間、述べてこられたというところもあります。","voiceIndex":193,"id":"exchange-084"},{"speaker":"筒井委員","kind":"質問・要望","question":"新庁舎等建設について伺います。そこで、まず本区での官製談合防止の現状の対策はどうなっておりますでしょうか。千代田区は有識者から成る第三者機関を設置するなど、再発防止に取り組み出しましたが、こうしたほかの自治体の官製談合防止の取組を参考にしながら、本区も新庁舎等の大規模建設が控えていることに鑑み、より一層の官製談合防止の取組強化に当たるべきと考えますが、いかがでしょうか。","respondent":"堀越総務部長","answer":"品川区といたしましては、これまで取組を進めてきました取組を引き続き徹底していきたいと思っていまして、職員の守秘義務等の倫理意識の向上、研修、それから対応について適正な関係を保つということ。","voiceIndex":195,"id":"exchange-085"},{"speaker":"筒井委員","kind":"質問・要望","question":"新庁舎建設費について伺います。新庁舎の建設費用は約５６０億円とされておりますが、今述べた基金分担補助金、起債をした上で、なお幾ら分ぐらい不足していると見込んでおりますでしょうか。この不足分を補うために、そして区民負担軽減という目的達成のためには、現庁舎跡地の活用というのは収益性の高い施設建設におのずから絞り込まれると考えますが、いかがでしょうか。","respondent":"遠藤財政課長、多並広町事業担当部長","answer":"現在、幾ら分、不足しているかですけれども、庁舎整備基金で令和６年度に３０億円積み増しまして１２０億円という形になりますので、先ほどの３３８億円を加えますと、建設費の４５０億円を超える形になりますので。区といたしましては、官民連携手法の導入により、区民ニーズの実現と区民負担の軽減を両立できると考えており、今後も検討の進捗に合わせて、対話型市場調査など行いながら、検討を段階的に進めていく考えであります。","voiceIndex":197,"id":"exchange-086"},{"speaker":"筒井委員","kind":"質問・要望","question":"不足分はゼロということで、安心いたしました。よろしくお願いします。比較して約３年近くのタイムラグは、大井町駅周辺地域のにぎわいづくりなどに悪影響が出ないかと危惧しておりますが、ご見解はいかがでしょうか。新庁舎建設の遅れは牽引役の遅れとなりかねないと考えますが、大井町駅周辺地域まちづくり全体や広町地区以外の地区の再開発に対する影響は、いかがお考えでしょうか。","respondent":"有江都市整備推進担当部長","answer":"私からは、大井町駅周辺地域への影響についてのご質問についてお答えいたします。大井町駅周辺まちづくり方針では、まちづくりの機運の高まりに合わせて段階的なまちづくりを進めていくこととしております。","voiceIndex":200,"id":"exchange-087"},{"speaker":"筒井委員","kind":"質問・要望","question":"この品川駅を軸とした品川圏の発想、すなわちグレーター品川という概念を取り入れて、今後の品川駅南地域のまちづくり、ならびに品川浦周辺地区まちづくりビジョン策定を進めるべきと考えますが、いかがでしょうか。この歩行者ネットワークというハード整備ができた後には、ソフト面の充実、すなわち有機的に人と人がつながる人的交流、にぎわいづくりが必要かと思いますが、いかがでしょうか。","respondent":"有江都市整備推進担当部長","answer":"広域連携につきましてですが、品川駅南地域を含む品川駅周辺の開発は、東京都が策定しました、２０４０年代の目指すべき東京の都市像を示した都市づくりグランドデザインや、ベイエリア全域を対象とした「東京ベイｅＳＧまちづくり戦略２０２２」。","voiceIndex":202,"id":"exchange-088","title":"議員研修会の内容"},{"speaker":"筒井委員","kind":"質問・要望","question":"グレーター品川を支えとして、東京都と品川区と港区の３自治体連携の強化を行っていただきたいと考えますが、いかがでしょうか。そして、関連して、都のガイドラインでは品川浦・旧東海道地区はその他の地区としては扱われておりますが、今回のグレーター品川の概念にのっとり、もう少し重要な拠点として格上げして扱っていただくよう、都に要望していただきたいのですが、いかがでしょうか。","respondent":"有江都市整備推進担当部長","answer":"現在、東京都や関係機関、地域の再開発準備組合などと検討を進めておりまして、区としましては引き続き、地域の皆様や関係機関と連携し、まちづくりを進めてまいります。","voiceIndex":204,"id":"exchange-089"},{"speaker":"筒井委員","kind":"質問","question":"天王洲アイル地域のさらなる活性化のためには、羽田空港アクセス線の新駅誘致の場所は天王洲アイル駅が適切だと考えますが、いかがでしょうか。既に乗換えできる駅があり、商業施設は既に活性化の拠点となっておりますが、新駅誘致はこうした地域活性化効果がある地域でないと意味があまりないと考えますが、いかがでしょうか。新駅誘致の考え方を伺います。","respondent":"中村都市環境部長","answer":"東京都などの関係機関と意見交換を行う機会もありますので、そんな中で取組状況につきまして、適時適切に議会にも今後また説明・報告させていただきたいと考えております。","voiceIndex":206,"id":"exchange-090"},{"speaker":"筒井委員","kind":"質問","question":"どうもありがとうあります。ぜひよろしくお願いします。以上で私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-091"},{"speaker":"藤原委員","kind":"質問・要望","question":"私は都区制度についてお伺いします。それと、新しい新井副区長、今回の予算の特徴、そして力を入れたこと、それとお子さんの子育ての支援と高齢者の支援のバランスを改めてお伺いします。その時にぴんと来たのです。でも、２３区から選出している東京都議会議員とは、そういうお話をきちんとしているのですか。私はするべきだと思うのです。例えば財政調整の配分だって、０.１％違えば２０億円違いますよね。","respondent":"桑村副区長、新井副区長","answer":"特別区とすれば、当然、各区で、この後、品川区もやるわけですので、いわゆる東京都でやっていた事業が区に来るのだから、当然、役割分担の変更があるはずだという主張をしているわけですけれども、東京都とすると。既にこの間の委員会の中でご説明申し上げてきたところではありますが、やはり一番大きなところとしては、予算の考え方ですね。事務事業評価というものによって、これまでの予算の無駄を削減し、２０億円という財源を捻出する。","voiceIndex":210,"id":"exchange-092"},{"speaker":"藤原委員","kind":"提案","question":"７・３の仕事なのに、全然、３は２３区に入ってきていないですよね。議員や、あと、こういう議会、委員会で、いろいろ要望や提案などあると思うのですけれども、執行部としてどういうふうに、こういう案を取り上げてくれたり、行政に執行していってくれるのかという思い。議員が各それぞれ、いろいろな要望、提案、質問をしていくわけですから、その辺の思いを教えていただきたいのが１点。お願いします。","respondent":"森澤区長","answer":"そして２点目、誰一人取り残さないという点では、本当にこれも議員の皆様から様々ご指摘いただくこと、あるいは私がタウンミーティングといったところで伺う声、あるいは区民アンケート、データに基づいて頂く声といったものを総合的に勘案しながら。","voiceIndex":213,"id":"exchange-093"},{"speaker":"藤原委員","kind":"質問・要望","question":"これでふわっと終わりたいのですけれども、最後に私ですから、介護についてお伺いします。もう、今この質問をするに当たって、今までの担当部長、担当課長、毎回同じ、「できません」という答弁を頂いた中で、こういう形で予算をつけてくださって、私は感無量です。これが、２３区の中で品川区独自だということ。この改善も、ぜひこれからしていっていただきたいと思いますが、いかがでしょうか。","respondent":"今井福祉部長","answer":"それから訪問介護につきましても、今、様々な改善の事例が、それぞれのホームヘルパーの事業者からの改善例なども、国からも周知されておりますので、様々な現場でもできる改善例も含めて、事業者様の声を聞きながら対応していきたいと考えています。","voiceIndex":215,"id":"exchange-094"},{"speaker":"せらく委員","kind":"確認","question":"しかし、認可保育園に入園したい方で、主に１歳児クラスからの入園にはまだ課題があるのではないかと思いますが、区としてはどのように捉えていますでしょうか。そこで、ホームページ上に公開されている令和６年４月からの入園状況（指数）を確認しました。今回の令和６年度４月入園の１歳児クラスの応募において、１次募集、２次募集、それぞれ不承諾数とその割合を伺います。","respondent":"柏原子ども未来部長","answer":"私から、保育園に関するご質問にお答えいたします。１歳児クラスの入園についてでありますけれども、区では２年連続で待機児童対策の結果、待機児童ゼロというところで、令和６年度においても、現時点においては待機児童ゼロを見込んでいるところです。","voiceIndex":218,"id":"exchange-095"},{"speaker":"せらく委員","kind":"質問","question":"お知らせいただきまして、ありがとうあります。こちらの利用状況はいかがでしょうか。令和５年４月と令和６年３月時点の状況を伺います。品川区としては、この緊急１歳児受入れ事業費補助金を使うなどして、１歳児の受入れについて、現行の２園から拡大するなどの検討はしたことがありますでしょうか。伺います。","respondent":"柏原子ども未来部長","answer":"令和６年度におきましても、引き続き、空きのある保育園を活用した定期保育利用事業を引き続き実施してまいりたいです。","voiceIndex":220,"id":"exchange-096"},{"speaker":"せらく委員","kind":"提案","question":"利用状況について教えていただき、ありがとうございました。次に、保育園入園の調整指数について質問いたします。款別審査で伺ったところ、すまいるスクール登録者の４割ぐらいが、このＢ登録とＣ登録ということです。上の兄弟が小学校に入学しても、２人以上の子育てで、就労のために保育が必要であると考えますが、対象範囲を広げてはという提案について、いかがでしょうか。","respondent":"柏原子ども未来部長","answer":"一方で、この兄弟加点について、加点の要件を広げていくといったところがありますと、他の新規に申し込まれる第１子の入園にも影響を与えることも懸念されるといったことがありますので、この点につきましては今少し検討させていただきたいと思ってあります。","voiceIndex":222,"id":"exchange-097"},{"speaker":"せらく委員","kind":"提案","question":"民生費でも伺いました、保育施設の指導検査について、先日、世田谷区で認可外保育施設での抜き打ち検査が行われたという報道がありました。当区では保育の死亡事故というのは起きていないと思いますが、認可外・認証保育所の指導検査の結果では指導項目が示されているところもあり、巡回支援でも併せて確認していると伺いましたが、指導検査、巡回支援は事前に連絡をして行っているのでしょうか。","respondent":"柏原子ども未来部長","answer":"現在、品川区におきましては、子ども・子育て支援法に基づく指導検査を行ってあります。指導検査の実施は年１回、事前通告の上、職員が訪問して検査を行うというところになってあります。今お話がありました巡回支援につきましても、最大で年２回行っているところです。","voiceIndex":224,"id":"exchange-098"},{"speaker":"せらく委員","kind":"質問・要望","question":"小学校の朝の時間について伺います。小学校の朝の開放については、以前も、つる委員が委員会で質問をされていたのを確認しておりまして、一部の学校では早めにお預かりしている事例があると、議事録から確認いたしました。ご状況を教えてください。ニーズの部分では、保育園に登園する時間が８時より前の園児はどれぐらいいるか、事前に現状について伺っておりましたが、いかがでしょうか。","respondent":"米田教育次長、柏原子ども未来部長","answer":"現状ですが、例えば学校独自の取組として、大原小学校では特色ある教育活動として、朝のスポーツ健康タイムを始業前の７時５０分から８時１０分まで毎日実施しており、大学生が有償ボランティアで子どもたちと一緒に活動しております。これは区立保育園のみの数字ですけれども、令和６年２月の１か月の間で一度でも８時前に登園などした児童数の実数ですが、１,０９９人。在園児が４,０４２人おりますので、およそ４分の１がその数というところになります。","voiceIndex":226,"id":"exchange-099"},{"speaker":"せらく委員","kind":"質問・要望","question":"本日は、困難を抱える子どもや若者支援として、子ども若者応援フリースペースについて伺います。年齢制限なく支援をしていっていただきたいと思いますが、思いを伺えればと思います。そして、南品川児童センター改築との関係性も伺えればと思います。当区のフリースペースの活動上での支援という点から、短時間の就労体験やプログラミング学習などの支援はいかがでしょうか。見解を伺います。","respondent":"柏原子ども未来部長","answer":"区内ＮＰＯとの連携等も、児童センターでの講座内容も様々考えられますので、様々な面において柔軟に対応してまいりたいと考えています。","voiceIndex":229,"id":"exchange-100"},{"speaker":"せらく委員","kind":"質問","question":"児童センターと、子ども・若者の居場所について考えていければと思います。そこで、メタバース空間でのいじめや犯罪が発生する可能性も出てくるのではないかと思いますが、空間内での大人の見守りやトラブルが起きないような対策は考えていますでしょうか。併せて、メタバース空間の利用対象を伺います。高校生や大学生は対象に含まれていますでしょうか。","respondent":"米田教育次長","answer":"先行実施している８自治体の事例では、児童・生徒がトラブルに遭ったという報告はなく、問題なく実施できていると認識しております。もし、区において問題が生じた場合には、所管の教育総合支援センターや学校が連携し、早期の対処に当たってまいりたいと考えているところです。","voiceIndex":231,"id":"exchange-101"},{"speaker":"せらく委員","kind":"質問","question":"こちらをお聞きしたのは、不登校ではなく、家から出られないひきこもり状態の方へもオンラインでのつながりから支援することができるのではないかと考えています。子ども若者フリースペースに行けない人、人と会えない場合や昼夜逆転という場合には、どのようなコミュニティやつながりがありますでしょうか。ひきこもりの子ども・若者へのオンライン支援について、子ども未来部のご見解をお願いいたします。","respondent":"柏原子ども未来部長","answer":"なかなか現在、具体的なところでつながっている部分というのは、手法としては難しい部分がありますけれども、ご紹介がありました部分で、教育委員会で実施しているメタバースを活用した事業といったことの連携や、どのような形の支援ができるかというのは。","voiceIndex":233,"id":"exchange-102"},{"speaker":"せらく委員","kind":"質問","question":"安心して子育てができるまちというテーマで、子育て住宅について伺っていきます。今、品川区では集合住宅においてどのようなものが建てられているか、分かる範囲で、１年度のワンルーム集合住宅と２ＬＤＫ以上の集合住宅の戸数をそれぞれ伺います。持ち主がいる場合は持ち主で制度の紹介をしたり、不動産会社への紹介も可能だと思いますが、ご見解を伺います。","respondent":"中村都市環境部長","answer":"そこで、可能な限り、そういった計画や相談の早い段階で庁内所管と連携しまして、様々な情報や、また、今ご紹介いただきました東京子どもすくすく住宅認定制度といったものの積極的な紹介に努めていきたいと考えております。","voiceIndex":235,"id":"exchange-103"},{"speaker":"安藤委員","kind":"質問・要望","question":"日本共産党品川区議団が提出した、第５号議案、令和６年度品川区一般会計予算に対する修正案および、第６号議案、令和６年度品川区国民健康保険事業会計予算に対する修正案の説明をします。補聴器購入費助成の増額に伴う都の２分の１補助分繰入金を増額します。修正案に盛り込んだ事業は２２事業で、予算の使い方を暮らし・福祉優先に切り替えれば、多くの区民要望を実現することができます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-104"},{"speaker":"高橋（伸）委員","kind":"提案","question":"品川区議会自民党・無所属の会は、令和６年度品川区一般会計、同国民健康保険事業会計、同後期高齢者医療特別会計、同介護保険特別会計、同災害復旧特別会計の各予算原案に賛成します。修正案には反対します。区が直面する課題を積極的に解決すべく編成されました。予算審査で各議員が行った提案・提言が十分に事業執行に反映され、さらなる区民福祉の向上が図られることを望み、意見表明とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":242,"id":"exchange-105"},{"speaker":"若林委員","kind":"質問・要望","question":"品川区議会公明党の意見表明を行います。さて公明党は、議会質問や緊急要望を通じ、所得制限により対象者を限定せず、また経済的負担を取り除くことで、福祉や教育など、人間として必要なサービスを誰もが享受できるベーシックなサービスの実現に努めてきました。本委員会での会派からの意見・要望を真摯に受け止められ、今後の区政へ活かされるよう要望し、意見表明とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":244,"id":"exchange-106"},{"speaker":"大倉委員","kind":"提案","question":"今後も、ＡＩやＩｏＴなどの最先端技術の活用や、利便性・効率性向上につながるデジタル化のさらなる推進、産前産後子育て支援の充実、学校教育の充実、障害者福祉・高齢者福祉の充実、地域経済活性化施策の推進、防災対策の強化、環境対策の推進、庁舎建て替え、新羽田ルート問題、多様性の推進、職員人材育成強化、デジタル地域通貨やポイントサービスの推進など。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":246,"id":"exchange-107"},{"speaker":"安藤委員","kind":"提案","question":"以下、理由について述べます。理事者におかれましても、予算修正に盛り込んだ事業、補聴器購入費助成の増額、子どもの国民健康保険料無料化、大学生への給付型奨学金、各種がん検診の無料化、中小企業・個人事業主への家賃補助、３５人学級の中学校までの拡大などをはじめ、各種提案をこれからの施策に活かしていただきますようお願い申し上げまして、日本共産党品川区議団の態度表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":248,"id":"exchange-108"},{"speaker":"須貝委員","kind":"質問・要望","question":"令和６年度の一般会計、国民健康保険事業会計と、後期高齢者医療、介護保険、災害復旧の特別会計の各予算に賛成します。中小企業は、買い控えや節約で消費減少により経営が悪化し、値上げもできず、人手不足と資金難で融資返済もできず、廃業や倒産が増えているので、区は支援に一層取り組んでいただきたい。最後に、悲惨なウクライナ侵攻や中東紛争などを人類は止めるべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-109"},{"speaker":"松本委員","kind":"提案","question":"なぜ、こうした予算案が可能になったのかということについて僣越ながら私見を述べるならば、１つには、森澤区長が組織・団体支援を受けていないということが挙げられるのではないかと思います。区におかれましては、当会派各委員の質疑の中で指摘・提案した点について検討され、予算執行や今後の施策に反映していただくよう要望し、品川区議会日本維新の会の意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":252,"id":"exchange-110"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6699#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":116185,"voices":261}},{"id":"r06-20240326-10","meetingId":"r06-cm03","date":"2024年3月26日","dateIso":"2024-03-26","committee":"議会運営委員会","time":"午前１０時３０分～午後 ０時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年第１回定例会","agenda":"令和６年第１回定例会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"副区長なのですが、現在、新井副区長と２人体制かと思いますが、副区長２人のそれぞれの役割分担や分掌事務がどうなるのか、改めて教えていただければと思います。監査委員については、選任に当たり、団体などからの推薦などはあったのかということをお伺いします。どんなお仕事をしておられたのか、職歴と推薦との関わりなどがあるのかなどを含めて伺います。","respondent":"森澤区長","answer":"１点目の副区長ですけれども、基本的には、今まで桑村副区長が担っていた担務を堀越総務部長、次期副区長として選任同意いただければというところですが、というふうに考えております。具体的にお伝えしたほうがいいですか。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"西村委員","kind":"質問","question":"私自身も広報会議に入っておりましたので、様々な意見があったことを確かに聞いておりまして、まず、入稿締切りが近いということで、そのスケジュール感を伺っておきたいと思うのですが、意見としましては、在校している子どもたちの気持ちにも配慮するべきだと思いますし、その他中高生の目にも触れること、あと２次被害が様々考えられることを思うと、やはりふさわしくないなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-002"},{"speaker":"山本委員","kind":"確認","question":"何点か確認させてください。ご対応、どうもありがとうあります。１点目が、広報会議内で、リーダーや周りの委員の方がそのように控えるべきではないかというふうに言われている中で、それを踏まえたやなぎさわ議員の態度、及びそのまま掲載してほしいということであればその理由をどういうふうにコメントされていらっしゃるのかということです。","respondent":"大澤区議会事務局長、せお議員","answer":"事務的なところで、私のほうからお答えします。原稿の締切りですけれども、４月の上旬が最終稿ですので、できましたら今週中には原稿は固めていきたいというふうに考えているところです。発行者の区議会が訴えられるというところですけれども、訴えられるというか、そこまでかどうかは分かりませんが、今回区議会はどう考えているのかというところを示すためにも、本人に事実確認しているのか。","voiceIndex":62,"id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"品川翔英高校から回答が得られているわけではないということでいうと、それは正確かどうか、今の段階では確認ができないということと、せおリーダーが言われたように、品川区内の全戸に配られて、かなり影響が大きいというところで、今の段階ではそのままで掲載することは控えたほうがいいのではないかというふうに、時間も迫っているということでしたので、このまま進まないようであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-004"},{"speaker":"こんの委員","kind":"確認","question":"先ほど、せおリーダーからのご説明も伺って、またこれが非常にデリケートな問題を持っているという課題、要するにカメラが設置されているといった説明は、あくまでも目撃した方からの証言だといったところは、やはり事実が確認できないということ、センシティブな課題なので、これが設置されている、設置されていないということに対して、また学校と生徒、保護者の関係性、学校名も出ている関係性も考えると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"なので、昨日の広報会議で私がちょっと取り違えていたというところで、申し訳なかったというふうに思うので、一致したというところとは、私の思いはちょっと違ったなというところです。そうすると、もう議事録に載る前からの段階で、発言の修正というか、もう学校名は出さないでくださいということが必要だったのではないかなというふうに思うので、どうなのかなというところがちょっとあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-006"},{"speaker":"須貝委員","kind":"確認","question":"今お話があったのですが、広報会議というのは、区議会で決めたのではないですか。保護者にもそうですが、我々が調査権を持っていて、そこの現場に行って、事実確認をきちんとやったなら、５０歩譲って聞いて、どうなのかなという微妙なところはあるのですが、調査権もない中で、今回は学校名を出しましたよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-007"},{"speaker":"安藤委員","kind":"提案","question":"議会運営委員会に相談ということだったのですけれども、具体的には、どういう文言に変えようとか、何をどうする、こうしたものをこういうふうに変えるとか、こういうふうにしたいのですと、相談の内容というか、広報会議としてはこうしていきたいのだけれども、具体的に学校名は伏せるということなのか、それとも監視カメラというところが議事録と違うので、防犯カメラというふうに変えるのか。","respondent":"せお議員","answer":"広報会議の正副においても、監視カメラを防犯カメラにしたとしても、この文章全体が事実かどうか分からないので、もう全文削除したいというところから、広報会議の委員の皆様にご相談したところでありますので、まずその前提で進めています。","voiceIndex":69,"id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"その部分を全部削除という提案というか、その相談ということなのですか。分かりました。その証言を受けてやなぎさわ議員は本会議で質問したのだと思います。あるいは、証言を基に質問したということであれば、何々と聞いているとか、表現をちょっと変えてもらうとか、そういった形でできる限りやなぎさわ議員が行った質問を削除しない方向で、最後までぎりぎり努力をしていただければと私は思っています。","respondent":"あくつ副議長、せお議員","answer":"ごめんなさい、せおリーダーというよりは、今多分共通認識として、どういう文言になっているかというのは、私は見ましたけれども。質問項目の部分から、子どものウエルビーイングを守れ、ストップ、大人による子どもへの人権侵犯（品川翔英高校について）、質問が。先ほど安藤委員から修正という話もあったのですけれども、それはこれから皆さんにご検討していただくとして、今のお話だと。","voiceIndex":71,"id":"exchange-009"},{"speaker":"安藤委員","kind":"提案","question":"案文をお配りします。〔資料配付〕 右上に日本共産党品川区議団提案となっておりますけれども、この間須貝委員との協議を重ねて、共同で案文をまとめさせていただき、３月８日には第１次案というのを各会派、議員にお渡しし、検討をお願いしました。併せてご検討いただいたことかと思います。改めて案文を読み上げて、提案させていただきたいと思います。ご議論をよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":84,"id":"exchange-010"},{"speaker":"こしば委員","kind":"提案","question":"こちらの案文を見て、また検討させていただきました。幾つか指摘させていただきたい箇所がありましたので、指摘させてもらいます。それを受けての報道であったと認識しているわけです。これは明らかになったと言えるのか。本来であれば、声明の内容が報道されたといった文言、事実のみを記述すべきではないかというところで、私のほうではそういうふうに考えまして、検討しまして、提案させていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-011"},{"speaker":"こしば委員","kind":"意見","question":"こういった指摘を踏まえた上で、改めてこの文言が必ずしも、本来の事実に沿っているとは私には思えないので、そこは修正するのが本来必要な判断ではないかと思いまして、あえて指摘をさせていただいた次第です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"文言の修正に関しては意見をいただいて、ぜひ一致したものを出したいと考えていますので、よろしくお願いしたいと思います。１つだけ、表現を変えるのはやぶさかではないので、もっと事実に即した書き方ができないかというご指摘だと受け止めました。","respondent":"あくつ副議長","answer":"決して否定する意味ではなくて、私も今の質問を聞いていて、今安藤委員がおっしゃったように、できるだけ事実に即した形でないと、いやしくも１人の議員に対して、その身分を、辞職しなさいという勧告ですから、ここについては事実に即した形で慎重な文面でないと。","voiceIndex":89,"id":"exchange-013"},{"speaker":"須貝委員","kind":"確認","question":"本人に直に確認しているのですから、それを何で今になって、事実と違うのではないのですかとか、疑わしいとか、そういうことは言ってほしくない。それより、区議会がずっとこのまま長引かせて、放っておいていいのでしょうか。でも、事実ということを議長も確認しているわけですから、区民が見ているのですから、品川区議会としても速やかに、明確に態度表明をきちっとやるべきではないですか。","respondent":"あくつ副議長","answer":"これだけは言わせてください。１２月の時点で報道があって、１月の議会運営委員会まで待った。１か月間何も出てこなかったから、この議会運営委員会でどうなっているのですかと催促をした。これはもう議会運営委員会にも記録が残っていますから、それは確認させてください。","voiceIndex":91,"id":"exchange-014"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"そこからスタートしましたというふうに書いたほうがいいのではないですかというお話をしているだけで、中塚氏が行為をしていない、そういう話をしているのではないので、あくまでもこの重い案文に対してはしっかりと事実を述べていただきたいというお話をさせていただいているのみですので、そこは訂正します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"我々は被害者とは直接接触していないし、何もやり取りをしていることではないので、そこはあくまで日本共産党品川区議団からの話として伺っているということ、その上で、本人は辞職を拒んでいる、辞職を受け入れないということを言っていたということを、本人というのは中塚氏ですけれども、表現していただくといいかと思うので、ご検討いただければ、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"さっき塚本委員がおっしゃった、おとしめるというところは、２段落目の部分も入っているのではないかなと。もう一点が、議会運営委員会において、事実確認のために日本共産党品川区議団の皆さんと中塚議員双方に説明を求める声が上がって、聴取・質疑を行ったこと、また、中塚議員が事実を認めたことを記述されてはいかがかというふうに思います。","respondent":"あくつ副議長","answer":"今、西村委員がおっしゃったことの一部補足というか、私も思ったことなのですが、議会としては、一方的に中塚氏の意見を求めるということではなくて、全体的にそうなのですけれども、どうしても２次被害を防ぐという意味で、共産党の中でのものが、フィルターがかかっている。","voiceIndex":96,"id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"根拠としては何かというと、まず、議員は規範となる行動が期待され、セクハラ行為に対しては厳格な態度で臨む自覚と責任が求められる立場であるものの、それを逸脱しているということが挙げられる。以上の理由により、中塚議員自身がセクハラ行為の責任を自覚し、自らの意思で辞職するように求めるということではないかと考えます。いかがでしょうか。","respondent":"あくつ副議長、大澤区議会事務局長","answer":"私もそのとおりだと思うのですけれども、ジェンダー条例はまだ成立していない、明日成立の見込みだと思うのですけれども、それを根拠にすることが、事務局としては、何か問題がある感じがありますか、それはこちらの判断でいいのか。総務委員会で討論していたという事実がありますので、そこの部分は特に問題ないと考えています。","voiceIndex":98,"id":"exchange-018"},{"speaker":"せりざわ委員","kind":"確認","question":"今の山本委員の話とつながる部分があるのですが、被害者との接触というのが、２次被害防止ということで、我々は直接お話ししていなくて、別にそれを批判している話ではないのですが、その中で被害者の心情であったりというのは先ほどお話があって、中段のところで、辞職を強く望んでいると述べているという話があって、共産党としては当然いろいろな接触をされて、確認されていると思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-019"},{"speaker":"安藤委員","kind":"意見","question":"様々なご意見をいただいて、ありがとうあります。それで今のせりざわ委員のところです。聞き取ったことはもちろん事実です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-020"},{"speaker":"せりざわ委員","kind":"確認","question":"別に批判する話ではないのですが、共産党は恐らく本人にいろいろお話ししていると思うので、それは当たり前の話で、こういう文書が出てきているのだと思うのですが、私が聞いているのは、それ以外の方が提出者になって、例えば、区民の方からその方々にどういう形で確認を取ったのですかと問合せがあったときに、いや、伝聞の伝聞ですという話で、議会としていいのでしょうかというお話です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-021"},{"speaker":"須貝委員","kind":"確認","question":"それは幹事長と本人、中塚議員とお会いしたときに、本人にこれは事実ですかとちゃんと確認して、本人がそのとおりですというふうに明確におっしゃった。言っていること、書いていることは違いますと言うならば、我々もそれでは引き下がりますという話ですけれども、本人が明確に認めたということが、そもそも今回文面になっていると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-022"},{"speaker":"せりざわ委員","kind":"確認","question":"かみ合っていないようなので、もう一度お話ししますが、加害者という表現をしますが、中塚議員の加害行為に対して、中塚議員から事実確認をされた。加害があったのは事実だと思います。ただ、被害者の心情とか、被害者がやめてほしいと言っているというところは、どうやって確認したのでしょうか。それを確認されていないのであれば、大丈夫なのですかという確認を今しているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"実に温かい思いやりのあるお言葉ですけれども、こういうふうに相手側が言っていますという話を本人にちゃんと伝えて、本人はそういうふうにおっしゃるなら、もうそのとおりですと、そういう批判を一切本人がされないのだったら、それ以上我々もやりようがないではないですか。","respondent":"あくつ副議長","answer":"裁判ではそれは事実として認定されるのでしょうけれども、我々は裁判所でもないし、そこのところで我々が言えるとするならば、内容について我々は確認できないけれども、彼がセクハラの事実を認めた。","voiceIndex":106,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"本来なら我々は、こういう事実でセクハラを受けたという女性を呼んで話を聞くべきでしょう。だけれども、聞けないではないですか。私は痴漢を受けました、こういうことをされました、こうなのです、区議会として相手に対する思いやり、配慮というのは最大限すべきではないですか。中塚議員が、いや、こんな話、とんでもないですよと言うなら、おっしゃるとおりです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-025"},{"speaker":"安藤委員","kind":"確認","question":"それであるならば、議会としてやってきたことなわけですから、やはり辞職勧告決議というのを出さないわけにいかないと私は思います。ただ、出すに当たって、今後にも関わることですから、慎重であるべきだということは本当に理解できるのですが、ぜひ皆さんのお知恵を貸していただいて、オール議会という形で進める案件だと思っていると、２月１９日の議会運営委員会で議長にもおっしゃっていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-026"},{"speaker":"せりざわ委員","kind":"意見","question":"当たり前ですけれども、書面を見ないとやれる、やれないはさすがに言えないです。ここで案文を出していただいて、これから中身を変えるというふうにおっしゃっている中で、賛成しますという話は、我々としてはなかなかできないということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":110,"id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"まして今これからまた案文にいろいろ訂正だ、変更だとあるので、それを見ながらでないと、今度皆さんが納得できないと思うので、それは安藤委員に骨を折ってもらって、それもできるだけ早く打合せをして、皆さんの賛同を得られるような文面に仕上げていただきたいと私は思います。今回遅れたことに関しては申し訳なかったというのは、反省しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6653#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":30157,"voices":115}},{"id":"r06-20240415-10","meetingId":"r06-cm04","date":"2024年4月15日","dateIso":"2024-04-15","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"西村委員","kind":"提案","question":"品川区議会自民党・無所属の会からは、行財政改革特別委員会、災害・環境対策特別委員会ということで、同様にご提案させていただきました。簡単に申し上げますと、行財政改革特別委員会は、新庁舎や公有地活用、ふるさと納税を取り上げられないかということでご提案をしています。環境対策は、プラスチックの削減や、カーボンニュートラルの実現に向けてということで、改めてご提案しています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-001"},{"speaker":"こんの委員","kind":"提案","question":"公明党からは、大きく４つを提案しています。行財政改革特別委員会、災害対策特別委員会、ＳＤＧｓ推進特別委員会、そして、地域共生社会特別委員会という４つの提案をしています。なお、これまで例年２つで来ておりますので、その中でという形になるのだろうと思いますが、一応、４つの提案をしています。これは、在宅でも、避難所でも、両方ですけれども、避難生活に関わる相談の体制はどうなっているのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-002"},{"speaker":"山本委員","kind":"質問・要望","question":"しながわ未来からは、まず、委員会の数としては２つです。実務的な運営なども考えまして、２つの委員会がいいのではないかと考えています。１つ目の、行財政改革のところですけれども、項目としては７つ挙げさせていただいてあります。１つ目が、「新庁舎・庁舎跡地等・その他公有地に関すること」というところで、公明党からもご説明がありましたとおり、引き続き検討していく必要がある。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"数は、４つ全てが必要だという立場で提案しているわけですが、かつては３つぐらい設置していたときがあったのですけれども、４つも無理ではないのではないかなと思いますし、現在参加していない無所属議員も含めれば、３つあったときは全員参加していたようですが、同じ区民から選出された議員ですので、発言や質疑の機会になるべく差がないほうがいいのではないかということでも、全員参加が必要な４つ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"特別委員会の調査事項の報告がいろいろありましたけれども、今の各常任委員会において、私はかなりのものが調査できるはずだと考えています。したがって、特別委員会を設置する必要はないのではないか。我が会派としては、特別委員会を設置することには反対で、各常任委員会でしっかり議論するべき重要なことではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-005"},{"speaker":"西村委員","kind":"提案","question":"私どもからご提案させていただいた２つではありますが、あまり多過ぎず、しっかり密に議論するためにも２つでいいのではないかと考えています。ＳＤＧｓとなると、結構幅広かなと考えていますので、私どもからの提案で申し訳ないのですが、行財政改革特別委員会と災害・環境対策特別委員会でいかがかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-006"},{"speaker":"こんの委員","kind":"提案","question":"今、ご提案があったお話で、大体それぞれの会派から出ている共通点は、行財政改革、あるいは災害・環境といったところはまとめられるのかなという思いがいたします。今、ご提案のあった行財政改革特別委員会、災害・環境対策特別委員会というまとめ方でもよろしいのかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-007"},{"speaker":"山本委員","kind":"質問・要望","question":"しながわ未来ですけれども、私どもも委員会の数は２つがいいのかなというところで、先ほどご発言がありました会派の皆様と同様です。中身のところについては、災害・環境対策に対して、関わる内容が多いかなというところで、私どもはつけしていますけれども、行財政改革との関連性もあるかなと思いますので、どちらかの中でしっかり議論していただきたいというのが要望としています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"例えば、議員も４０人いるわけですから、必要なものにはちゃんと設置していくべきと思っています。ご存じのようにＳＤＧｓの５番目のゴールとして、ジェンダー平等を実現しようという大きなＳＤＧｓの柱の１つでもありますので、３つ目としてＳＤＧｓ特別委員会ということで、その中に私たちから提案させていただいているジェンダーの問題を入れていただく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"皆様のご意見をいただいた上で、３つはどうですかと投げかけているので、１回目はそうでしたけれども、２回目の意見を出してもらったほうがいいのではないかなと思うのですが、その上でまとめていただきたいということが１つです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-010"},{"speaker":"山本委員","kind":"意見","question":"委員会の数ですけれども、繰り返しになりますが、２つがふさわしいのかなというところがあります。理由としては何点かありますが、テーマとしてかぶるところも結構あるのかなというところで言うと、例えば、ＳＤＧｓを独立させずに災害・環境対策にすることで、一体のテーマとして取り扱える。なので、私どもの会派は２つでいいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-011"},{"speaker":"せりざわ委員","kind":"提案","question":"自民党としてお話しすると、先ほど、３つがいいのではないかというお話があったのですが、我々もそれを踏まえた上で２つがいいのではないかというお話をしていて、３つというのが新しいやり方だなという話ではなくて、３つがいいのか、１つがいいのか、ほかの数も含めて検討した結果、２つがいいのではないかというご提案をしておりますので、そこから特段意見の変更はありません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":31,"id":"exchange-012"},{"speaker":"こんの委員","kind":"提案","question":"公明党からも４本提案はしましたけれども、例えば、行財政改革特別委員会の中に、あるいは災害・環境対策特別委員会の中に振り分けられる内容でもあるので、そこは１本立てなくても、両方の中にこのことは取り入れていけるのではないかと、ほかの会派からもそうした提案の項目も出ていますので、そうした整理ができると２本でよろしいのかなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"１点だけ。今日は議会改革推進会議のリーダーの方もいらっしゃるのですが、議会改革推進会議で、様々な合理化、行政改革等を進めて、議会改革も第一線として進めている。意見だけ言わせてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"調査事項については、行政のデジタル化とおっしゃいましたけれども、行政だけではなくて、デジタル化広義で地域のデジタル化なども議論していただきたいというところもありますので、併せて調査事項については、別途、この２つの委員会の中で改めてご調整をいただきたいと思ってあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":38,"id":"exchange-015"},{"speaker":"安藤委員","kind":"提案","question":"今、挙げてもらったものにということであれば、さらに細かいところに入るのかというところがあるのですけれども、思いとして、自民党から出されていたごみ収集の有料化があるではないですか。これも非常にいい提案ではないかと思いますので、私たちとしては、少し項目が多くなってしまうのですが、ぜひ特別委員会で議論していただいてもいいのではないかなというご意見を伝えします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":41,"id":"exchange-016"},{"speaker":"こんの委員","kind":"提案","question":"調査項目の備考欄で、これと、あれと、それとと入れていくような形で、大きく「災害に関すること」と、リサイクルや脱炭素のほうは、環境に関することなので、「環境に関すること」と大きく２つにして、備考欄で細かい調査項目をどのような項目にしたらいいのかとまとめてみるのもいいのではないかと思うのですが、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-017"},{"speaker":"山本委員","kind":"提案","question":"行財政改革特別委員会で「新庁舎等」の「等」というのは、跡地やその他公有地の活用も含むということでいいのか、１点ご確認。具体的には、これで言うと、特に災害・環境対策の中に入れるのがよいかとは思いますが、調査事項で複数の会派から明確にご提案がありますので、入れていただきたいです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-018"},{"speaker":"こんの委員","kind":"確認","question":"１点だけ確認です。今のそれぞれの会派の意見を踏まえてというご説明です。そうすると、例えば、調査事項が決まって、その中のいろいろな項目というか、調査の備考はどのように出されていくのですか。それは、ここではやらないのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-019"},{"speaker":"こんの委員","kind":"提案","question":"調査事項までということで、その細かい内容については、ご提案があって、そこで調整していくという理解でいいですか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"いいのですけれども、多いと大変なのですが、１３人となると、一部の議員しか入れないことになるのです。１３人の決め方は、工夫があってもいいのではないかと思うのです。つまり、具体的に言うと、無所属の方も少し入れるような状況をつくるなど、今のルールありきで行かなくてもいいのではないかという思いがあるのですけれども、いかがでしょうか。","respondent":"大澤区議会事務局長","answer":"これまで、人数割は、会派の比例配分で決めておりました。","voiceIndex":55,"id":"exchange-021"}]},{"id":"topic-02","title":"その他の(1)議長からの報告","agenda":"その他の(1)議長からの報告","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"ここなのかと思ったのですけれども、前回、区議会だよりの件で、議会運営委員会に相談と議論があったと思うのです。最終的に議長一任のような感じになったことがどうなったのか。","respondent":"渡辺議長","answer":"その後、そこで協議の上、結論としましては、今回、具体名、該当する学校名や明確な根拠の曖昧なところは削除といいますか、掲載しないという結論にいたしました。そして、当該議員にも、私から直接お伝えして、ご理解をいただきました。ご協力ありがとうあります。","voiceIndex":65,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"ありがとうございました。須貝委員とも内容を確認しながら作成しました。今からお配りさせていただきたいと思います。よろしくお願いします。前回、議会運営委員会でいただいた各会派の皆様の意見を反映した案文となっていると思いますので、ぜひ賛成していただくとともに、提出者にもなっていただけるよう、改めてお願いしたいと思います。その点についても、ぜひご検討をお願いしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-023"},{"speaker":"塚本委員","kind":"質問・要望","question":"ざっと読ませていただいて、１点だけご検討いただければなと思うのが、２段落目の２行目から「品川区議会としても看過できず」となって、「議会運営委員会において、各会派から事実確認のため中塚亮議員に説明を求める意見が出され、令和６年２月８日、会派・無所属議員の代表による聴取及び質疑を行った」となっているのです。ご検討いただければと思ってあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-024"},{"speaker":"安藤委員","kind":"提案","question":"趣旨としては、より議会運営委員会での対応を丁寧に強調してほしいということだと思います。今、塚本委員に提案していただいた案文を参考にして、さらに反映できたらと思っています。そのような考えはあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":79,"id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"追記についてはいいのですけれども、細かい文言などが大事なところであると思うのですけれども、趣旨については重々理解していますので、変えたいと思っているのですけれども、今すぐ文言と言われても困るなということがあるのです。例えば、早くやったほうがいいと思うので、議会運営委員会において、日本共産党品川区議団から聴取し。少し待ってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-026"},{"speaker":"須貝委員","kind":"提案","question":"私も提案者になりますが、安藤委員にはお願いなのですが、各会派の皆様にこの後、それぞれご意見を聞いて、もし提案者になっていただける方がいましたら、一緒に載せていただける方がいましたら、お願いしてみたらどうでしょうか。早急に動いていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6655#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":17971,"voices":90}},{"id":"r06-20240416-6","meetingId":"r06-cm04","date":"2024年4月16日","dateIso":"2024-04-16","committee":"区民委員会","time":"午後 １時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和５年度、町会・自治会課題解決支援事業報告書","agenda":"令和５年度、町会・自治会課題解決支援事業報告書","exchanges":[{"speaker":"せらく委員","kind":"質問","question":"令和６年度の実施予定についてお聞きしたいのですけれども、（１）の伴走型支援プログラム、５町会というのはもう決まっているのですか。","respondent":"宮澤地域活動課長","answer":"今、この報告書の内容を各地区各町会・自治会に説明しておりまして、併せて令和６年度の支援を求めている町会・自治会を募集しているので、今は決まっていなくて、募集中という形です。","voiceIndex":20,"id":"exchange-001"},{"speaker":"せらく委員","kind":"質問","question":"ご説明しながら募集をしている形ということで、あと、５町会よりも増えた場合はどのような対応を検討されているか教えてください。","respondent":"宮澤地域活動課長","answer":"もし応募が５町会を超えた場合の対応ですけれども、この間、令和４年度からこの事業を行っておりまして、その間に支援させていただいた町会から改めてまた、応募が来た場合に関しては、新たにというところの町会・自治会を優先したいというふうに考えております。","voiceIndex":22,"id":"exchange-002"},{"speaker":"山本委員","kind":"質問・要望","question":"地域コミュニティーの活性化のために、このような、主体的な町会をサポートする伴走型支援、それから、横のつながりを形成するための交流会の開催というのは、いずれもよい取組であると私は考えております。それで、区としてこれをやってみての評価、それからやった上での課題というのがあれば、お聞かせいただきたいと思います。","respondent":"宮澤地域活動課長","answer":"これは以前、活動活性化の調査をしてきているときの調査内容から見ても、やはり抱えている課題というのは変わってきていないというところ、それをいかに進めていくかということで、こういったコンサルタントを入れて伴走型支援ということでも取り組んでいるところですけれども。","voiceIndex":25,"id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"なので、主体的でない町会・自治会の皆様にどう、こういったことを理解していただき、自らやっていこうとしていただくかというのが必要だと思いますので、ぜひそういった取組にも尽力いただきたいと思います。１点、この交流会については、来年、令和６年度の実施予定、特に記されていないのですけれども、こちらについては、どのような経緯だったのかというのを教えていただきたいと思います。","respondent":"宮澤地域活動課長","answer":"交流会の部分につきましてなのですけれども、今年度に関してはマンションとの関係づくりというところで手引を作成して、各町会・自治会に説明をするというところが一つ、ちょっと事業内容として変化を加えたところです。","voiceIndex":27,"id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ、繰り返しになりますけれども、全体への、その他の町会・自治会への広がりへのアクションを取っていただきたいということで、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"提案","question":"それとあと、もう一つ、最後３つ目はマンションとの関係で、私もマンション住民であって、マンションの理事長もやりましたけれど、本当に町会との関係というのが非常に難しいというか、今回手引を作られるということですけれども、これ何回か私も提案しているのですけれど、提案というか、難しいですが、町会加入の覚書のひな形みたいなもの、町会とマンション。","respondent":"宮澤地域活動課長","answer":"３点目の、町会とマンションとの関係づくりですけれども、覚書を交わして町会の加入が成功したという事例を、特にここ一、二年でよく聞くところですので、そういった成功事例をちょっと集めさせていただきまして。","voiceIndex":31,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"意見","question":"最後の部分ですけれど、私も町会長から頼まれてそのひな形みたいなものを作ると、あれも入れなければ、これも入れなければと、すごい堅苦しいものを作ってしまって、相手側がすごい警戒して、入会断られるみたいなこともあるので、成功した、いわゆるあまり堅苦しい契約書ではなくて、覚書というやわらかい形のもので、そういう成功事例、誘いやすいようなものを載せていただけるということでしたので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-007"},{"speaker":"横山委員","kind":"質問","question":"２点目に、５ページのところなのですけれども、行事を減らしたくないということが書いてあるのですが、この理由としてどういったものがあるのかなというところに絡めて、このアンケート結果というのをどういうふうに結果に生かしていくのかなというところと、そのアフターフォローみたいなところは、今回この１年間で終わってしまいますけれども、体制どのようになっているのかというところ。","respondent":"宮澤地域活動課長","answer":"なかなかやはり、優先順位をつけていくというのは、正直難しいかなとは思っているところですが、やはり町会の活動の中では、マンションとの関係づくりというのは、特に多く聞く声だというところで、まず、手引の作成ということを考えているところです。","voiceIndex":35,"id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"行事のところもちょっと聞き直したかったのですけれど、また、できることできないこと、あとその優先順位とそのリソースとか、やりたいことと、ちょっとこれはということと、いろいろな整理の仕方、優先順位の立て方みたいなところが、もしかしたらお困りなのではないかなというふうに思いましたので、そういったあたり、その他の、昨年度のアフターフォローを含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"だから八潮というのは、今日、偶然、八潮の担当課長、お見えになっているけれども、八潮というのはこういう自治会とかいうとちょっと特別な位置づけにされてしまうのですか。それとも、そうではないのだと、当たり前ですけど、八潮も品川区の一つの自治会ですから、その辺についてどう、これからでいいですから、考えていくのか。ぜひ八潮の担当課長にご答弁いただければ幸いです。","respondent":"宮澤地域活動課長、今井八潮まちづくり担当課長","answer":"そういった中で、今回の支援の中でもそうなのですけれども、例えばアンケートを取る目的としては、町会にどういったことを求めているかというのをよく、より把握して、特に、町会・自治会が、そこに住む皆さんにとってどういう存在で。こういったところと併せまして、今年度については、八潮のコンセプト検討の委託というものを予算としてつけさせていただいておりまして、行政としてどのように町会活動等をサポートしていくかといったところを大きな視点で。","voiceIndex":38,"id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"町会の加入促進をしてくれていないと、決して私は言っているのではないのです。一生懸命努力してくれていますよね。でも、それは数字でこれから出てきます。ですから、その辺も含めて、これから、役所もそうだし、住んでいる方たちもそうだし、その辺というのはしっかりもみ込んでやっていくことが大事だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-011"},{"speaker":"えのした委員","kind":"質問","question":"やはり２０１町会・自治会あるので地域性あるとは思いますが、やはり先ほど課長おっしゃられた、共通課題、今回も例えば、先ほども出た、高齢化ですとか、ＩＣＴ、担い手づくり、ＬＩＮＥのオープンチャットなど今回出てきましたけれども、助成金も使えますし、何ですか今後、よい取組とすると、このマンションとの関係づくりに向けた手引の作成というふうになっているのですが、まだ。","respondent":"宮澤地域活動課長","answer":"この課題解決支援事業に関しましては、今年で３年目を迎えて、今回、それぞれの報告書という形でまとめていて、それをまず、各町会・自治会にご説明することで、それぞれの取組を参考にしていただいて、また。","voiceIndex":43,"id":"exchange-012"},{"speaker":"えのした委員","kind":"質問","question":"もう１点、先ほどあくつ委員からも出ました、マンションの関係づくり、それこそ好事例ですよね。そういったパッケージ的なものを区のほうでもつくっていただいて、町会も、これを建築前に持っていってお願いしているというのはもう、重要というか、そこからでないとやはり町会との関係性が結んでいけないかと思っているのですけど、その辺をいかがお考えでしょうか。","respondent":"宮澤地域活動課長","answer":"ただ、町会からお聞きする、マンションとの関係づくりに悩むという声は、必ずしもそこ、それも含めてなのですけれども、既に建っているマンションとの関係づくりから、また、既存のマンションも分譲なのか賃貸なのか、また、一人暮らし向けなのか世帯向けなのかということで。","voiceIndex":45,"id":"exchange-013"},{"speaker":"せらく委員","kind":"質問","question":"でも、中延五丁目町会など調べてみると、アカウントが出てこず、単純に検索すると、品川の町会・自治会というホームページの、個別の中延五丁目町会の紹介というページに当たりまして、若い方たちはやはり、ＳＮＳが親しみやすくて、回覧板や掲示板なんかよりもすごくいいと思いますが、回覧板、掲示板だけでＳＮＳアカウントありますというふうになると、また、そこまでたどり着くのが難しくて。","respondent":"宮澤地域活動課長","answer":"中延五丁目町会の取組ということで、報告書の７ページにもあります。","voiceIndex":49,"id":"exchange-014"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"時間のない中恐れ入れますが、ちょっと気になったので、ぜひこういったことがないように、再発防止はしっかりやっていただきたいというのが思いなのですけども、９件あった、その誤交付されたものについてはどのようになったのか、教えていただければと思います。","respondent":"築山戸籍住民課長","answer":"連絡先が分からない方がいましたので、その方につきましては、速達で正しいものを送付させていただきまして、郵送で差し替えの対応をさせていただいたところです。","voiceIndex":56,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6663#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":16456,"voices":60}},{"id":"r06-20240416-7","meetingId":"r06-cm04","date":"2024年4月16日","dateIso":"2024-04-16","committee":"厚生委員会","time":"午後 １時００分～午後 ４時５４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年陳情第２０号、重度障害者が入居できるグループホームの運営支援を区に求める陳情","agenda":"令和６年陳情第２０号、重度障害者が入居できるグループホームの運営支援を区に求める陳情","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"もう少し現状を把握したいので、幾つかお聞かせください。先ほど、８７名の応募があったとお聞きしましたが、こちらの区内区外のそれぞれの人数がもし分かりましたら、お知らせください。配置のところで、常勤１０人ということでしたが、どういった方で、資格等がもしあれば、資格職の方など、詳細を教えていただけると助かります。","respondent":"松山障害者支援課長","answer":"３点ご質問をいただきました。１点、区内、区外の内訳です。８７人のうち、辞退の方がお一人、８６人のうち、区外が５人です。それ以外、８１人が区内の方となっております。","voiceIndex":33,"id":"exchange-001"},{"speaker":"おぎの委員","kind":"確認","question":"ほとんど品川区の区内の方ということで確認いたしました。区分の内訳も、４の方が３０人ということで、そうしますと、やはり面接をすると、４以上の方が多くなるのかなと思いますが、今、順次面接をされているということで、Ａ区分というのは、ほとんどこれ、区分の４から６の方が多いのかなと思いますが、その辺はいかがでしょうか。","respondent":"松山障害者支援課長","answer":"そのため、看護師を配置ということは、現段階ではございません。例えば、今後、医療的ケアが必要になった場合は、外部から、例えば訪問看護を入れるなどの可能性もありますし、今、区立の中でもそのように対応しているグループホームもあります。","voiceIndex":35,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この陳情のところの港区は空床型の短期入所は医療的ケアのある方の受入れを求めていますということで書かれているのですけれども、ここの短期入所２名があるわけですけれども、これは医療的ケアの方を受け入れるということはあるのか、その点も伺います。","respondent":"松山障害者支援課長","answer":"１点目ですけれども、支援区分が高い方、いわゆる区分６の方から入りやすいかというご質問ですけれども、区としては、推薦する中で、Ａ区分の中でも区分が６の方、５の方という形で、支援区分の高い人から当たってくださいと。","voiceIndex":39,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それ以外のところで、品川区立のグループホームは幾つもあると思うのですけれども、その中で実際に支援区分５とか６の方は、実際は入られていないのか、その点も教えていただきたいと思います。","respondent":"松山障害者支援課長","answer":"ショート、短期入所での医療的ケアの方の受入れということになりますが、医療的ケアの状態にもよるというか、今回も、ご本人やご家族と面接をしていただいて、実際に書類だけでは分からないような、実際にご本人の望む生活ですとか、あるいは。","voiceIndex":41,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それと、約４,２００万円を介護報酬で見込むということで、事業者の見込みということなのですけれども、港区の介護報酬からすると、この介護報酬に３.６倍しても３,５００万円ぐらいにしかならないのですけれども、それよりもかなり介護報酬は事業者の見込みが多いという感じなのですけれども、そこら辺のところは、なぜ港区などよりも介護報酬が多いという見込みになるのか。","respondent":"松山障害者支援課長","answer":"出石つばさの家は初年度ということですので、指定管理者からの運営収支計画を基に出していただいたものですので、決して指定管理料が少ないからということではございませんし、区としては、指定管理者の運営収支を基に、この運営収支につきましても。","voiceIndex":43,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"多分そんなに単純に３.６倍ということではないのかなと思いながらも、計算してみたら、少し少ないなというふうな思いがしたので、でも、それは多分、事業者とのやり取りで、これでやりくりできますよという、そういうことでの指定管理料として決まったというふうなことで捉えていいですか。そういうところで、１０点の人もいるのか、その点もお聞かせください。","respondent":"松山障害者支援課長","answer":"最大で１日６人です。それから、生活支援員、３月までは、この人数規模で言いますと、４対１以上というものがありましたけれども、今年度直近で介護報酬基準改定がありまして、６対１ということでグループホームの基準では出されております。その基準をクリアしております。","voiceIndex":45,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"もう１つ伺いたいのが、このグループホーム、８７人が申し込まれたということなのですけれども、今まで、ここの中で、どれぐらい待機者がいらっしゃるかということで伺ったときには、相談のところに登録というか、希望されている方が５０人くらいということで答弁だったと思うのですけれども、それよりも８７人はすごく多いなというふうに思ったのですけれども、地域移行とか、それからあと。","respondent":"松山障害者支援課長","answer":"したがいまして、今回、在宅の方と、その方を合わせると、大体見込みとしては５０人、その方々がプラスされた人数が申し込みいただいたということで把握しています。","voiceIndex":47,"id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２２人の方が、やはり本来であれば、区内にあれば入りたかったということで、品川区に戻ってきたいという方なのだなと、改めてこの人数を考えると、やはりこれからももっとグループホームを、こういう希望に沿った形で、ぜひともつくっていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-008"},{"speaker":"ひがし委員","kind":"確認","question":"この入居の順位の区分、Ａ、Ｂ、Ｃというふうにつくられていると思っていて、その内訳については先ほど聞きましたが、このＡの方々、９点で２８人、その中の内訳で、区分４の方が１７人で、区分５が６人で、区分６が５人ということなのですけれども、この点数、９点がマックス、今のところの段階ではというところでいくと、障害支援区分の点数は４から６が合わせて全部２点になっていまして。","respondent":"松山障害者支援課長","answer":"調整指数の点数の決め方です。今回、中重度ということで、４から６の方をまず入れていただきたいというのが区としています。Ａの方にも、Ｂの方にも、４から６の方は非常に多いです。","voiceIndex":51,"id":"exchange-009"},{"speaker":"ひがし委員","kind":"確認","question":"ただ、点数は一緒だけれども、面談とか体験をするというときは、区としては、やはり区分が高い６から先にやっていただくというふうにお願いをしているということの認識で合っていますでしょうかという点と、あとは、この入居者の選定方法、先ほど教えていただきました入居候補者選定会議というところ、区も入っていたと思うのですけれども、最終的にどのような流れで決まっていくのか。","respondent":"松山障害者支援課長","answer":"区分の高い方から入れていきたいという区の認識についてです。実際このように調整指数を決めさせていただきまして、これはご案内ですので、皆さんにお申し込みいただく際には、もう既に公表されているものです。","voiceIndex":53,"id":"exchange-010"},{"speaker":"ひがし委員","kind":"確認","question":"今、推薦の決定は区が最終的にしたということで確認ができたのですけれども、この後のお話を聞いていて、入居者を、今、面談をしていて、体験とかをしていくという流れになると思うのですけれども、その最終的なものが言えるところ、決定権がどこにあるのかという質問だったと思うのでその点について、お答えいただければと思います。","respondent":"松山障害者支援課長","answer":"最終的には、指定管理者とご本人との契約に基づいて、双方合意の上で契約をするということになります。区としては、グループホーム、共同生活援助サービスを利用していただくような決定はできるのですが、どこにというのは、ご本人と運営事業者との契約ということになります。","voiceIndex":55,"id":"exchange-011"},{"speaker":"ひがし委員","kind":"確認","question":"恐らくこの陳情を見ていったときに、Ａの点数が２８人というふうにいらっしゃって、その中の区分内訳のところを考えていくと、もしかすると、この面談だったりとか体験の後に入った方々が、重度の方がいないのではないかとか、取れないのではないかというところを危惧されていての陳情なのではないかというふうに思っていて、区として、中重度の方を入れていくというところで考えると。","respondent":"松山障害者支援課長","answer":"区としては、意向をその都度伝えておりますし、この選定会議の中でも、ほかにも外部の方も入っておりますので、その方々の前でも伝えておりますので、今後も情報連携をきちんととりながら。","voiceIndex":57,"id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その点について、この指定管理料が少ないためにというところが陳情の趣旨にも書かれていますが、港区と比べて、そもそも品川区は指定管理の収入の内訳が違うというふうに先ほど説明でいただいたと思うのですけれども、ここについても改めてもう１回説明をいただいてもよろしいでしょうか。","respondent":"松山障害者支援課長","answer":"障害福祉サービスの報酬については、例えば、支援区分が高い、あるいは人員体制を整えるとすると加算が多く出る、いわゆる報酬として指定管理者の報酬に入るという形になりますので、品川区の場合は、障害福祉サービスの報酬を指定管理者の収入とすることで。","voiceIndex":59,"id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問・要望","question":"長岡福祉協会の方々とお話をしていても、すごく積極的に中重度の方が入れるように体制を整えていくというようなお話を聞かせていただきましたので、区としても、この指定管理料のところについて、今回は初年度なので、相手方が提示した金額と説明をいただきましたけれども、もし足りないだったりとか、もっとサービスを何か入れてほしいというようなお声かけがあったときには、しっかりと区としても。","respondent":"松山障害者支援課長","answer":"委員がおっしゃられるように、初年度のため、指定管理者からの運営収支計画に基づきまして算出いたしましたが、今後、実績等を見させていただいて、指定管理者と随時協議をしながら、今後、指定管理料については、また検討していくということで。","voiceIndex":61,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"すみません、６番の入所順位区分のところなのですけれども、区分Ａが２８人ということで、区分Ａは９点ということなので、支援区分としては、４から６ということですよね。それとも、区分Ａが優先的に入って、それで辞退して、Ａの方で足りなかったらＢの方に移るという、そういうことですよね。そうすると、４から６が中心というか、基本的に４以上になるのではないかということで考えていいのでしょうか。","respondent":"松山障害者支援課長","answer":"Ａ区分とＢ区分についてです。Ａ区分については、おっしゃられるように９点、Ｂ区分については８点なのです。その１点の違いはどこかといいますと、ご家族の状況というところが大きいです。","voiceIndex":64,"id":"exchange-015"},{"speaker":"筒井委員","kind":"確認","question":"この出石つばさの家は、中重度の方、重度の方も含めて受け入れるという体制だということの確認と、あと、そもそもグループホームというのは、あくまでも共同生活の場だと思うのですけれども、あまりにも重度の障害者の方は、医療施設ということになるのかという、このチラシにその旨が書かれておりますけれども、その点の確認をしたいと思います。","respondent":"松山障害者支援課長","answer":"ただ、共同生活が可能な方といいましても、支援した上で可能になる方も当然ながらいらっしゃると思いますので、ここは指定管理者がどのように支援をしていくかというところがキーになるかと思ってあります。","voiceIndex":67,"id":"exchange-016"},{"speaker":"筒井委員","kind":"確認","question":"分かりました。重度障害者も利用はできるということが確認とれました。この陳情の趣旨で、指定管理料が少ないために重度の障害者が利用するのに不十分な人員体制という旨と、あと、２ページで、指定管理料が少ないことが分かり、人員体制を減らさざるを得なかったことが推測される。その確認をしたいと思います。","respondent":"松山障害者支援課長","answer":"指定管理料についてですが、品川区の場合は、そのように利用料金制ということで、報酬については指定管理者の収入になるということは、きちんと説明をしていますし、その上での運営収支計画を提出いただいている。それで、協議の上で決めているものです。","voiceIndex":69,"id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"今回の約４,２００万円は、きちんと指定管理者の方に入るということなのですけれども、そうした前提の下、今回、陳情者が言われている重度の障害者が利用するには不十分な人員体制と書いてありますけれども、人員体制については、これ、区としては十分だと考えておられるのでしょうか。","respondent":"松山障害者支援課長","answer":"ただし、今後、入居者の状況によって、やはり支援が必要だということであれば、指定管理者がご用意をするという報告を受けておりますので、区としても、そのように依頼をしています。","voiceIndex":71,"id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"確認","question":"これ、先ほどの筒井委員の質問の続きなのですが、利用料金制でしたか、それは募集の段階で、事業所のほうには、うちはこういうふうなやり方ですと周知はしているということは確認ができたのですけれども、つまり、区としては、経営努力によって報酬が上がる可能性があるよというようなインセンティブをつけているというところで、それをやることによって、やはり区としては。","respondent":"松山障害者支援課長","answer":"区としての利用料金制ですけれども、やはり全く区の歳入にしてしまうと、指定管理者にとってはあまりメリットがない状況になりますので、やはり指定管理者の経営努力や創意工夫によって歳入が得られる、収入が得られるということは。","voiceIndex":74,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"確認","question":"特に、この制度に対して、説明会の段階で何か事業所から、この点について、何か質問とか、こういうふうにしたほうがいいのではないかとか、そういう問合せは特に説明会の段階ではなかったのでしょうか。確認です。","respondent":"松山障害者支援課長","answer":"委員よりお問い合わせのあったご質問のようなものは、区には特にございませんでした。","voiceIndex":76,"id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これは要望になるかもしれませんけれども、重度障害者のグループホームということで、非常に待ち望まれていたものということで、安定して経営をして、受入れをしっかりしていただきたいというところがあるので、ぜひ今後というか、まだ走り出したところなので、収支の面がどうなるかということは承知しているのですけれども、しっかりと伴走していただいて、赤字で続けられないとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-021"},{"speaker":"こんの委員","kind":"質問・要望","question":"この後、今年度、今は選定をされているので、どういう区分の方が何人入ってこられてという、そこの報酬につながっていくところだと思うのですけれども、今後、事業者が、やはり区分５、６の方々を受け入れたときに、人員を増やす、あるいは有資格者を増やすというような体制を考えていったときに、柔軟に、ここ、指定管理料を、協議の上、決めていっていただきたい、こういうふうに思うのですけれども。","respondent":"松山障害者支援課長","answer":"今後、やはり期待されているグループホームですし、中重度の方を、区としては、指定管理者と協力しながら、実際にどういうことがお困りなのか、きちんと聞きながら、あるいは、どういう支援が必要なのか。","voiceIndex":80,"id":"exchange-022"},{"speaker":"こんの委員","kind":"質問・要望","question":"このグループホームに限らず、利用者へのサポートをされるスタッフ、そうした方々の、こういう報酬については、今、報酬アップというような話も社会的にもありますので、事業者がこれからスタッフのお給料を上げていきたいというようなところも、ぜひしっかりご相談に乗っていただいて、協議をしていただいて、そういう体制がとれて、そして、中重度の方が入所できる、こうしたグループホームとして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-023"},{"speaker":"こしば副委員長","kind":"質問","question":"理由としましては、これまで様々な委員の方々からの質問に対する課長の説明、また答弁をお聞きしまして、今回の陳情の趣旨の例えば１つであります指定管理料についても、必ずしもこれは不均衡なものではなく、指定管理者となる事業者の経営、収支状況を鑑みるなど、そういった複合的な作用があった上での指定管理料の決定であることが分かりましたし、また、必ずしも、この陳情の最後のところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-024"},{"speaker":"こんの委員","kind":"確認","question":"本日結論を出すでお願いします。結論は、先ほどの質疑を１点だけさせていただきましたが、指定管理料の考え方も柔軟にといったところも確認がとれましたし、人員配置、それから利用者の選定の考え方等々も確認をさせていただきましたので、先ほどの質疑でも申し上げましたが、指定管理者が中重度の方々を受け入れやすい体制がとれるといったところは、やはり区の支援が必要だろうと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-025"},{"speaker":"ひがし委員","kind":"質問・要望","question":"本日結論を出すでお願いいたします。ただ、確認しましたように、重度の障害者の方も利用できるような運営ができるように、区としても十分に引き続き支援をしていただけるように、こちらについては改めて強く要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択でお願いしたいと思います。今、ご説明を伺って、重度の方が入所できるというふうなところは分かりました。しかし、ここに書かれているように、これまでも重度の方々がなかなか入れないで苦労されてきた、そういうことも分かりますし、この区立の出石の運営事業者は、港区でも指定管理者を受けている事業者なのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日、結論を出すで、不採択でお願いします。ただ、一方で、今回、初年度ということで、しっかりこの運営体制が維持できるように、品川区も伴走をして、しっかりとこの事業が維持できるようにしっかりと見ていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-028"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すでお願いします。ただ、一方、やはり重度の方がずっと入れなくて困っているという部分はもちろんこちらの陳情の趣旨で非常に伝わってきますので、事業者に人員配置や指定管理料をはじめ、やりやすいように協議をして、しっかり区としてもバックアップしていただきたいと思いまして、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出すでお願いします。他方で、おぎの委員おっしゃるようなところもあり、この陳情の提出者の方も、こういった区民の方の声、やはり中重度の方がしっかりと安心して地域で暮らせるというところを望んでいるような声もしっかりと受け止めるべきだなということもありまして、趣旨採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-030"}]},{"id":"topic-02","title":"「第４期品川区地域福祉計画（素案）」に係るパブリックコメントの実施結果","agenda":"「第４期品川区地域福祉計画（素案）」に係るパブリックコメントの実施結果","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"地域福祉計画は、ＰＤＣＡサイクルで、毎年１年間の取組の状況を全部まとめて、それはホームページにも、令和４年分のものまで見つかったのですけれども、令和５年もされているのでしょうかということと、このＰＤＣＡサイクルの意味なのですけれども、これ、すごく幅広いではないですか。","respondent":"東野福祉計画課長","answer":"メンバー的には、庁内の関係部署、子どもから高齢者、生活福祉、障害者、そういったところが網羅されているものです。こちらは福祉は広い分野ですので、そういった所管の取組について、年間の取組を確認していくという形をとってあります。","voiceIndex":97,"id":"exchange-031"},{"speaker":"鈴木委員","kind":"質問・要望","question":"年に１回というのは、ここの中にもどこかにあったか、公開はされているのですか。傍聴はできるのですかみたいなこともどこかにあったような気がしたのですけれども、そういうことはできないのか、それとも、庁内だけのまとめみたいな形でされて、それがホームページで公開されるということになるのか。多分、令和５年度ももう既にされていると思うのですけれども、その公表、令和５年度もされているのですね。","respondent":"東野福祉計画課長","answer":"それが推進委員会です。令和５年度につきましては、令和５年度の１サイクルが３月までということになりますので、これから１サイクルのところの活動状況についての確認を行ってまいります。","voiceIndex":99,"id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問","question":"令和４年度までは、その年度内にやっていたと思うのですけれども、令和５年度分はまだされていないというなのでしょうか。なおかつ、この地域福祉計画推進委員会というところで、このＰＤＣＡサイクルでやるということによって、どういうものをどう前進させていこうということになるのか、そこら辺のところがよく見えないので、もう少し教えていただけたらと思います。","respondent":"東野福祉計画課長","answer":"その検討をどう生かしたかについても、併せて推進委員会の中で確認を行っていく、そういうやり方をしております。","voiceIndex":101,"id":"exchange-033"},{"speaker":"鈴木委員","kind":"意見","question":"ここの出されたパブリックコメントの中で、重層的支援体制整備事業もいろいろと出てきて、２５年に本格実施を目指すということで、ここの中でも何回か報告されたことがあるのですけれども、福祉計画課が中心になって重層的支援体制整備事業を行っていくということで前もご説明いただいたのですけれども、それは、ここのところでも、２１年から準備を開始して、そして２２年から本格実施に向けて始めて。","respondent":"東野福祉計画課長","answer":"そういったもろもろのこと、それから、まだできていない部分がございまして、複合課題を抱えている人にどうアウトリーチしていくかというところを、今年度は事例を挙げながら内部での検討を進めて、重層的支援体制整備事業を完成させていこうです。","voiceIndex":103,"id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問・要望","question":"Ｎｏ.３１だ、Ｎｏ.３１で、「アウトリーチについて必要性を整理されているが、素案の中で具体的なイメージがつかめません」ということに対して、もう既に各分野で自宅を訪問する等のアウトリーチを実施していますということで書かれていたので、どのようなアウトリーチがもう既にどれぐらいまでできているのかということを伺えたらなと思います。","respondent":"東野福祉計画課長","answer":"区では、昨年度からいち早く取組を始めておりまして、地域協議会の設立に向けまして、令和６年度の設立を予定しております。まだメンバーなどは固まっておりません。","voiceIndex":105,"id":"exchange-035"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"細かいところで、ここで要望することではないかもしれないのですけれども、概要版の１６ページ、本編だと４９ページですけれども、児童相談所の写真が載っていると思うのですけれども、写真が夕方の暗い時間の写真になっていて、私は、これがいずれ差し替わると思っていたのですけれども、区の書類とかで、ずっとこれが使われていて、ネットで「品川児童相談所」とかと調べても、これしか出てこないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-036"},{"speaker":"こんの委員","kind":"質問・要望","question":"その不動産屋さんとのつなぎ、あるいは情報提供、すごく不動産屋さんとも連携をとってくださるので、非常に手厚くやってくださるのですが、いざ内覧して、そこを借りようとしたときの手続に関わるいろいろな、お一人ではなかなか手続でき切れないというようなところもあるので、こうした体制を、こちらは２点に絞って具体的な取組というふうに、いわゆるサービスの提供と、サポートしますよということと。","respondent":"東野福祉計画課長","answer":"先ほど、別の委員からもお話がありました推進委員会でこういった具体的な取組について、どういう課題があって、それに対してどういう対応をしていくかという部分をＰＤＣＡサイクルの中で取り組んでいるところですので、そこで改めて、今、委員がおっしゃったようなことについて。","voiceIndex":114,"id":"exchange-037"},{"speaker":"こんの委員","kind":"提案","question":"そうなると、本当にこのサポートというところは、１つ大きく取り上げてもいいぐらいの計画の１つになるかと思いますので、今おっしゃってくださった検討委員会の中でも進めていただくのですけれども、住宅課と連携しながら、居住支援法人といったところで、住まいのあらゆるサポートという体制をとっていただくように、福祉計画課からも、そうした提案をしていただきながら進めていただきたいと思いますが。","respondent":"東野福祉計画課長","answer":"委員のご提案のところにつきましては、区全体の中、住宅課とも連携をとりながら、よりお困りの高齢者、また、ほかにも困っている方にとって、どういう施策が展開できるかを考えてまいりたいと思います。","voiceIndex":116,"id":"exchange-038"},{"speaker":"おぎの委員","kind":"質問","question":"私もこちらの資料を見たときに、こんの委員と同じく、Ｎｏ.２９のコメントが一番気になっておりまして、今、住まいの確保という面では、ご意見をお聞きできたので、続いて、下の後半部分の「賃貸住宅で孤立死が発生した場合に行政が埋葬、清掃してほしい」という部分で、今後、高齢化社会でこういったケースはすごく増えてくると思うのですが、現状で、孤立死されて、お掃除とか、埋葬とか。","respondent":"東野福祉計画課長","answer":"区として、どのような体制がとれるか、孤独・孤立対策についても取組を始めているところですので、そことまた併せ持って考えていければと思います。","voiceIndex":119,"id":"exchange-039"},{"speaker":"おぎの委員","kind":"質問・要望","question":"先ほどもお話があったように、孤独・孤立対策の協議会はこれから進めていくということですので、こういった事案の把握も含めて、ひとり暮らしの高齢者の方が安心して過ごせる環境をつくっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-040"},{"speaker":"ひがし委員","kind":"質問・要望","question":"私からは、パブリックコメントＮｏ.２２の、ページで言うと、品川区地域福祉計画の４３ページの６）災害時助け合いのしくみの充実の点から質問させていただきたいと思います。","respondent":"松山障害者支援課長","answer":"避難行動要支援者個別計画の作成についてです。区としては、令和３年度から実施いたしまして、令和３年度、令和４年度と合わせて、令和５年度の集計がまだできていないのですけれども、今、分かっている数字の中では、５２７人の作成が済んでいます。","voiceIndex":123,"id":"exchange-041"},{"speaker":"ひがし委員","kind":"質問・要望","question":"実はこれ、先日の予算委員会のほうでも質疑させていただいたのですけれども、やはり不安というところをこうやってパブリックコメントにも載ってきているということですし、現状として、やはりいろいろな地域で地震が起きているというところでいくと、やはり早急に進めていくべきだというふうに思いますので、この点について、改めて丁寧に進めていって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-042"},{"speaker":"こんの委員","kind":"確認","question":"すみません、先ほど、おぎの委員からも話がありましたけれども、決して私は、先ほどの質問の中で、後段の部分を除いての話ではなかったのですけれども、確認です。なぜ使われていないかと、私たち会派でもいろいろと研究調査しているのですが、金額です。内容と金額。その辺を確認させてください。","respondent":"東野福祉計画課長","answer":"社会福祉協議会につきましても、あんしん居住サポートのところに、終活相談の担当を置いて、これから広く進めていくということで伺っております。区として何か連携をしてできることは整えていければと思っています。","voiceIndex":127,"id":"exchange-043"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-044"}]},{"id":"topic-03","title":"「品川区障害者計画及び第７期品川区障害福祉計画・第３期障害児福祉計画（素案）」に係るパブリックコメントの実施結果","agenda":"「品川区障害者計画及び第７期品川区障害福祉計画・第３期障害児福祉計画（素案）」に係るパブリックコメントの実施結果","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"それともう１つ、団体に対してのヒアリングのことで、この１１ページのＮｏ.５３のところに、コンサルがヒアリングをしているということで、コンサルに何を聞いても回答できないので、ただの記録係になっているので、やり方を変えてくださいということで、職員に同席してほしいということで書かれているのですけれども、その同席については、今後検討いたしますということで書かれているのですけれども。","respondent":"佐藤障害者施策推進課長","answer":"ただ、今申し上げたようなところで、施策全体へのお話もいただいているというようなところも踏まえまして、パブリックコメントの答えと同様になりますが、今後のヒアリングへの職員の同席については検討させていただければという今回のお答えとなっているところです。","voiceIndex":135,"id":"exchange-045"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これは要望します。それから、ヒアリングの中身は、まとめて策定委員会のほうには出されているということであれば、厚生委員会にも出していただけると、私たちも直接、その資料を、団体の方々がどういうことで要望されているかということが分かりますので、ぜひ厚生委員会にも資料として出していただきたいと思いますが、その点についても伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"団体ヒアリングの結果の公表につきましては、委員会への報告も含めまして検討させていただきたいと思います。","voiceIndex":137,"id":"exchange-046"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは、そうされたということでいいのですけれども、その意見を聞いて、団体と、それからこのパブリックコメントの中で、中身として修正したものがあるのかと、それがあったらお聞かせいただきたいという、そういう文言の修正の程度しかなくて、中身として意見を聞いた中でこういうふうに変えましたよというものはないのか、それとも、大きなところであるのであれば。","respondent":"佐藤障害者施策推進課長","answer":"今の内容に関するようなところという意味では、事業、施策等についてのご意見、例えば、定員の拡大の記載について書かせていただいている部分について充実を図ってほしいというようなご意見をいただいて、記載内容を修正させていただいたりですとか。","voiceIndex":139,"id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問","question":"分かりました。１０数か所あるのです、そういうふうに。そこのところは、必要なサービス量が見込み量として反映されていないために、必要なサービスの供給確保の計画ができないのではないかと思うのですけれども、そこのところは、区としては、必要なサービスの供給量をしっかりと確保するために、見込み量との整合性をどう考えるのか、その点を伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"ご指摘の見込み量のところですが、パブリックコメントの区としての考え方でもお答えさせていただいている部分がありますが、計画としましては、見込み量の算出の方法ということで、直近３期と直近５期の利用時間数等を対比したりですとかというようなところで。","voiceIndex":141,"id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところで、どれぐらいサービスの見込み量よりもオーバーしたかとかということは分かると思いますので、その時点で必要なサービスが供給できないということがないような、そういう計画に変更するというところも含めて、サービスが足りなくて使えないということは今でもあるわけですから、しっかりとサービス量を確保するようにということで。","respondent":"佐藤障害者施策推進課長","answer":"今、直近でいただきました３５ページのコメントに対してのお答えについてですけれども、こちらについては、解釈というか、書き方で誤解を生んでしまっていたら申し訳ないのですけれども、基本的には、今までお伝えしておりますとおり。３０年は無償貸付ということで間違いない、更新等を含めてご相談というところで間違いございません。","voiceIndex":143,"id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問","question":"ここの回答書だと、「３０年間の無償貸付としています。でも、そういうふうに書いてあるわけではないですか、これは。ここの回答は。違うのか。","respondent":"佐藤障害者施策推進課長","answer":"ご意見に対して直接答えたような形なので、貸付期間経過後の部分等については、詳しくお書きしていない部分はあります。貸付期間経過後に関しては、今申し上げたとおりです。","voiceIndex":148,"id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問・要望","question":"はい、分かりました。多分これはそういうことが心配で質問されたのではないかと思うので、その後も続けられますよということであれば、そういう丁寧な書き方にぜひしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-051"},{"speaker":"おぎの委員","kind":"質問・要望","question":"「具体的にどのようなものを目指しているのでしょうか」、「いきなりインクルーシブとするのではなく、まずは区内小学校全校へ特別支援学級を設置することで就学時に障害児が就学先を選択できる環境整備を求めます」ということで、森澤区長は障害がある子もない子も誰一人取り残さないインクルーシブな教育ということをおっしゃっていて、区の姿勢も非常によく分かるのですけれども、一方で。","respondent":"松山障害者支援課長","answer":"今お尋ねの特別支援学校のインクルーシブに関してのご質問ですが、このことにつきましては、教育委員会の所管となっておりますので、この場では回答は差し控えします。","voiceIndex":153,"id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問","question":"分かりました。そうですね。この後、学校現場との調整とかも方向性をお聞きしようかと思っていたのですが、全般的に教育の担当ということで、また改めてそちらのほうに聞いてみたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":155,"id":"exchange-053"},{"speaker":"こんの委員","kind":"確認","question":"区の課題の捉え方をお聞きしたいのですけれども、相談支援事業所での、いわゆる増員をしていきますというお答えをしているわけですけれども、やはり事業所が抱えている課題を、区としてはどういうふうに捉えていらっしゃるかというところを確認したいのですけれども、要は、個別の計画相談、これについては、きちんと単価が出ているので、報酬として上がるのですが、計画までいく前の段階の相談が結構あって。","respondent":"松山障害者支援課長","answer":"そうはいいましても、基本相談なくしては計画相談に、サービスにつなぐことができないという課題がありまして、事業所とは、この間、話しているのですが、この間、ご質問いただいたのは、コロナ禍の影響も実は非常に多くございまして。","voiceIndex":157,"id":"exchange-054"},{"speaker":"こんの委員","kind":"質問・要望","question":"確かに国では、報酬が発生せずボランティアというような形になってしまっているので、その辺は課題として捉えてくださっていますし、いろいろ協議というか、ニーズを把握してくださるというお答えをいただきますので、ぜひその辺、事業所さんを増やす、増員をしていくというところの課題の１つはここかなというふうにも捉えておりますので、ぜひその辺のところも、今後。","respondent":"佐藤障害者施策推進課長","answer":"申し訳ございません。そうですね、ほかに質問が２つ並んでしまっております。大変申し訳ございません。確認します。失礼いたしました。","voiceIndex":159,"id":"exchange-055"},{"speaker":"鈴木委員","kind":"質問・要望","question":"説明会についても、このパブリックコメントに対しての回答みたいな形で説明会をしていただいてもいいのかなと思ったのですけれども、説明会をぜひ、全ての計画が私はやっていただきたいと思うのですけれども、そういうふうに方針に変えてほしいというふうに思っているのですが、その点も伺いたいと思います。","respondent":"松山障害者支援課長、佐藤障害者施策推進課長","answer":"こちらのグループホーム運営費助成につきましては、今年度につきましても、新たなグループホームが増えましたので、きちんと全部グループホームに改めて周知をしまして、またご意見等を協議していく予定です。全体、こういった計画に対するパブリックコメント等の実施方法については、各所管でも行っているところもありますし、他区で行っている状況もありますが、現時点では説明会の実施は考えていないところです。","voiceIndex":162,"id":"exchange-056"},{"speaker":"鈴木委員","kind":"質問・要望","question":"説明会については、品川区はやらないという、ほとんどの計画は説明会をしない方針で、大本がそういうふうな方針なのですか。ずっと求めても、されないまま来ているので、このところでぜひ、様々な計画は区民に知らせていただいて、区民の意見も、その場でも直接聞くような説明会はやる方向で、ぜひ方針の転換をしていただきたいということで、要望をさせていただきたいと思います。よろしくお願いします。","respondent":"松山障害者支援課長","answer":"ただ、やはり令和６年度、ちょうど報酬改定もございましたので、多分、グループホームの経営自体も、どのようにされるかというところもありますので、今後、グループホームの事業者に対しまして、改めて周知を行いまして。","voiceIndex":166,"id":"exchange-057"},{"speaker":"ひがし委員","kind":"確認","question":"パブリックコメントの結果の提出人数について、改めて確認したいのですけれども、提出人数（団体数）というふうに書かれていたので、団体の方々の意見もこの中に全て反映されているのだろうなというふうに私は認識していたのですけれども、先ほどの鈴木委員との答弁を聞いていると、団体には別途ヒアリングをしていて、その結果はここには入ってきていないという認識でいいのかということと、あと。","respondent":"佐藤障害者施策推進課長","answer":"今回、こちらに書かせていただいているのは、パブリックコメントとして、それを団体のお名前でいただいたというような形になりますので、先ほど申し上げた団体のヒアリングの内容をこちらに反映しているということではございません。","voiceIndex":170,"id":"exchange-058"},{"speaker":"ひがし委員","kind":"質問・要望","question":"区民説明会というところを毎回私も言わせていただいているのですけれども、やはりこの計画を見るだけでは分からなかったりとか、分からないからこそパブリックコメントで意見が寄せられているということもあるのかなというふうに思うので、そこの説明のところは、ぜひ私もしていただきたいというふうに思いますので、この点については要望とします。","respondent":"佐藤障害者施策推進課長","answer":"今回、報告に当たりまして、その前の計画素案とパブリックコメントの実施結果についての報告ですので、今回、６期と２期のときについても同様な形でやらせていただいてはおりますが、計画策定結果につきましては、当然、先ほど申し上げたように、策定委員会等につきましては。","voiceIndex":172,"id":"exchange-059"},{"speaker":"ひがし委員","kind":"質問","question":"ぜひヒアリングのところについても丁寧に開示していただければいいなというふうに思うのと、あとは、６４ページの、番号で言うとＮｏ.２７７のところで、ヒアリングは、「質問しても、何も答えられず、伝えておきます」となって、なかなか休みを取れないので、文面でパブリックコメントに質問することにしましたみたいな趣旨のところが書いてあったりするので、そこについても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"私からは、概要版の７ページで、計画における区の成果目標というところで、国の基本指針に基づき定めましたということですけれども、当然、４年かけて目標を達成していくということなのでしょうけれども、これ、まず、現実的に達成可能な目標を立てられているのかどうかということを、全体的なこととしてお聞きするのと、具体的には、目標１の地域生活移行者数が、現状３人から。","respondent":"佐藤障害者施策推進課長","answer":"成果目標等についてのお尋ねですが、こちらは今、委員におっしゃっていただいたとおり、もともと国の基本方針というところがございまして、それに対してそれぞれ成果目標等を定めるというようなことになっておりますので、各項目を定めさせていただいているところではあります。","voiceIndex":176,"id":"exchange-061"},{"speaker":"筒井委員","kind":"質問","question":"はい、分かりました。一番気になるのは、目標１の地域生活移行者数、現状の３人から、もう１９人以上となったというふうに、かなり大幅に増えているのですけれども、そのまま大丈夫なのかということでお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"その１９人が、実際は目標を達成するために、地域の課題や課題解決、地域自立支援協議会というところがございまして、そちらの相談支援部会で、区内外の施設にアンケート調査を実施しまして、この中で１９人の方が施設からの地域移行をご希望されていると。","voiceIndex":178,"id":"exchange-062"}]},{"id":"topic-04","title":"「第九期品川区介護保険事業計画概要（案）」に係るパブリックコメントの実施結果","agenda":"「第九期品川区介護保険事業計画概要（案）」に係るパブリックコメントの実施結果","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"このパブリックコメントのＮｏ.１５のところですけれども、先ほどご説明があったように、段階が前より若干増えて１７段階になって、上限２,５００万円までということで、２.８倍から３.３倍までということで変わったのですけれども、これは、もう既に前の厚生委員会のときも、私も申し上げたと思うのですけれども、もう既に八期の段階で３,０００万円以上もうけている、３,０００万円、３,５００万円。","respondent":"菅野高齢者福祉課長","answer":"保険料についての他区との状況についてのご質問にお答えします。まだ正式な集計表みたいなものが東京都からも示されておりませんので、まずは、６,５００円の保険料基準額については、他区も東京都が公表しております。","voiceIndex":185,"id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう形で、介護報酬にすると、どうしても介護保険料に関わりますので、そうではない形で処遇改善をして、介護のこれだけ深刻な状況は、さんざん前にも、この委員会の中でも話しましたので繰り返しませんけれども、そういうことを改善させるためにも、国に対して、私は、区のほうからも、介護報酬ではなくて、処遇改善交付金という形で、ぜひ対応してほしいということを求めていただきたいと思うのですが。","respondent":"菅野高齢者福祉課長","answer":"今回、そうは言っても、区としては、介護人材が不足しているということを大きく取り上げて、今回、９５ページのところで書かせていただきました居住支援手当については、介護保険の中ではなくて、一般財源でというところで対応させていただいているところです。","voiceIndex":187,"id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは、税金の使い方は、本当に様々無駄遣いというか、介護保険とか、社会保障だろうという、そういう税金の使い方はいっぱいありますので、ぜひとも社会保障の部分で、しっかりと税金を使っていくことは、私は逆に今、求められていると思いますので、区としても、ぜひ求めていただきたいということでお願いしておきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"品川区は、１人当たりの基金が、数年前に調査した結果では、保有率が一番少なかったという部分がありますので、今までもそういった基金を崩して使いながら保険料に当ててきたという経過もありますので、今後、この結果、第九期の保険料が出た段階で。","voiceIndex":189,"id":"exchange-065"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"在宅介護支援センターのケアマネジャーは、品川区のプラス１万円の手当の対象にならないかもしれないということをお伺いしたのですけれども、現時点で、もし品川区の決定事項で分かっていることがありましたら、お教えいただきたいのですが、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"在宅介護支援センターのケアマネジャーが対象ではないのではないかという、その不穏なうわさの根拠が分からないのですけれども、そういったことをどこか説明会でお話ししたとかということも全くございませんので、そういうことは、まだある、ないとはっきりは言えませんけれども。","voiceIndex":192,"id":"exchange-066"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"このパブリックコメントというか、これの２ページの、先ほどご説明もあった「カラダ見える化トレーニング」について、効果があって拡大してほしいというようなご要望があって、非常にいいことなのかなというふうに思っておりまして、そういった中で、やはり自分で通わなくてはいけないというところで、行ってみたいのだけれども、少し足がというか。","respondent":"樫村高齢者地域支援課長、菅野高齢者福祉課長","answer":"ただ、委員からご指摘がありましたとおり、そういった課題も把握はしておりますので、そういった手だてがないかというところは研究してまいりたいというふうに考えます。これは、一応、ケアマネジャーのケアプランでこういった区分がサービスされるものなのですけれども、外出が難しい方が、こういった形の機能訓練をすることによって、外出が少し可能になって、結果、通いのそういった事業に出られる。","voiceIndex":194,"id":"exchange-067"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"やはり他人事と思えないというか、そういうことがありまして、今後、高齢者が増えてきて、サービスが必要になる方が増えるという見込みが出ているのに、こういう状況というのは、やはり介護事務所の経営面が厳しいというあらわれなのではないかというふうに思っておりますので、ぜひその辺は注視していただくというふうに思いますし、今後、２０２４年度で新たに介護報酬が変わりましたし。","respondent":"菅野高齢者福祉課長","answer":"区としては、そういった情報もキャッチしながら、ただ一方で、給付と負担のバランスというところもありますので、そうは言っても、事業者がなくなってしまっては元も子もないというところも見据えながら、そういった事業者の動向など。","voiceIndex":197,"id":"exchange-068"}]},{"id":"topic-05","title":"しながわ健康プラン２１および品川区がん対策推進計画の策定に向けた「健康に関する意識調査」結果報告","agenda":"しながわ健康プラン２１および品川区がん対策推進計画の策定に向けた「健康に関する意識調査」結果報告","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"今年度に策定委員会を両方、年４回と年３回を開催するということなのですけれども、これは別々の委員会が２つつくられるということなのでしょうか。そして、これは傍聴とかも可能だということなのでしょうか。そして、パブリックコメントを実施するというのは、およそいつぐらいになるのか、その点も伺いたいと思います。","respondent":"若生健康課長","answer":"２点目は、傍聴等の公開についてです。委員会の考え方ですけれども、現在、この辺りも含めて運営方法について検討中ですけれども、原則として公開していくような形で考えております。それから、パブリックコメントですけれども、こちらは来年の１月を予定しております。","voiceIndex":204,"id":"exchange-069"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それともう１つ、予算特別委員会で取り上げさせていただいたものなのですけれども、前立腺がんの検診で、行政評価でＤ評価ということで、廃止・終了、そういう評価になったと思うのですけれども、これは、少し時間がなくて途中で最後までできなかったのですけれども、泌尿器科学会としてもガイドラインを出しているし、声明も出していて、前立腺がん検診を、ＰＳＡをやることが死亡率の低下にもつながるし。","respondent":"若生健康課長","answer":"こういったところにつきましても、がん対策推進計画の委員会の中で、専門家の学識の先生ですとか、医師会の先生等も入って議論していく予定ですので、有効性を十分に検証しつつ、実施の可否も含めて検討していきたいと考えています。","voiceIndex":206,"id":"exchange-070"},{"speaker":"鈴木委員","kind":"質問・要望","question":"前立腺がん検診は、本当に周りでもＰＳＡをやって早期に見つかって手術したという方がかなりたくさんいらっしゃいますし、こういう評価をするときは、特に医療関係の部分は、私は専門家の医師会の先生ですとか、泌尿器科の先生ですとか、そういうところのご意見を伺うことが必要ではないかと思いますので、ぜひそうしていただきたいと思いますし、これについては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-071"},{"speaker":"こんの委員","kind":"質問","question":"意識調査の仕方について、参考までに伺いたいのですけれども、無作為抽出で３,０００人の方に送られたということなのですけれども、無作為抽出といっても、ある程度、年齢別というものを見ているのかどうなのか。回答数についても、年齢別でどれぐらいの方たちがご回答いただいているのか。設問の中に年齢というところが入っていればあれなのですけれども、そうしたところを参考までに伺いたいと思います。","respondent":"若生健康課長","answer":"回収率３６％については、目標としてはもう少し高く４０％ぐらいに置いていたのですけれども、若干下回っているということで、そうはいっても、これは委託している統計ですとか、現状、専門業者に聞いたところ、やはり都市部では。","voiceIndex":210,"id":"exchange-072"},{"speaker":"こんの委員","kind":"質問","question":"素案ができていますので、この中身は、いろいろなご意見もあるとは思うのですが、これからパブリックコメントをされるということですので、またそのときに区民の方のご意見等々を伺いながら、この計画がより区民の方の健康増進、また維持といったところ、また、検診率の向上といったところにつながっていくように、これからの取組を見ていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-073"},{"speaker":"筒井委員","kind":"意見","question":"１０年ぐらい、中間見直しがあるとはいえ、１０年来の長い計画なので、区民委員の方の募集人数、これ、２名ではなくて、もう少し増やしてもいいのかなとは思うのですけれども、この募集人数２名とした理由についてお聞かせください。","respondent":"若生健康課長","answer":"そういったところとの全体のバランスも考えまして、区民公募委員については、２名程度が適切なのではないかということで所管として判断したところです。","voiceIndex":214,"id":"exchange-074"},{"speaker":"筒井委員","kind":"質問・要望","question":"分かりました。ぜひ実になる議論をしていっていただきたいと考えております。委託事業者を公募で決めたということで、株式会社創建というところが選定事業者になるのですけれども、この事業者は、２０２０年の中間見直しのときにもやられた事業者の方だと思うのですけれども、事業者に委託して、具体的にどのようなことをやられていくのでしょうか。","respondent":"若生健康課長","answer":"委託事業者の委託業務内容につきましてですが、この健康プラン２１は、１０年間ということで、国の健康増進法に基づいて、市区町村の健康増進計画として指標も定め、計画期間を求められている計画になっておりまして。","voiceIndex":216,"id":"exchange-075"},{"speaker":"やなぎさわ委員","kind":"質問","question":"報告書の８６ページのところなのですけれども、お伺いしたいのが、「この１か月間に不安などがあったか－３０分以上の運動やスポーツをする頻度別」ということで集計があるのですけれども、これは区としての受け止めとして、運動頻度が高いと、ストレスとか、精神的な不安状態に陥りにくいというふうに読み取っていらっしゃるのでしょうか。ご見解を伺います。","respondent":"若生健康課長","answer":"実際、結果については、例えば、ほぼ毎日スポーツをする方については、そういう不安が１か月間ないと答えた方の割合が一番多い結果で、そういった数字が実際に結果としてあらわれたです。","voiceIndex":220,"id":"exchange-076"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そうなると、やはり区民のメンタルヘルス、心の健康という意味で、運動をするような機会とかを推進していきたいというような方針ということでよろしいでしょうか。","respondent":"若生健康課長","answer":"この健康づくりと運動、スポーツは、かなり密接に関連していることから、現行の計画でも取り組んでいるところでありますので、委員おっしゃるとおり、そういった視点を重視して進めていくです。","voiceIndex":222,"id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そういった中で、５０ページにいくのですけれども、運動をほとんどしていない方の理由がここに書いてあって、様々あるのですけれども、ここら辺のことをいろいろ勘案すると、正に来年、品川区で初めて行われるしながわシティランというのは、ジョギングといいますか、非常にいい取組になるのではないかというふうに感じておりまして、つまり、運動しない人の理由のところをいろいろ探ってみると。","respondent":"若生健康課長","answer":"ジョギングも含めまして、運動を習慣づけていることが明らかに精神の健康の増進につながるということは、言われているところでございまして、区を挙げて、しながわシティランのほうもやっていくですので、そういったところを、健康面も一緒にＰＲできるような形で。","voiceIndex":224,"id":"exchange-078"},{"speaker":"やなぎさわ委員","kind":"意見","question":"つまり、しながわシティラン単体で見ると、例えば、事業的に赤字になったとしても、区民が健康になって、医療費の抑制につながったりすると、最終的にはプラスというようなことになると思うので、そういったところも考慮して、品川区が一体になって、横断型でぜひ実施していただければと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":226,"id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6661#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":61240,"voices":229}}]);
